-- ---------------------------------------------------------
-- Arabic descriptions for the startups in the dataset (817 descriptions).
-- Run this once in the Supabase SQL Editor, AFTER migration 0011.
-- Safe to run again: it only fills startup_description_ar of these startups.
-- The English columns are not touched. Startups with no English description
-- are left without an Arabic one too.
--
-- Long English descriptions are translated a little shorter, keeping what the
-- startup does; brand and product names stay in English.
-- ---------------------------------------------------------
update public.startups as s set startup_description_ar = v.ar
from (values
  ('ST_001', 'تساعد Lean الشركات على تحويل الأموال والتحقق من الهويات وفهم الأوضاع المالية للعملاء من خلال منصة واحدة متوافقة مع الأنظمة.'),
  ('ST_002', 'نظام متكامل لإدارة المطاعم ونقاط البيع لتسهيل عملياتك وإدارة المخزون واستقبال الطلبات عبر الإنترنت وزيادة المبيعات.'),
  ('ST_003', 'سلة هي منصة التجارة الإلكترونية الرائدة في المملكة العربية السعودية لإنشاء المتاجر الإلكترونية وإدارتها، وتقدّم حلولًا متكاملة للمدفوعات والشحن والتسويق وتنمية تجارتك الإلكترونية.'),
  ('ST_004', 'الحل الرائد لحسابات ومدفوعات المنشآت الصغيرة والمتوسطة في المملكة. أدِر منتجاتك، وتحكّم في التكاليف، وتابع مبيعاتك لحظة بلحظة، واحصل على تمويل لنقاط البيع لدعم نموك.'),
  ('ST_005', 'تعرّف على أفضل برنامج محاسبة وكاشير لإدارة نشاطك التجاري: حلول متكاملة تجمع الكاشير والمحاسبة والمخزون والفوترة الإلكترونية في نظام واحد.'),
  ('ST_006', 'زد منصتك المتكاملة لإنشاء متجر إلكتروني في دقائق، مع حلول شاملة للدفع والشحن المحلي والدولي وإدارة المخزون والتسويق الفعّال.'),
  ('ST_007', 'تقود Classera قطاع تقنيات التعليم عالميًا بشبكة تضم أكثر من 200 شريك دولي ومحلي حول العالم، وتقدّم مجموعة متكاملة من الخدمات بجودة استثنائية. تحظى بثقة الحكومات والمؤسسات التعليمية والتدريبية، وتُعرف بالتزامها بالتنفيذ على أي نطاق تطمح إليه.'),
  ('ST_008', 'شاليهات وشقق ومزارع ومنتجعات للإيجار وغيرها. استرخِ في مكان إقامة مميز واصنع ذكريات لا تُنسى. احجز الآن واستمتع عبر منصة مرخّصة ومعتمدة.'),
  ('ST_009', 'تربط ساري متجرك أو منشأتك أو منزلك أو فندقك أو مكتبك في السعودية ومصر بشبكة واسعة من موردي وموزعي سوق الجملة في مكان واحد، بأسعار تنافسية ومنتجات متنوعة وأفضل العروض والخصومات، مع توصيل سريع وفي الموعد، والدفع نقدًا أو بالبطاقات، وتتبّع الطلبات والشحنات بضغطة زر.'),
  ('ST_010', 'اشترِ سيارتك من جوالك ومن أي مكان في المملكة.'),
  ('ST_012', 'مرسول وُلد من متاعب الحياة اليومية ليقدّم حلولًا يومية. ماذا لو كان لديك أخ في كل ركن من أركان المدينة؟ من هذا السؤال البسيط والملهم انطلقت فكرة مرسول، مستوحاة من تحديات إنجاز المشاوير اليومية والموازنة بين المسؤوليات، بهدف إنشاء منصة تساعدك في ذلك.'),
  ('ST_013', 'Grintafy هي المنصة الرائدة لاكتشاف مواهب كرة القدم في الشرق الأوسط، وتربط عشاق كرة القدم والطامحين للاحتراف بالأندية والفرص حول العالم. تأسست عام 2019 ووصلت إلى ما يقارب مليوني لاعب. من خلال شراكاتها مع الاتحادات والأندية المحلية والدولية تنظّم اختبارات الأداء وتقدّم التوجيه وتدعم رحلتك نحو الاحتراف، كما تتيح لك الانضمام إلى مباريات كرة القدم في أي وقت ومكان ومع أي شخص.'),
  ('ST_014', 'أكبر تطبيق للادخار الجماعي في المملكة، وحل متكامل للجمعيات المالية (الادخار الدوري بين الأفراد) بكل سهولة.'),
  ('ST_015', 'اكتشف كيف تقود رسن الابتكار الرقمي في قطاعي التقنية المالية وتقنية التأمين في المملكة بحلول ذكية للأفراد والشركات.'),
  ('ST_016', 'متجر لأفضل منتجات التجميل والعناية الشخصية، من مكياج ومنظفات البشرة وغيرها، مع خدمة توصيل سريع إلى جميع أنحاء المملكة.'),
  ('ST_017', 'استعد لاختبارَي القدرات والتحصيلي مع أفضل المدربين في المملكة، عبر دورات شاملة ومكثفة لك ولزملائك.'),
  ('ST_019', 'تدعم PayTabs التجارة الإلكترونية والشركات وشركات التقنية المالية والجهات الحكومية بتطبيق شامل وتنسيق للمدفوعات وبنية تحتية متكاملة. صُنّفت ضمن أفضل 100 شركة تقنية مالية عالميًا.'),
  ('ST_020', 'سهّل عمليات الشحن لديك عبر منصة برمجية مؤتمتة ومتكاملة تربطك بعدة شركات شحن. بسّط شحناتك ووفّر وقتك.'),
  ('ST_021', 'اكتشف حلول Unifonic المدعومة بالذكاء الاصطناعي للارتقاء بتفاعلك مع العملاء، إذ تجمع بين التقنية المبتكرة والتجارب المخصّصة.'),
  ('ST_022', 'Penny AI نظام مشتريات مؤسسي بالذكاء الاصطناعي يبسّط طلبات العروض وأوامر الشراء والموافقات وإدارة الموردين والمدفوعات ضمن نظام موحّد من التوريد حتى الدفع.'),
  ('ST_024', 'ذكاء اصطناعي مؤسسي للقطاعات التي تتطلب أعلى درجات الموثوقية، تثق به المؤسسات المالية والقطاع العام. سيادي بطبيعته، ويقدّمه مهندسون يعملون ضمن فرقك.'),
  ('ST_025', 'أول منصة تمويل شخصي في المملكة مرخّصة من البنك المركزي السعودي (ساما)، تعمل بنموذج التمويل بين الأفراد والتقنية المالية: تمويل سريع دون تحويل الراتب يصل إلى 30,000 ريال، يُودَع خلال 24 ساعة تقريبًا من الموافقة المشروطة، ومتوافق مع أحكام الشريعة الإسلامية.'),
  ('ST_026', 'حلول تمويل جماعي للشركات تصل إلى 7.5 ملايين ريال، وفرص استثمار متعددة بعوائد مجزية للأفراد، تحت إشراف ورقابة البنك المركزي السعودي.'),
  ('ST_027', 'واجهة برمجية قياسية لاستقبال المدفوعات الإلكترونية عبر البطاقات الائتمانية وApple Pay وSTC Pay.'),
  ('ST_028', 'HyperPay بوابة دفع إلكتروني رائدة في المملكة ومنطقة الشرق الأوسط وشمال أفريقيا، موثوقة منذ عام 2014. اقبل مدفوعات مدى وفيزا وApple Pay وغيرها. قدّم الآن.'),
  ('ST_029', 'نقدّم في منصة عناب حلول تعلّم رقمي تمكّن الأفراد والجهات من تطوير المهارات وبناء القدرات عبر برامج تدريبية وفق أفضل الممارسات الدولية.'),
  ('ST_030', 'أدِر بطاقاتك ومعاملاتك وأموالك في مكان واحد.'),
  ('ST_032', 'تبسّط المنصة الإدارة المالية للشركات عبر إدارة المصروفات وبطاقات الشركات والتعويضات وأتمتة المحاسبة في منصة مالية متكاملة للشركات في المملكة.'),
  ('ST_033', 'تخزين وشحن ووصول إلى جميع أنحاء المملكة من منصة واحدة.'),
  ('ST_034', 'استحوذت Tabby على الشركة مؤخرًا.'),
  ('ST_036', 'منظومة متكاملة لأعمال التجميل والعافية: نظام تشغيل لإدارة الحجوزات والموظفين والمدفوعات والمخزون والمواقع الإلكترونية وغيرها في منظومة واحدة. أكثر من 3,500 منشأة في أكثر من 10 دول، وأكثر من 50 مليون حجز و20 مليون فاتورة، ومتوافق بالكامل مع لوائح الفوترة الإلكترونية لهيئة الزكاة والضريبة والجمارك (المرحلتان الأولى والثانية).'),
  ('ST_037', 'قدّم خيارات دفع مرنة كالاشتراكات والأقساط، واجذب مزيدًا من العملاء، واستلم مستحقاتك بسهولة. حل فوترة بسيط وموثوق لأعمال منطقة الشرق الأوسط وشمال أفريقيا.'),
  ('ST_039', 'Dowell منصة تداول اجتماعي إلكترونية تتيح للمستثمرين الاطلاع على المحافظ الاستثمارية للخبراء والاسترشاد باستراتيجياتهم الاستثمارية.'),
  ('ST_040', 'استرجع قيمة مشترياتك في ثوانٍ.'),
  ('ST_041', 'بدأت مُرني عام 2015 كخدمة للمساعدة على الطريق، ثم تطورت إلى منصة شاملة لخدمات السيارات في المملكة تغطي كل ما تحتاجه المركبة. نمونا مع عملائنا وتعلّمنا من الرحلة.'),
  ('ST_042', 'نساعد الشركات على التوظيف بشكل أسرع وأذكى من خلال مجتمع يضم أكثر من مليون باحث عن عمل في أنحاء المملكة.'),
  ('ST_043', 'نستخدم التحليلات المتقدمة والذكاء الاصطناعي لتنمية أثمن أصول منشأتك: بياناتك.'),
  ('ST_044', 'palm.hr برنامج موارد بشرية حديث ومتكامل مصمَّم للمنشآت الصغيرة والمتوسطة في الشرق الأوسط، يدير بيانات الموظفين والحضور والانصراف والرواتب والالتزام بالأنظمة وغيرها بسهولة.'),
  ('ST_045', 'استثمر في صناديق عقارية حصرية في المملكة بدءًا من 500 ريال فقط، مع دخل سلبي منتظم وأرباح خلال 24 إلى 60 شهرًا، متوافقة مع الشريعة ومرخّصة من هيئة السوق المالية (ترخيص رقم 2023-53-5).'),
  ('ST_046', 'أصبحت منشأتك الآن مرتبطة بمنصة فوترة هيئة الزكاة والضريبة والجمارك، وجاهزة لإصدار فواتيرها الإلكترونية.'),
  ('ST_047', 'خدمات لوجستية متكاملة للتجارة الإلكترونية لتوسيع أعمالك: نخزّن منتجاتك ونغلّفها ونوصلها إلى عملائك في أي مكان في العالم.'),
  ('ST_048', 'Taker برنامج طلبات إلكترونية للمطاعم يساعدها على افتتاح فرعها الرقمي عبر موقع وتطبيق للطلبات.'),
  ('ST_049', 'Voom برنامج محاسبة شامل يساعدك على إدارة حساباتك ومخزونك وأصولك وتقاريرك المالية بكفاءة ودقة. جرّبه الآن!'),
  ('ST_053', 'نسهّل عليك الاستثمار عبر بناء محفظتك ومتابعة أدائها وإعادة توازنها واستثمار الأرباح بطريقة رقمية بالكامل.'),
  ('ST_054', 'استئجار السيارات أصبح سهلًا.'),
  ('ST_055', 'اطلب الآن من مطعم عنب بيتي في مكة عبر ذا شفز، مع توفّر التوصيل في جميع أنحاء مكة، وقائمة الطعام والأسعار والصور.'),
  ('ST_056', 'إدارة تضمن بقاء استثمارك متوافقًا مع أهدافك يومًا بعد يوم.'),
  ('ST_057', 'إدارة المبيعات والمشتريات والتقارير والمحاسبة والمخزون والمستودعات والموارد البشرية لقطاعات الصحة والتجزئة والتوزيع.'),
  ('ST_058', 'لبيه الحل المتكامل لتقديم خدمات الرعاية النفسية عن بُعد، عبر جلسات ومحاضرات من مختصين بسهولة وسرية تامة.'),
  ('ST_059', 'تطبيق لصيانة السيارات يقدّم جميع خدمات الإصلاح وتوفير قطع الغيار، مع فريق متخصص وضمان ذهبي وأسعار تنافسية وسهولة في الاستخدام. حمّل التطبيق الآن.'),
  ('ST_062', 'Circlys بديل مبتكر للجمعيات المالية الشهرية التقليدية، وطريقة مرخّصة ومضمونة تساعدك على تحقيق أهدافك بسهولة وراحة بال.'),
  ('ST_063', 'عون لتملّك المنازل بوابتك لاستكشاف أفضل العقارات السكنية في الرياض، مع حاسبة للتمويل العقاري وخيارات من جميع البنوك.'),
  ('ST_064', 'لا تشيل هم الإيجار: قسّم إيجارك السنوي على 12 دفعة شهرية مريحة، ويستلم المؤجر إيجار السنة كاملًا منّا اليوم.'),
  ('ST_065', 'WakeCap نظام للتحكم في المشاريع مدعوم بأجهزة الاستشعار، يتيح رؤية القوى العاملة لحظيًا وذكاءً شاملًا للموقع، ويُستخدم في بعض أكبر المشاريع وأعقدها في العالم، ومنها نيوم وأرامكو والقدية.'),
  ('ST_066', 'نشتري لك المواد التي يحتاجها عملك وندفع لمورّدك مباشرة، وتسدّد أنت بما يناسبك من شهرين إلى 12 شهرًا.'),
  ('ST_067', 'بع واشترِ الجوالات وأجهزة iPhone والحواسيب المحمولة وأجهزة iPad وحتى السيارات، مع ضمان حقك والتوصيل إلى باب منزلك، وبالتقسيط عبر تابي وتمارا.'),
  ('ST_068', 'حوّل كل إشارة من عملائك إلى حل بالذكاء الاصطناعي. تجمع لوسيديا الرصد الاجتماعي والتفاعل عبر جميع القنوات والدعم الذاتي في منصة واحدة لتجربة العملاء.'),
  ('ST_069', 'يوفّر لك تطبيق اثنين مدربًا للسكري وفريقًا متخصصًا لوضع خطة شاملة توازن حياتك مع السكري. حمّل التطبيق اليوم وابدأ رحلتك نحو الصحة والعافية.'),
  ('ST_070', 'منصة تقنية تسهّل تجارة الجملة وتجمع الموردين والمصنّعين والتجار في نظام واحد يمكّنهم من البيع والشراء والتمويل وإدارة الطلبات والفواتير الذكية.'),
  ('ST_072', 'منصة لحجز المواعيد الطبية في تخصصات النساء والولادة والجلدية والعيون والأسنان وغيرها، مع نظام تذكير يقلّل الغياب، وتغطية تأمينية، وتحويل المرضى، والاستفادة من الذكاء الاصطناعي. احجز موعدك الآن.'),
  ('ST_073', '1Pass تطبيق يهدف إلى تحسين العافية وجودة الحياة، باشتراك واحد يغطي أكثر من 400 نادٍ رياضي ونشاط للعافية والرياضة في أنحاء المملكة. حمّل التطبيق واكتشف المزايا!'),
  ('ST_074', 'أكاديمية تعليمية تجمع بين متعة التعليم ومهارته بما يواكب التطور التقني، وتهدف إلى تقديم برامج تعليمية عالية الجودة لمن يرغب في تطوير مهاراته بشكل إيجابي وفعّال ليؤدي الأدوار التي تدرّب عليها.'),
  ('ST_075', 'جلسات تفاعلية مباشرة عبر الإنترنت وحضوريًا مع مرشدين سعوديين لتعلّم اللهجة السعودية وثقافتها الرائعة. تعلّم اللغة، وتعرّف على الثقافة، واستمتع بالسعودية مع Arabius.'),
  ('ST_076', 'منصة أجدر التعليمية تقدّم شروحات المواد والدورات والمحاضرات لطلاب الجامعات السعودية بأسعار مناسبة ومزايا متعددة.'),
  ('ST_077', 'أول منصة إلكترونية لتعليم الخط العربي عبر الإنترنت، يقدّمها نخبة من المحترفين المختارين بعناية لمشاركة خبراتهم.'),
  ('ST_079', 'Ygii منصة سعودية للإهداء ورصد نوايا الشراء، تساعد الأفراد والشركات على جعل الإهداء أكثر عناية وخصوصية واعتمادًا على البيانات. يستطيع الأفراد إنشاء قوائم الأمنيات ومشاركتها ليسهل على الأهل والأصدقاء تقديم الهدايا المرغوبة فعلًا، وتقدّم للشركات حلول هدايا تساعدها على إدارة هدايا الموظفين والعملاء والشركاء بتخصيص أفضل وملاءمة ثقافية وهوية واضحة وأثر قابل للقياس. وتمثّل كل قائمة أمنيات إشارة واضحة على الطلب المستقبلي، ما يجعل Ygii تبني بيانات قيّمة عن نوايا المستهلكين قبل الشراء، وتتجه رؤيتها إلى تحويل الإهداء إلى تجربة أذكى لبناء العلاقات.'),
  ('ST_080', 'تطبيق ومنصة ذكية مدعومة بالذكاء الاصطناعي لربط الشركات بالكفاءات السعودية الشابة، تغطي 62 مدينة في المملكة وبدأت مؤخرًا في مصر.'),
  ('ST_081', 'أفوكادو وجهتك المثالية للحصول على أفضل الخضروات والفواكه والورقيات. تسوّق الخضروات والفواكه عبر الإنترنت في جدة.'),
  ('ST_082', 'نقدّم لك أفضل الأسعار وعروضًا دائمة ومستمرة في تطبيق منزلك!'),
  ('ST_083', 'نظام بيانات مؤتمت ومتكامل مع أنظمة المبيعات والدفع، يمكّنك من الحفاظ على عملائك وزيادة مبيعاتك عبر أدوات مبتكرة ومتعددة.'),
  ('ST_084', 'دفاتر تقدّم حلول تخطيط موارد سحابية متقدمة للإدارة المالية والمبيعات والموارد البشرية، لتحكّم كامل في عملك وأتمتته وتحوّله الرقمي. اكتشف قوة دفاتر الآن.'),
  ('ST_085', 'قدّم على تأشيرتك بسهولة، وابدأ التحضير لرحلتك مع Direct.'),
  ('ST_086', 'منصة إلهام للتعلّم الذكي: حلول تدريب مبتكرة بالذكاء الاصطناعي للمؤسسات.'),
  ('ST_087', 'استبياني في المرحلة الثالثة من أربع مراحل للبناء، بأكثر من 77 ألف سطر برمجي على مدى عامين ونصف، بمعدل 20 ساعة أسبوعيًا؛ استغرقت رحلة البناء نحو 2,600 ساعة في 650 يوم عمل، رافقتها 650 كوبًا من القهوة.'),
  ('ST_088', 'نخدمك ونخدم سيارتك أينما كنت. أول منصة رقمية في الشرق الأوسط تغطي كل ما تحتاجه سيارتك من صيانة وبيع وشراء، مع سوق للسيارات ومزادات، ونفحص لك أي سيارة قبل شرائها ونقدّم لك تقريرًا عنها.'),
  ('ST_089', 'منصة فهيم لتعليم الطلاب عن بُعد بدروس خصوصية فردية مع نخبة من المعلمين، من رياض الأطفال حتى الجامعة، مع خطة تعلّم مخصصة وباقات مرنة.'),
  ('ST_090', 'تقدّم FalconViz خدمات متكاملة لرقمنة الأصول والعمليات باستخدام الطائرات المسيّرة والمعدات المرتبطة بها، مع حلول رقمية كاملة تساعد عملاءها على مواجهة تحديات مشاريعهم وأعمالهم اليومية.'),
  ('ST_091', 'رحلتك مصمَّمة بأفضل وأرخص سعر لك.'),
  ('ST_092', 'دورات فردية لتعزيز التحصيل ومتابعته تلبي احتياجاتك التعليمية، وبرنامج جديد للتأهيل لمقياس الموهوبين يجمع بين تنمية مهارات التفكير العليا والتدريب المكثف على أنواع أسئلة المقياس لضمان تميّز الطلاب ونجاحهم في الاختبار.'),
  ('ST_093', 'نشر ثقافة الابتكار والتصنيع ودعمها لجميع الأعمار في المنطقة العربية عبر منظومة تعليمية متكاملة ومتجر لجميع الاحتياجات.'),
  ('ST_094', 'سواء كنت رائد أعمال طموحًا أو منشأة قائمة، تقدّم جيديا حلول الدفع والأعمال في المملكة بأدوات تناسبك.'),
  ('ST_095', 'تقدّم هبوب للأمن السيبراني خدمات احترافية في المملكة، تشمل تقييم الثغرات واختبار الاختراق والتحليل الجنائي الرقمي ومركز عمليات الأمن المُدار وهندسة الأمن السيبراني والاستشارات. احمِ أعمالك مع خبراء موثوقين في الدفاع السيبراني وإدارة المخاطر الرقمية.'),
  ('ST_096', 'سجّل في هلا يلا وابقَ على اطلاع بأحدث تجارب وفعاليات السياحة والترفيه والرياضة في المملكة.'),
  ('ST_097', 'حراج سوق سعودي يضم كل السلع: حراج للسيارات وحراج للعقار وحراج للأجهزة.'),
  ('ST_099', 'نمكّن المؤسسات من إنجاز أعمالها المعقدة بالذكاء الاصطناعي الوكيلي، وتحويل أصعب عملياتها إلى أتمتة آمنة وقابلة للتحكم.'),
  ('ST_100', 'توصل لك هنقرستيشن طعامك المفضل ومشترياتك من البقالة وغيرها في المملكة. اطلب الآن عبر الإنترنت من جميع المطاعم والبقالات والصيدليات في منطقتك.'),
  ('ST_101', 'أجير منصة تقنية تربطك بمقدّمي خدمات الصيانة والتشغيل في المملكة، مع حلول مخصصة للأفراد والشركات والمتاجر والشركاء ومقدّمي الخدمات.'),
  ('ST_102', 'iDrive أول تطبيق لمشاركة السيارات في المملكة. استأجر سيارة من جوالك يوميًا أو أسبوعيًا أو شهريًا، مع وقود مجاني.'),
  ('ST_103', 'iStoria أفضل تطبيق لتعلّم اللغة الإنجليزية، مع أكثر من 400 كلمة جديدة شهريًا. حمّل التطبيق الآن وابدأ التعلّم.'),
  ('ST_104', 'تقرير تنفيذي يومي يقدّم لك ملخصًا ومختارات من أهم المؤشرات وأفضل المحتوى.'),
  ('ST_105', 'تقدّم لقمتي تجربة طعام مميزة من السوشي الطازج والبرجر وغيرها في المملكة.'),
  ('ST_107', 'برنامج نقاط بيع مرن: كاشير سحابي متكامل يعمل على مختلف الأجهزة ومعتمد من هيئة الزكاة، لإصدار فواتير متوافقة مع ضريبة القيمة المضافة واستلام المدفوعات وإصدار الفواتير الإلكترونية بسهولة.'),
  ('ST_108', 'تحدّث مع نخبة من الخبراء واستفد من خدماتهم عالية الجودة؛ تطبيق يجمعك بخبراء ومختصين في عدة مجالات لزيادة فرص نجاحك.'),
  ('ST_109', 'قرارات أسرع وتشغيل أذكى وصيانة أقل تكلفة لمنشآتك بثقة وذكاء. منصة سعودية ذكية لإدارة المرافق والعقارات توفّر رؤية لحظية لجميع المواقع، وتحوّل فوضى التشغيل إلى نظام متكامل يجمع مهامك ومورديك في مكان واحد، مع تجربة سلسة للمستأجرين والسكان تضمن رضاهم وسهولة التعامل.'),
  ('ST_112', 'اطبع ملفات PDF عبر الإنترنت في المملكة: ارفع الملف واختر مكتبة قريبة، ثم استلمه أو نوصله إليك.'),
  ('ST_113', 'استعد لاختبارات القدرات والتحصيلي والرخصة المهنية واختبار STEP عبر دورات مباشرة ومسجلة ومحتوى تدريبي وملخصات من منصة قدرة، بخبرة تزيد على 16 عامًا.'),
  ('ST_114', 'قوام تمكّن منظومة ريادة الأعمال من العمل بوتيرة أسرع وفاعلية أعلى.'),
  ('ST_115', 'Rain منصة العملات المشفرة الرائدة في الشرق الأوسط ولها عملاء حول العالم، وتتيح لك شراء البيتكوين والإيثيريوم وغيرها من العملات.'),
  ('ST_116', 'رواق منصة عربية للتعليم المفتوح، تقدّم التعليم والتدريب الإلكتروني المستقل، إضافة إلى الاستشارات والخبرات والخدمات التقنية.'),
  ('ST_117', 'منصة رحلتي للرحلات المدرسية: تصفّح واختر الوجهة المناسبة لطلاب مدرستك من أكثر من مئة وجهة مختارة في مجالات وأنشطة متنوعة.')
) as v(id, ar)
where s.startup_id = v.id;

update public.startups as s set startup_description_ar = v.ar
from (values
  ('ST_118', 'نساعد عملاءنا على بناء مدن ذكية بتقنية تراقب شبكات المياه السطحية ومياه الأمطار، وتدعم تخطيط المرونة الحضرية واستدامة الموارد والاستجابة الفعّالة للأزمات.'),
  ('ST_120', 'خبرة تقنية وتدريب متميز ومهارات إدارية فريدة اجتمعت لتنتج منصة تقنية معلومات مسجّلة تتوسع باستمرار، بهدف إثراء قطاع التدريب السعودي بأحدث الحلول الرقمية الفعّالة عبر منصات رقمية تغطي رحلة المتدرب بالكامل من التسجيل حتى التقييم.'),
  ('ST_121', 'ارتقِ بتجربتك الصحية مع منصة صنار الشاملة: احجز المواعيد، وتابع أدويتك، واستفد من خدمات الطب عن بُعد، وأدِر صحتك رقميًا.'),
  ('ST_122', 'يجمع ACGWIN بين وصول منظّم وأنظمة حماية وواجهة سريعة الاستجابة لتقديم تجربة ألعاب إلكترونية أكثر راحة عبر مختلف الأجهزة.'),
  ('ST_123', 'تقدّم Skillers حلولًا لتوظيف الكفاءات السعودية في مختلف التخصصات. انشر وظيفتك مجانًا الآن وابدأ في استقطاب المواهب لشركتك.'),
  ('ST_124', 'منصتك الأولى لمعرفة أسعار قطع غيار السيارات من أكبر تجمّع لوكلاء ومتاجر السيارات في جميع الأسواق، مع تواصل مجاني، وقطع جديدة وأصلية.'),
  ('ST_125', 'تصفّح جميع عروض التجميل والعناية في المملكة مع خصومات تصل إلى 80%، تشمل المساج والسبا والبشرة والأسنان والفيلر والبوتوكس وغيرها.'),
  ('ST_126', 'تلفاز 11 استوديو إعلامي إبداعي سعودي متخصص في المحتوى الترفيهي القريب من المجتمع المحلي.'),
  ('ST_130', 'ورشة بلس تحسّن جودة متطلبات تأمين المركبات وإصلاحها عبر نظام سحابي متكامل، وتقدّم حلول قطع غيار المركبات لشركات التأمين والورش بطريقة ذكية وآمنة.'),
  ('ST_132', 'اكتشف حلول ينمو الرقمية لمتابعة نمو الأطفال وإدارة الحضانات وتأهيل ذوي الاحتياجات الخاصة والتقييمات النمائية.'),
  ('ST_133', 'دورات لتطوير الذات، وعلاج الإدمان، ومراكز التنمية البشرية، وخدمات الإرشاد الأسري، والاستشارات الزوجية والنفسية، والتدريب الشخصي (لايف كوتشينج) عبر الإنترنت.'),
  ('ST_134', 'بلومال المالية منصة استثمار جماعي في الاستثمارات البديلة الخاصة.'),
  ('ST_135', 'LIVSHO منصة مزادات مباشرة وسوق إلكتروني للتسوق المباشر، تتيح للمشترين والبائعين تجربة تجارة تفاعلية واجتماعية مباشرة.'),
  ('ST_136', 'يرقمن تطبيق أجرة أساطيل سيارات الأجرة السعودية بالكامل، ببرمجيات معتمدة من الهيئة العامة للنقل وأجهزة متينة داخل المركبات ومنظومة جاهزة للسيارات الكهربائية مدعومة بشراكات عالمية.'),
  ('ST_137', 'حافظ على الرقابة على سلسلة الإمداد وسلامتها وسهولة الوصول إليها عبر حل سلس ومؤتمت.'),
  ('ST_138', 'في Cipher فريق متخصص من خبراء الأمن السيبراني ملتزم بمساعدة المؤسسات على مواجهة التهديدات الرقمية المعقدة والمتغيرة باستمرار.'),
  ('ST_139', 'نقل أثاث احترافي وآمن مع Smove. احجز نقلك عبر الإنترنت في دقائق بسعر واضح من البداية.'),
  ('ST_140', 'منصة مميزة مصمَّمة لمن يبحث عن سكن مرن ومريح.'),
  ('ST_141', 'استأجر بدلًا من الشراء. تبسّط Kara استئجار الأجهزة: اختر من مجموعة واسعة من الأجهزة المميزة، واستفد من خيارات دفع مرنة ودعم لا مثيل له.'),
  ('ST_142', 'النطاق swc-dent.com نطاق ‎.com سهل التذكر من 8 أحرف متاح للشراء بسعر 195 دولارًا.'),
  ('ST_143', 'Ocean Revive الشركة الاستشارية الرائدة عالميًا في استعادة الشعاب المرجانية، تتعاون مع المنتجعات الفاخرة والمطوّرين الساحليين والعلامات الداعمة للشعاب لبناء أثر بيئي على الشعاب وقياسه وتسويقه على نطاق واسع.'),
  ('ST_144', 'نمكّن الشركات والمهنيين عبر حلول ذكية للإرشاد والتوجيه والتطوير؛ منصة مبتكرة تربط مسؤولي الموارد البشرية والموظفين والخبراء لبناء برامج نمو مهني مخصصة، مع التركيز على القيادة وتطوير المهارات والاستشارات المؤسسية، لتحقيق نجاح مستدام للأعمال وتميّز للأفراد.'),
  ('ST_145', 'ابنِ أنظمة عمل بالذكاء الاصطناعي للعمال وسير العمل والموافقات والفواتير والمدفوعات والعمليات المرنة.'),
  ('ST_146', 'Cybersenshi تؤتمت الأمن السيبراني وتبسّطه كخدمة برمجية.'),
  ('ST_147', 'أبواب.ai شركة سعودية حائزة على جوائز في الذكاء الاصطناعي، تغيّر طريقة تقييم المؤسسات المالية لائتمان المنشآت الصغيرة والمتوسطة في المملكة وتوسيعه. تهدف إلى سد فجوة تمويل المنشآت الصغيرة والمتوسطة البالغة 250 مليار دولار في المنطقة بتحويل البيانات المالية المعقدة إلى رؤى ائتمانية واضحة وقابلة للتفسير، عبر بيانات لحظية وتقارير جاهزة للجهات التنظيمية. أسهمت حتى الآن في معالجة قروض تتجاوز مليار ريال، وتتعاون مع البنوك وشركات التمويل والتقنية المالية والصناديق والجهات التنظيمية.'),
  ('ST_148', 'BuildHop البنية التحتية الرقمية لسلسلة إمداد البناء: ورّد المواد، وأدِر طلبات عروض الأسعار، وتواصل مع أفضل الموردين.'),
  ('ST_149', 'ساهل منصة عقارية تفاعلية تقدّم مؤشرات أسعار العقار والمعلومات والبيانات عن السوق العقاري السعودي باستخدام البيانات المفتوحة والذكاء الاصطناعي وذكاء الأعمال، لتمنح المستخدم شفافية عالية حول مكونات القطاع العقاري واتجاهات السوق.'),
  ('ST_150', 'ادفع إيجارك شهريًا: استأجر الآن وادفع لاحقًا. حوّل إيجارك السنوي إلى 12 دفعة شهرية واستمتع بالمرونة المالية.'),
  ('ST_151', 'استمتع بعروض حصرية وحجز سهل مع تطبيق مبات. حمّله الآن!'),
  ('ST_152', 'تصفّح آلاف العقارات للبيع والشقق للإيجار في الرياض والدمام وجميع مدن المملكة على ديل، من فلل وأراضٍ ومحلات تجارية مع وسطاء معتمدين.'),
  ('ST_153', 'تصفّح شققًا وشاليهات وفللًا موثّقة في الرياض وجدة وغيرها. منصة سعودية بدعم محلي باللغتين العربية والإنجليزية.'),
  ('ST_154', 'منصتك الأولى للاستثمار في صناديق الاستثمار، مرخّصة من هيئة السوق المالية ومتوافقة مع أحكام الشريعة الإسلامية.'),
  ('ST_155', 'كهرباء وسباكة وتنظيف وتكييف: إدارة الفنيين وأوامر العمل والعقود والفواتير.'),
  ('ST_156', 'منصة سعودية تقدّم تجربة تسويقية متكاملة تربط العلامات التجارية بعملائها عبر عروض حصرية ومزادات تفاعلية ومكافآت تعزّز التفاعل والولاء.'),
  ('ST_157', 'تجمع Hero الأساطيل والطلبات والتمويل والقوى العاملة في منصة واحدة مدعومة بالذكاء الاصطناعي.'),
  ('ST_158', 'لاهنت شركة ناشئة سعودية في التقنية الحكومية، تبني طبقة بنية تحتية مدعومة بالذكاء الاصطناعي فوق الأنظمة الحكومية، تحوّل الأنظمة المعقدة إلى سير عمل مؤتمت يتيح التحقق الفوري من الأهلية والامتثال وتنفيذ الخدمات، فتختصر مدة المعاملات بين الشركات والجهات الحكومية من أيام إلى دقائق.'),
  ('ST_159', 'اكتشف فائض الطعام من المطاعم والمقاهي والمخابز وغيرها بخصم يصل إلى 70%. اطلب عبر بركة وساعد في تقليل هدر الطعام في المنطقة.'),
  ('ST_160', 'تطوّر iyris إضافات متقدمة للأغشية والطلاءات والمواد المركّبة.'),
  ('ST_161', 'مزوّد رائد لمقاييس التدفق متعدد الأطوار غير المشعة المدعومة بالذكاء الاصطناعي، بتقنية تثق بها أرامكو السعودية وشركات الطاقة العالمية.'),
  ('ST_162', 'Elevatus نظام التوظيف الأول بالذكاء الاصطناعي الوكيلي للمؤسسات الكبيرة، يؤتمت التوظيف من طلب الوظيفة حتى تهيئة الموظف دون برمجة.'),
  ('ST_163', 'اشترِ مواد بناء عالية الجودة من أفضل الموردين سعرًا في المملكة، واطلب عرض السعر في ثوانٍ، ونوصل المواد إلى متجرك أو مشروعك، مع دفع سهل يساعدك على الاستفادة القصوى من ميزانية مشروعك.'),
  ('ST_164', 'استبدل عشرة اشتراكات بمنصة واحدة مبنية على الذكاء الاصطناعي: الاجتماعات والمعرفة والكتابة والترجمة والمالية وإدارة الملكية. تثق بها أكثر من 24 جهة حكومية. ابدأ مجانًا.'),
  ('ST_165', 'اكتشف برنامجنا المتكامل لإدارة التوصيل والمستودعات لتبسيط عملياتك اللوجستية وتوحيدها.'),
  ('ST_166', 'VistaPRO منصة ذكاء اصطناعي حضري تضع الخصوصية أولًا، للسلامة والأمن والمراقبة والوعي بالموقف في البيئات الخارجية المعقدة.'),
  ('ST_167', 'نقدّم العلاج الطبيعي المنزلي في الرياض على يد أخصائيين مؤهلين وذوي خبرة في التعامل مع مختلف الحالات، ونوجّه كل حالة إلى الأخصائي الأنسب حسب طبيعتها واحتياجات المريض وخبرة الأخصائي.'),
  ('ST_168', 'تساعد Uvera منشآت الأغذية على تقليل الهدر وإطالة مدة الصلاحية وتحسين التتبع ومراقبة سلاسل التبريد لحظيًا بتقنية مدعومة بالذكاء الاصطناعي لسلاسل إمداد الغذاء.'),
  ('ST_171', 'هل تأكل خصومات تطبيقات التوصيل أرباحك؟ مع بلّورة فعّل حملاتك، وتابع أداءك، واسترد التكاليف الضائعة من مكان واحد.'),
  ('ST_172', 'نساعدك في الحصول على أفضل قاعة لمناسبتك، سواء كانت زواجًا أو مولودًا أو معرضًا أو مؤتمرًا وغيرها في المنطقة الشرقية، من قاعات الأفراح والفعاليات إلى قاعات الفنادق.'),
  ('ST_173', 'قارن أفضل عروض التمويل الشخصي والبطاقات الائتمانية وحلول التمويل العقاري في المملكة لعام 2026 مع بنوكي.'),
  ('ST_174', 'مهمتنا تقديم حلول طاقة متطورة مدعومة بالذكاء الاصطناعي تعزّز الاستدامة وتحمي البيئة، ورؤيتنا أن نكون روّادًا في قطاع الطاقة نحو مستقبل مستدام. تقدّم Gasable حلول طاقة متقدمة لأكثر من 1.6 مليون عميل.'),
  ('ST_175', 'مرجعك العقاري الأول للصفقات والمعلومات والخرائط والمؤشرات والتقارير والأخبار العقارية في المملكة، مع أرشيف لأكثر من 10 سنوات من بيانات السوق العقاري السعودي عبر محرك بحث وخرائط.'),
  ('ST_176', 'تأسست الشركة شركةً مساهمة برأس مال 112 مليون ريال، وحصلت على ترخيص هيئة السوق المالية في 21 مارس 2023 لممارسة أنشطة التعامل وإدارة الأصول والحفظ.'),
  ('ST_177', 'نستثمر وندير الأصول ونوزّع الصناديق من مكتبنا في الرياض.'),
  ('ST_178', 'استثمر بدءًا من 1,000 ريال في صناديق عقارية سعودية موثّقة ومتوافقة مع الشريعة. تابع العوائد، واستلم أرباحك، واسحبها، كل ذلك في مكان واحد.'),
  ('ST_180', 'أدِر حساباتك ومدفوعاتك وتمويلك التجاري بسلاسة عبر حلول مالية متطورة.'),
  ('ST_181', 'تقدّم دينار حلول تمويل مرنة متوافقة مع الشريعة الإسلامية للعقار ورأس المال العامل والتوسع.'),
  ('ST_182', 'بدأنا تقديم أدوات تمكين النمو في مايو 2021 بمشروع مستشفى خاص في جدة بقيمة 10 ملايين ريال، ومنذ ذلك الحين أسهمنا بأكثر من 12.5 مليون ريال في التنمية الاقتصادية.'),
  ('ST_184', 'نقدّم للشركات خدمات تأجير سهلة بدفعات شهرية مرنة، ونساعدها على النمو وإدارة الأصول عبر حلول تقنية خاصة.'),
  ('ST_185', 'برنامج ادخار للموظفين يعمل تلقائيًا عبر الرواتب، يساعد شركتك على الاحتفاظ بالكفاءات وتعزيز الرفاه المالي باستثمار متوافق مع الشريعة.'),
  ('ST_186', 'اكتشف الحلول والخدمات المبتكرة من SDM.'),
  ('ST_187', 'FlyAkeed منصة برمجية متكاملة ومنظومة لسفر الشركات، تخصّص تجربة السفر للمؤسسات والمنشآت الصغيرة والمتوسطة، وتؤتمت موافقات السفر وإدارة المصروفات، وتمنح الموظفين مزايا ترفيهية منها خصومات حصرية وخيارات تمويل مرنة لرحلاتهم الشخصية.'),
  ('ST_188', 'Livedin طبقة تشغيل بالذكاء الاصطناعي للعقار في المملكة، تحدد الاستخدام الأعلى قيمة لكل مبنى (إقامات قصيرة، سكن شركات، سكن عمالة، سكن طلاب) ثم تشغّله بالكامل: التسعير والتوزيع والضيوف والعمليات والتراخيص. أكثر من 450 عقارًا قيد التشغيل ونمو بعشرة أضعاف، بدعم من Plug & Play وAntler وMisk وغيرهم.'),
  ('ST_189', 'طوّر منشأتك بمراقبة لحظية مدعومة بالذكاء الاصطناعي للسلامة والأمن والإنتاجية.'),
  ('ST_190', 'وظّف مبرمجين وكفاءات تقنية معتمدة عن بُعد أو في مقر عملك، وابنِ الأنظمة والتطبيقات وحلول الذكاء الاصطناعي مع Squadio.'),
  ('ST_192', 'اكتشف الفعاليات وانضم إليها، وتواصل مع المجتمعات، واستكشف ما يحدث بالقرب منك على Declic.'),
  ('ST_193', 'اشترِ سيارة أحلامك مضمونة ومفحوصة من كارلي. اختر من أوسع تشكيلة للسيارات المستعملة في المملكة، وجرّبها، وأعدها خلال سبعة أيام مع استرداد كامل المبلغ.'),
  ('ST_195', 'تساعد Levers الشركات التي تبيع لشركات أخرى على تقليل المدفوعات المتأخرة وتسريع التحصيل والتخلص من المهام اليدوية عبر متابعة مؤتمتة ومخصصة للعملاء ومدفوعات ومطابقة إلكترونية مبسّطة.'),
  ('ST_197', 'رؤى سهلة عبر تحليلات مُدارة بالكامل. نظّم بياناتك واتخذ قرارات أذكى بسلاسة.'),
  ('ST_198', 'STRABL حل دفع وإتمام شراء متطور للتجارة الإلكترونية والمعاملات الرقمية: إتمام الشراء بنقرة، ومعالجة المدفوعات، والدفع بالبصمة، والدفع لاحقًا، والدفع بعد الاستلام، وروابط الدفع، دون تكاليف استرداد أو اعتراضات.'),
  ('ST_199', 'تجنّب الخسائر والتكاليف الإضافية الناتجة عن إهمال الصيانة الدورية لسيارات أسطولك، عبر جداول متابعة وصيانة دورية بأسعار تنافسية في مراكز الصيانة المعتمدة لدينا.'),
  ('ST_200', 'ظاهر منصة تجارة موحّدة تتيح للشركات بيع المنتجات وإدارة الحجوزات وتشغيل أعمالها من واجهة متجر واحدة.'),
  ('ST_202', 'استمتع بخدمات توصيل فائقة السرعة مع تتبّع لحظي وتعامل احترافي وموثوقية لا مثيل لها في المنطقة.'),
  ('ST_203', 'قسّط مشترياتك المؤهلة بأقساط بنكية متوافقة مع الشريعة عبر بطاقات الراجحي والأهلي والإنماء الائتمانية، عبر الإنترنت وفي المتاجر ومع Apple Pay.'),
  ('ST_205', 'منصة مبتكرة تربط الخبراء في مختلف المجالات بالمستخدمين الباحثين عن استشارة وحلول سريعة وفعّالة عبر جلسات فيديو أو صوت مدتها 10 دقائق.'),
  ('ST_207', 'محطتك الموثوقة لقطع غيار السيارات الأصلية وأفضل القطع والإكسسوارات جودةً في مصر. اشترِ عبر الإنترنت واستلم عند باب منزلك بأفضل سعر.'),
  ('ST_208', 'تستخدم Amplifai Health التصوير الحراري والذكاء الاصطناعي لمساعدة الأطباء على اكتشاف علامات الخطر المبكرة، وتدعم الرعاية الوقائية لصحة القدم السكرية والإصابات الرياضية بكشف تغيّرات الحرارة التي قد تدل على مشكلات ناشئة.'),
  ('ST_209', 'منصة واحدة لتشغيل برامج الولاء والمكافآت والتفاعل للتجار والمؤسسات، ومساعدة الأفراد على استبدال نقاطهم.'),
  ('ST_210', 'BEEMS تعيد تعريف الولاء والتفاعل، حيث تلتقي التقنية بالهدف والمجتمع بالفرص. ليست مجرد منصة بل حركة تربط الناس بالعلامات التجارية بطرق هادفة. انضم إلى مجتمع حصري.'),
  ('ST_212', 'DOO® وكالة سعودية للعلامات التجارية متخصصة في استراتيجية العلامة وأنظمة الهوية البصرية والتقارير السنوية والتصميم التحريري والمطبوعات المؤسسية والمواقع والتجارب الرقمية.'),
  ('ST_217', 'تذاكر جولات ومعالم في مكة والمتاحف والمدن الترفيهية والأحواض المائية، مع خدمات النقل والاستقبال والتوصيل من المطار وجولات في أنحاء المملكة.'),
  ('ST_218', 'إدارة الاشتراكات أصبحت أسهل: زد إيراداتك، وقلّل فقدان العملاء، وحسّن تجربتهم عبر منصة شاملة لإدارة الاشتراكات.'),
  ('ST_219', 'Popsy سوق سعودي سريع النمو للأجهزة الإلكترونية المجدّدة، يجعل الأجهزة عالية الجودة أقل تكلفة وأسهل وصولًا وأكثر استدامة. يتخصص في الهواتف الذكية والإلكترونيات المجدّدة المميزة، ويخضع كل جهاز لفحص دقيق مع ضمان من سنة إلى ثلاث سنوات وسياسة إرجاع خلال 14 يومًا، ويوفّر خيارات شراء مرنة كالتقسيط والتمويل، ويدمج الخدمات اللوجستية والمدفوعات وخدمة ما بعد البيع ليجعل الأجهزة المجدّدة الخيار الأول في المنطقة.'),
  ('ST_220', 'قرى أول تطبيق في الشرق الأوسط يقدّم الخدمات والاستشارات الطبية عن بُعد، مع أطباء ومختصين متاحين على مدار الساعة لخدمتك وخدمة عائلتك.'),
  ('ST_221', 'حلول تمويل ذكية ومرنة للأفراد والشركات لتحقيق أهدافك بثقة.'),
  ('ST_222', 'أنشئ منصتك التعليمية في دقائق مع سيان: رفع الدورات المسجلة والبث المباشر، وإدارة الطلاب، وبوابات الدفع الإلكتروني، والشهادات المعتمدة، وأدوات ذكاء اصطناعي متكاملة.'),
  ('ST_223', 'أنشئ متجرك الإلكتروني مع متجرة، منصة تجارة متكاملة تشمل المتجر وتطبيق الجوال ونقاط البيع والدفع والشحن.'),
  ('ST_224', 'مراسلة ومكالمات فيديو ومشاركة ملفات واستضافة تضع الخصوصية أولًا. مبنية في أوروبا، وتبقى بياناتك ملكك دائمًا.'),
  ('ST_225', 'بلند لإدارة طلبات تطبيقات التوصيل من شاشة واحدة: قبول الطلبات، وإضافة الأصناف، ومتابعة التقارير، وتحكّم كامل في مكان واحد.'),
  ('ST_226', 'أدِر أعمال المقاولات بذكاء أكبر مع حسابات: من المشاريع إلى الالتزام بالأنظمة، في منصة تخطيط موارد واحدة مصمَّمة للمقاولين السعوديين.'),
  ('ST_231', 'أنشئ النماذج وصمّمها وانشرها واجمع الردود عبر أداة بناء سهلة ومساعد ذكي.'),
  ('ST_232', 'اكتشف حلول تخطيط موارد سحابية تناسب احتياجات عملك، وخصّص نظامك وحسّن عملياتك بسهولة. اطلب عرضًا تجريبيًا الآن.'),
  ('ST_234', 'نتّو منصة لإدارة رأس المال البشري مصمَّمة لتلبية احتياجات إدارات الموارد البشرية وتحقيق أهدافها الاستراتيجية، آمنة ومتوافقة مع نظام العمل السعودي.'),
  ('ST_235', 'منصة سعودية لتقنيات الإعلان وإعلام التجارة تربط الناشرين وتجار التجزئة والعلامات التجارية والوكالات: العينات الإلكترونية والإعلانات المبرمجة وشراء الوسائط والإعلانات داخل المتاجر وخارجها.'),
  ('ST_236', 'عائلة eCopter المعيارية: طائرات كهربائية متطورة للإقلاع والهبوط العمودي للجيل القادم من التنقل الحضري.'),
  ('ST_238', 'حسّن تجربة عملائك مع برنامج خدمة العملاء من مقسم المدعوم بالذكاء الاصطناعي: أتمتة مهام الدعم والمبيعات، وتجارب سريعة وقريبة من التعامل البشري مع وكيل ذكي يتحدث العربية.'),
  ('ST_240', 'نصمّم ونطوّر منصات وتطبيقات سحابية متكاملة، من الفكرة حتى الإطلاق والتشغيل، تخدم آلاف المستخدمين وتحقق أثرًا ملموسًا لأعمالك.'),
  ('ST_241', 'أوفر منصة للتفاعل مع العملاء والتجارة المحادثية مدعومة بالذكاء الاصطناعي، تجمع واتساب ووسائل التواصل والمكالمات وإدارة علاقات العملاء والطلبات والتوصيل في مكان واحد، لتتحول كل محادثة مع العميل إلى نتيجة أسرع وأذكى.'),
  ('ST_242', 'منصة حوكمة ومخاطر وامتثال بالذكاء الاصطناعي لمعايير ISO 27001 وSOC 2 والهيئة الوطنية للأمن السيبراني ونظام حماية البيانات الشخصية في المملكة. أتمت الامتثال وأدِر المخاطر واحجز عرضًا تجريبيًا مجانيًا.'),
  ('ST_243', 'حلول أساسية لنجاحك التسويقي.'),
  ('ST_244', 'منصة رياضية تقنية يقودها تنفيذي بخبرة تزيد على 12 عامًا في قيادة التقنية الرياضية والشركات الناشئة، مقرها الرياض.')
) as v(id, ar)
where s.startup_id = v.id;

update public.startups as s set startup_description_ar = v.ar
from (values
  ('ST_245', 'مجموعة من حلول الذكاء الاصطناعي لبناء عقول رقمية ذكية واستخدامها وتوسيع نطاقها في العمل والحياة.'),
  ('ST_247', 'Taskershub منصة سوق احترافية للعمل الحر بمزايا متقدمة ترتقي بأعمالك، وتجمع جميع أنواع الخدمات الرقمية في منصة واحدة متكاملة.'),
  ('ST_249', 'بِع أكثر ونمِّ أعمالك بإتاحة خيار «اشترِ الآن وادفع لاحقًا» لعملائك من الشركات عند الدفع.'),
  ('ST_250', 'نصنع المعجزات بالألعاب 🎮.'),
  ('ST_251', 'حل متكامل مصمَّم لتبسيط تنمية أعمالك، من التسويق والمبيعات إلى الاحتفاظ بالعملاء.'),
  ('ST_252', 'حلول تمويل للشركات في المملكة لدعم السيولة والنمو، بخيارات تمويل مرنة تشمل رأس المال العامل وتمويل الفواتير لتلبية احتياجات أعمالك.'),
  ('ST_253', 'تمكين ذوي الإعاقة نحو حياة أفضل.'),
  ('ST_254', 'خدمات استشارات عمالية مؤتمتة بشأن عقود العمل والإجراءات المرتبطة بها في المملكة العربية السعودية.'),
  ('ST_255', 'حساب Adres على إنستغرام: صور ومقاطع فيديو التطبيق.'),
  ('ST_256', 'احجز رحلات القوارب والفعاليات والدخول إلى الشواطئ الخاصة مع Wave6Wave، مع حجز إلكتروني آمن وتأكيد فوري وتجارب بحرية فريدة.'),
  ('ST_257', 'هل تأكل خصومات تطبيقات التوصيل أرباحك؟ مع بلّورة فعّل حملاتك، وتابع أداءك، واسترد التكاليف الضائعة من مكان واحد.'),
  ('ST_258', 'ابحث في مخزون الفنادق المعتمدة واحصل على تأكيد فوري بعد الدفع.'),
  ('ST_259', 'منصة تقنية مالية متكاملة للمنشآت الصغيرة والمتوسطة: تابع التدفق النقدي، وأدِر المصروفات، والتزم بالأنظمة عبر أدوات آمنة للمصرفية المفتوحة.'),
  ('ST_260', 'Swarm Robotics مزوّد رائد لحلول الأتمتة الصناعية والروبوتات في المملكة. اكتشف خدماتنا وخبراتنا وشركاءنا.'),
  ('ST_262', 'احجز سيارتك المستأجرة في المملكة مع Go Steer: إيجار يومي وأسبوعي وشهري من الاقتصادية إلى الفاخرة، مع توصيل مجاني. حمّل التطبيق الآن.'),
  ('ST_263', 'بعقد شحن واحد تستطيع بدء أعمالك وإدارتها وتنميتها، وشحن الطرود المحلية والدولية من لوحة تحكم واحدة.'),
  ('ST_264', 'تجاوز البحث البسيط: ادعم القرارات الحاسمة، وأنشئ تجارب تعلّم تفاعلية، وابنِ تطبيقات أذكى بالذكاء الاصطناعي الأساسي من Slangit.'),
  ('ST_265', 'اكتشف قمصان Patrah الرجالية القطنية 100%: نقوش زهرية وتراثية وكالامكاري، وأزياء المناسبات وقمصان الشاطئ، براحة وأناقة لا تزول.'),
  ('ST_266', 'محطات Aquivio لترطيب الجسم تقدّم مياهًا قلوية غنية بالهيدروجين بنكهات مخصصة للشركات والأندية الرياضية والفنادق، لترطيب أفضل واستدامة قابلة للقياس.'),
  ('ST_268', 'Trivers منصة توظيف بالذكاء الاصطناعي تساعد الشركات على التوظيف بشكل أسرع وأذكى عبر الترشيحات الموثوقة والأتمتة الذكية.'),
  ('ST_269', 'أحدِث نقلة في التعلّم بالذكاء الاصطناعي، فكل طالب يستحق تعليمًا مخصصًا له.'),
  ('ST_270', 'اكتشف واحجز واستكشف وجهات جديدة للمغامرة.'),
  ('ST_271', 'فطافيط تطبيق مدفوعات عائلي يركّز على تعليم الأطفال الادخار والاستثمار داخل التطبيق.'),
  ('ST_272', 'تمنح QBIT المؤسسات السعودية منصة محكومة لذكاء الأعمال والقرارات وأتمتة سير العمل وذكاء المواقع والمصرفية المفتوحة ونشر الذكاء الاصطناعي السيادي.'),
  ('ST_273', 'منصة ولاء مؤسسية لتقسيم العملاء وأتمتة الحملات والمكافآت، مصمَّمة للأعمال متعددة الفروع وعالية الحجم.'),
  ('ST_274', 'اتبع إرشادات الموقع، وأرسل الدفعة، وابدأ العمل! ونحن نتولى الباقي.'),
  ('ST_276', 'يجعل تقسيم المصاريف الجماعية عادلًا وسريعًا وبلا عناء.'),
  ('ST_277', 'ازرع طريقك نحو الحياد الكربوني وتحقّق من أثرك لحظيًا. تمكّن Netzero الشركات من تحقيق أهداف الاستدامة عبر شراكات زراعة الأراضي ومشاركة المجتمع.'),
  ('ST_279', 'GuestNa تطبيق للسياحة في المملكة العربية السعودية.'),
  ('ST_283', 'اكتشف واجهات Spare البرمجية الرائدة لمعلومات الحسابات وبدء المدفوعات، المصمَّمة لبناء منتجات مالية قوية.'),
  ('ST_284', 'اكتشف كيف نعيد ابتكار رحلة السيارات للمستهلكين والمموّلين والوكلاء والمصنّعين ومقدّمي خدمات السيارات.'),
  ('ST_286', 'تقدّم منصة عزّام حلولًا متكاملة لإدارة المؤتمرات والمعارض والفعاليات الكبرى بأعلى معايير الجودة والاحترافية.'),
  ('ST_288', 'Navides المنصة الرائدة التي تساعد الشركات والموظفين على النجاح في عالم المنافسة التجارية السعودي.'),
  ('ST_289', 'وكلاء صوتيون بالذكاء الاصطناعي، وتحليلات مراكز الاتصال، والتفريغ النصي وتحويل الكلام إلى نص للبنوك وشركات الاتصالات في المنطقة، بفريق يضم أكثر من 86 خبيرًا في الذكاء الاصطناعي العربي.'),
  ('ST_290', 'منصة مدفوعات متكاملة للمدارس والمقاصف والأكاديميات والشركات في المملكة: نقاط بيع، ومتجر رقمي، ومحفظة، واشتراكات، وحضور.'),
  ('ST_291', 'يشتري آجل مواد عملك ويدفع للموردين مباشرة. احصل على قدرة شرائية متوافقة مع الشريعة تصل إلى 4 ملايين ريال، وسدّد خلال 2 إلى 12 شهرًا.'),
  ('ST_292', 'Ossus أول منصة ذكاء اصطناعي سيادية تنجز أعمال الأمن والقانون والامتثال بسرعة الآلة وبمستوى تحليل يرقى لمتطلبات الجهات التنظيمية. نموذجها اللغوي الخاص «حارس» مدرَّب على فهم أعباء الشركات وخياراتها، ويوفّر جمع الأدلة آليًا وتحليل الفجوات لحظيًا وتقارير جاهزة للجهات التنظيمية، ما يقلّل العمل اليدوي بنسبة 60-85% ومدة دورات التدقيق بنسبة 60-80%.'),
  ('ST_293', 'نسعى لقيادة مستقبل أمن الأجهزة المتصلة في الشرق الأوسط وخارجه، مستفيدين من الذكاء الاصطناعي والخبرة التقنية العميقة لبناء بيئات رقمية أكثر أمانًا وذكاءً تحسّن الحياة دون المساس بالخصوصية أو الثقة.'),
  ('ST_294', 'شبكة للمتداولين بناها متداولون: شبكة اجتماعية ذكية قائمة على ثقافة التعلّم والتعاون.'),
  ('ST_295', 'حوّل فكرتك إلى تطبيق في دقائق! بنقرة واحدة تحصل على تطبيق مصغّر بالذكاء الاصطناعي وخطة تحليل وقصة مستخدم واضحة.'),
  ('ST_297', 'منصة لربط الشركات الناشئة بالمستثمرين وفرص التمويل.'),
  ('ST_298', 'مستشارون وباحثون هجوميون ومدققون ومزوّدو تقنية: خبرات متقدمة في الأمن السيبراني بمجالات وعقليات متنوعة تساعدك على تقديم أفضل أمن سيبراني ممكن بشكل أكبر وأسرع وأفضل.'),
  ('ST_300', 'أول منصة تمويل فردي مباشر في المملكة.'),
  ('ST_301', 'Ofintech منصة مدعومة بالذكاء الاصطناعي للإدارة المالية المؤتمتة، تقدّم رؤى حول الإنفاق والتدفق النقدي والاستثمارات مع وصول سحابي، وتعزّز الكفاءة والدقة واتخاذ القرار لمساعدة الشركات على تحسين مواردها ونموها المالي.'),
  ('ST_302', 'تقدّم راوية دروسًا فردية خصوصية في اللغة العربية مع معلمين ذوي خبرة، مصمَّمة وفق أهدافك التعليمية.'),
  ('ST_303', 'نمكّن نموذج أعمال مستدامًا وقابلًا للتوسع بإتاحة حصول المشترين على ما يريدون بتقسيم مبلغ الفاتورة على أقساط دون فوائد أو رسوم.'),
  ('ST_305', 'السحابة الطبية منصة تتيح لك الرعاية العاجلة على مدار الساعة طوال أيام الأسبوع.'),
  ('ST_306', 'نهدف إلى تعزيز عافية عائلتك وسعادتها عبر العلم الحقيقي والمكونات الطبيعية. اكتشف لماذا يعتمد قرابة مليون منزل على First Day كمنتج يومي أساسي.'),
  ('ST_307', 'مبيت منصة مرخّصة من وزارة السياحة السعودية لتأجير الشقق والشقق ذات الدخول الذاتي والشاليهات البحرية والفلل والمزارع والمخيمات في المملكة عبر تطبيق سهل.'),
  ('ST_308', 'العناية الفاخرة بسيارتك تبدأ من هنا.'),
  ('ST_309', 'aiia طبقة سياق ومساحة محادثة تستبدل شاشات أنظمة تخطيط الموارد بعمليات أعمال محكومة.'),
  ('ST_310', 'يجمع تطبيقنا بين التسوق والتواصل الاجتماعي، ليتيح لك اكتشاف المنتجات وشراءها بسهولة وأمان سواء كنت بائعًا أو مشتريًا.'),
  ('ST_311', 'شركة تقودها مؤسستها ورئيستها التنفيذية، مقرها دبي.'),
  ('ST_312', 'نسق: سافر بذكاء وبما يناسب ميزانيتك.'),
  ('ST_315', 'تعرّف على منتجات TechieMatter لتوظيف الكفاءات التقنية، وتشمل أربع خدمات رئيسية: التوظيف التقني، والتقييمات التقنية، والمقابلات التقنية، وتهيئة الموظفين.'),
  ('ST_317', 'رفيق رحلات بالذكاء الاصطناعي للسيّاح: تحدّث مع HiGem لتحصل على ردود فورية على مدار الساعة بلغتك لتستمتع برحلتك، مجانًا ودون إعلانات مضللة.'),
  ('ST_319', 'أصول مركبات مرمّزة رقميًا في برلين وبوخارست ودبي: سيارات حقيقية تحقق إيرادات تشغيلية حقيقية، بدءًا من 100 دولار.'),
  ('ST_322', 'سعودي وتبحث عن دخل سريع؟ طوّر مهاراتك واشحن محفظتك بالساعة 💪 ولديك نشاط تجاري وتريد موظفًا مرنًا؟ نقول لك: أبشر.'),
  ('ST_324', 'ميلا لتنسيق المناسبات في المملكة: أعياد الميلاد والتخرج والخطوبة والأمسيات الرومانسية في مطاعم وأماكن مختارة بعناية.'),
  ('ST_325', 'منصة شاملة لتجربة التعلّم وإدارة الكفاءات. مع تسارع التغيير أكثر من أي وقت مضى، يطلق فريقك المستقبلي إمكانات منشأتك، ونحن ندعم رحلتك نحو الازدهار.'),
  ('ST_326', 'انضم إلى أكثر من 500,000 ممارس صحي موثّق يطوّرون كفاءاتهم السريرية عبر منظومة تعليمية معتمدة ومتميزة في المملكة.'),
  ('ST_327', 'اكتشف Activide، التطبيق الرائد لعرض الفيديوهات التفاعلية في متجرك. حسّن تجربة العملاء بتقنية تسويق مبتكرة وزِد مبيعاتك. جرّبه الآن!'),
  ('ST_328', 'فتنس منصة رقمية متخصصة في اشتراكات الوجبات الصحية، تربط العملاء بمطاعم متنوعة تقدّم وجبات صحية.'),
  ('ST_329', 'اشتراكات غداء العمل أو وجبات اليوم الكامل من أفضل المطاعم. اطلب مرة واحدة، وكل يوم من مطعم مختلف، ونوصل لك يوميًا إلى باب منزلك.'),
  ('ST_330', 'CLST رائدة في سوق إقراض الأصول المشفرة للمؤسسات، تساعد المُقرضين المؤسسيين على تحقيق العوائد.'),
  ('ST_333', 'تربط رِفد المستثمرين العالميين بأسواق غير مستغلة، وتحدث نقلة في توريق الذمم المدينة بتقنية متطورة.'),
  ('ST_334', 'أداة بسيطة وقوية تتيح لك التحكم في جميع شاشاتك من مكان واحد، للمطاعم والمقاهي والمساجد وغيرها.'),
  ('ST_335', 'اعرف قيمة أعمالك الفنية. يصعب على سوق الفن خدمة الراغبين في اقتناء الأعمال الفنية، وتعالج قنطرة ذلك بدءًا من ذكاء التسعير، لجيل الثروة القادم في الخليج.'),
  ('ST_337', 'مكتب محاسبة سعودي يقدّم خدمات متكاملة تشمل مسك الدفاتر والتقارير المالية والرواتب والإقرارات الضريبية وحسابات الشركات، بحلول دقيقة تساعد قادة الأعمال على تحقيق النجاح المالي.'),
  ('ST_339', 'ربائد منصة سحابية مشتركة بين المنشآت تسهّل التعاون في قطاع البناء بين ملّاك المشاريع والاستشاريين الهندسيين والمقاولين، عبر رقمنة التقديمات والموافقات والطلبات، لضمان رؤية موحّدة وسلامة البيانات وتسليم أسرع للمشاريع من خلال سير عمل مؤتمت ونماذج محلية.'),
  ('ST_340', 'اكتشف شبكتنا الواسعة من الجامعات الشريكة، وتواصل مع مجتمعنا العالمي من سفراء الطلاب.'),
  ('ST_342', 'صمّم رحلة عميلك من أول تسجيل اهتمام بالعقار حتى التسليم.'),
  ('ST_343', 'صادق منصة التوقيع الإلكتروني والتوثيق المعتمدة في المملكة: وقّع العقود والمستندات نظاميًا، وتحقق من الهوية وفق متطلبات «اعرف عميلك»، وأدِر مستنداتك بأمان.'),
  ('ST_344', 'تطبيق معاك للرعاية الصحية الشاملة، تطبيق متكامل للطب عن بُعد.'),
  ('ST_345', 'Sharkforce منصة مبنية على الذكاء الاصطناعي تجيب عن السؤال الذي يطرحه كل مدير: كلّفت بالمهمة، لكن هل أُنجزت فعلًا؟'),
  ('ST_346', 'يواجه المستثمرون في المراحل المبكرة صعوبة في العثور على الشركات الناشئة الواعدة وفرزها، وتوفّر جري وصولًا حصريًا إلى شركات ناشئة سعودية موثّقة وفرصًا للاستثمار المشترك مع صناديق رأس المال الجريء والمستثمرين الملائكيين المعروفين.'),
  ('ST_347', 'اسم مستخدم واحد لجميع حساباتك البنكية والرقمية.'),
  ('ST_348', 'Clean Basket تطبيق لخدمات الغسيل والكيّ، متوفر على متجر التطبيقات.'),
  ('ST_350', 'MENA Cashback منصة مكافآت رقمية تتيح للمستخدمين في الشرق الأوسط وشمال أفريقيا الحصول على استرداد نقدي وخصومات وعروض حصرية عند التسوق عبر الإنترنت، بالشراكة مع أكثر من 2,000 علامة تجارية إقليمية وعالمية عبر الموقع والتطبيقات وإضافات المتصفح. يمكن سحب المبالغ عبر التحويل البنكي أو PayPal أو بطاقات الهدايا أو التبرع للجمعيات الخيرية، كما تقدّم حلًا للشركات بعلامتها الخاصة لدمج الاسترداد النقدي والمكافآت في منصاتها عبر واجهة برمجية.'),
  ('ST_351', 'Net Zero Build منصة رقمية تساعد المطوّرين العقاريين على تقليل الأعباء الإدارية والتكاليف المرتبطة بالشهادات البيئية للمباني.'),
  ('ST_352', 'احجز رحلات الغوص والإقامة على القوارب ودورات الغوص في المملكة والبحر الأحمر وخارجها، واكتشف مراكز الغوص والمدربين المعتمدين على EscaVida.'),
  ('ST_353', 'ولاء بلس المنصة الرائدة لمكافآت الموظفين وبرامج الولاء، عزّز ولاء موظفيك وسعادتهم بحلول مبتكرة ومزايا مالية وصحية تسعدهم في بيئة العمل.'),
  ('ST_354', 'Sellershook من TeqBoost نوع جديد من أسواق التجارة الإلكترونية يضع احتياجات المشتري أولًا، ويعزّز الأمان والثقة في الشبكة بأكملها.'),
  ('ST_355', 'Cepro شركة تقنية متخصصة في حماية العلامات التجارية، من المواقع الإلكترونية إلى منصات التواصل الاجتماعي. يعمل نظامها المدعوم بالذكاء الاصطناعي على مدار الساعة لمسح الإنترنت ومنصات التواصل واكتشاف أي انتحال أو تعدٍّ على العلامة، وينبّه أصحابها فورًا لاتخاذ إجراء سريع لحماية سمعتهم وهويتهم. Cepro ليست مجرد مزوّد خدمة، بل شريك موثوق في تأمين علامتك والبقاء متقدمًا على التهديدات.'),
  ('ST_357', 'تساعد Mata Logistic المطارات على تحسين استلام الأمتعة بتجميعها حسب رقم الحجز وتسليمها بإرشاد، لتقليل الازدحام عند الوصول وتسريع التسليم والتكامل مع العمليات القائمة.'),
  ('ST_358', 'منصة طبية مدعومة بالذكاء الاصطناعي تربط المرضى بأفضل الأطباء في الأردن والسعودية، مع تشخيص أولي للأعراض وبحث ذكي باللغة الطبيعية.'),
  ('ST_359', 'منصة لكشف الاحتيال لحظيًا وأتمتة الامتثال للمؤسسات الرقمية في المملكة ودول الخليج، توقف الجلسات الخطرة قبل تفاقمها.'),
  ('ST_360', 'تحوّل «أقصر» أفكار أكثر الكتب مبيعًا في العالم إلى ملخصات صوتية ونصية قصيرة في دقائق. ابدأ التجربة مجانًا.'),
  ('ST_362', 'HAL ERP نظام متكامل لتخطيط موارد المؤسسات بخبرة محلية مثبتة في تطبيق هذه الأنظمة وغيرها. أتمت المهام المتكررة، وتواصل وخطط بشكل أفضل، ونظّم عملك وأدِره بنظام بسيط وفعّال.'),
  ('ST_363', 'أصدر البطاقات، وأدِر المدفوعات، وراقب المصروفات والموافقات، في منصة واحدة مصمَّمة لكل فريق.'),
  ('ST_365', 'بيت برمجيات سعودي من الخبراء يحوّل الأفكار الطموحة إلى منتجات رقمية مؤثرة.'),
  ('ST_366', 'بيت برمجيات سعودي من الخبراء يحوّل الأفكار الطموحة إلى منتجات رقمية مؤثرة.'),
  ('ST_367', 'اكتشف أحدث حلولنا في استخبارات التهديدات وإجراءات الأمن الاستباقية، المصمَّمة لحماية أعمالك من أخطر تهديدات الإنترنت المظلم.'),
  ('ST_368', 'بيت برمجيات سعودي من الخبراء يحوّل الأفكار الطموحة إلى منتجات رقمية مؤثرة.'),
  ('ST_369', 'بيت برمجيات سعودي من الخبراء يحوّل الأفكار الطموحة إلى منتجات رقمية مؤثرة.'),
  ('ST_370', 'انسَ التنقل بين أدوات الإنتاجية، وركّز على ما يهم.'),
  ('ST_371', 'ائتمان سريع للمخزون للتجار السعوديين، ومدفوعات مضمونة وخالية من المخاطر للموردين.'),
  ('ST_372', 'كل ما تحتاجه في مكان واحد: عروض على ما ينقصك والخدمات الأساسية التي تحتاجها كل يوم.'),
  ('ST_374', 'Rology الشركة الرائدة في الشرق الأوسط وأفريقيا في الأشعة عن بُعد بمساعدة الذكاء الاصطناعي، وتشغّل منصة أشعة حاصلة على موافقة FDA. تأسست عام 2017، وتساعد المستشفيات ومراكز الأشعة والأنظمة الصحية على تجاوز نقص أطباء الأشعة وتأخر التقارير عبر شبكة تضم أكثر من 300 طبيب أشعة خبير، بتقارير سريعة ومتخصصة في 8 أنواع من التصوير و12 تخصصًا دقيقًا، مع أدوات ذكاء اصطناعي وتشغيل على مدار الساعة. قدّمت أكثر من 1.6 مليون تقرير لأكثر من 400 مستشفى في 13 دولة، ولها مكاتب في السعودية ومصر وكينيا.'),
  ('ST_376', 'تمكّنّا من فحص عقارات تتجاوز قيمتها السوقية 100 مليار ريال سعودي عبر شبكة عين الواسعة من المهندسين وثقة عملائنا.')
) as v(id, ar)
where s.startup_id = v.id;

update public.startups as s set startup_description_ar = v.ar
from (values
  ('ST_377', 'معلومات موثّقة عن الخليج للمؤسسين الذين يتوسعون في أسواق الخليج الست: المستثمرون والشركات الناشئة والمنح والبرامج والمجتمع.'),
  ('ST_378', 'شريك للتحول الرقمي مقره أبردين: برمجيات مخصصة وبلوك تشين ووكلاء ذكاء اصطناعي وتقنيات الواقع المعزز والافتراضي للشركات الناشئة والمنشآت الصغيرة والمتوسطة والمؤسسات في اسكتلندا والمملكة المتحدة.'),
  ('ST_379', 'من الحصول على التمويل إلى تطوير منتجات متطورة، نرشدك في كل خطوة من رحلة نموك.'),
  ('ST_381', 'حوّل المستندات الورقية إلى أنظمة رقمية قوية بإرشاد من الذكاء الاصطناعي، مع التكامل مع أنظمة إدارة العملاء وتخطيط الموارد ودعم مخصص بمشاركة الشاشة.'),
  ('ST_382', 'شركة ناشئة لديها صفحة على LinkedIn.'),
  ('ST_384', 'اختبر مستقبل التداول المؤتمت مع Bots Technology، وتحكّم في مستقبلك المالي عبر منصة الاستشارات الآلية. ابدأ الاستثمار الذكي اليوم ودع خدماتنا تعمل من أجلك.'),
  ('ST_385', 'تقدّم راوية دروسًا فردية خصوصية في اللغة العربية مع معلمين ذوي خبرة، مصمَّمة وفق أهدافك التعليمية.'),
  ('ST_386', 'منصة ذكية تعاونية لإدارة المسار المهني، تجمع الطلاب والجامعات والمنشآت في بيئة رقمية واحدة للتدريب وتطوير المهارات والتوظيف.'),
  ('ST_387', 'احصل على وسيط معتمد من منصة إيجار في ثلاث دقائق وأنت في مكانك دون مكتب، مناسب للضمان الاجتماعي وحساب المواطن، والدفع بعد الاطلاع على العقد.'),
  ('ST_388', 'خدمات تصميم داخلي احترافية في المملكة، نصمّم مساحات مبتكرة وعملية وأنيقة لاحتياجات أعمالك. حوّل مساحة عملك اليوم!'),
  ('ST_393', 'يقدّم Locate أفضل المطاعم والمتاجر بين يديك: تصفّح القوائم، واكتشف مفضلاتك الجديدة، واطلب بسهولة في تطبيق واحد.'),
  ('ST_394', 'منع الاحتيال وذكاء الامتثال بالذكاء الاصطناعي.'),
  ('ST_395', 'منصة مصروفات للشركات مرخّصة من البنك المركزي السعودي بثلاثة منتجات: بطاقات الأساطيل للتحكم في الوقود والصيانة، وبطاقات المشتريات لمدفوعات الموردين، والعهدة النقدية الرقمية للاستغناء عن التعامل النقدي، مع منع الاحتيال بالذكاء الاصطناعي واسترداد نقدي 2% دون حد أقصى.'),
  ('ST_396', 'برنامج إلكتروني بسيط ومرن وقابل للتوسع لإدارة أساطيل النقل.'),
  ('ST_397', 'حذر شركة سعودية للأمن السيبراني تحمي المؤسسات والأفراد من التهديدات السيبرانية، وتقدّم حلولًا متقدمة منها مراقبة الإنترنت المظلم وتحليل المصادر المفتوحة لكشف التسريبات والاختراقات المحتملة، وتتخصص في تحليل المخاطر وتقديم الاستشارات، وتسعى لرفع الوعي بأهمية الأمن السيبراني وتقديم خطط استجابة فعّالة للهجمات.'),
  ('ST_398', 'خدمات متكاملة تشمل التأهيل والعلاج المنزلي وجلسات الإرشاد وتدريب الأسرة وبرامج خاصة مثل التدريب على استخدام دورة المياه.'),
  ('ST_400', 'كاتب، دار الكتابة العربية: المنصة الأسهل لإنشاء مدونتك، وإطلاق نشرتك البريدية، وتحويل نصوصك إلى ملفات صوتية، مع دعم كامل للغة العربية.'),
  ('ST_401', 'تجمع Bookista فرقًا متخصصة من شبكة تضم أكثر من 10 آلاف مبدع سعودي، وتدير مشروعك بالكامل: تغطية الفعاليات والأفلام والبودكاست وأنظمة الهوية.'),
  ('ST_402', 'خضروات استثنائية تُزرع بطرق مستدامة في قلب المملكة: منتجات زراعة مائية فاخرة لأرقى مطابخ الرياض.'),
  ('ST_403', 'استكشف كولادا واحصل على عروض حصرية وخصومات تصل إلى 50% في مطاعمك ومطابخك المفضلة.'),
  ('ST_404', 'تبسّط فرناس سفر الأعمال بحلول مدعومة بالذكاء الاصطناعي، وتساعد الشركات على توفير الوقت والمال مع تحسين تجربة السفر. سجّل منشأتك معنا الآن!'),
  ('ST_405', 'شركة حلّات لأفضل نظام لإدارة علاقات العملاء، ونظام تذاكر عبر واتساب، وخدمات إدارة العملاء في المملكة. احصل عليه الآن!'),
  ('ST_406', 'منصة متكاملة تقدّم ذكاء القرار في أربع قارات، لتحقيق وفورات تصل إلى 30% في النفقات الرأسمالية والتشغيلية بحلول ذكاء اصطناعي مثبتة.'),
  ('ST_407', 'أكاديمية سعودية تأسست لتحسين جودة مخرجات التعليم والتدريب في مجالات تقنية المعلومات عبر معسكرات تعليمية للمهارات تلبي احتياجات سوق العمل السعودي.'),
  ('ST_408', 'اكسب عملاء جددًا وزِد مبيعاتك المباشرة بخطوة واحدة مع نظام الطلبات المتكامل للمطاعم والمتاجر.'),
  ('ST_409', 'أطلق وكلاء ذكاء اصطناعي صوتيين ونصيين في دقائق: منصة ذكاء اصطناعي تفاعلية تضع العربية أولًا للمؤسسات في الشرق الأوسط.'),
  ('ST_410', 'تقدّم نوت نظامًا تقنيًا متقدمًا لإدارة الأعمال يشمل المحاسبة ونقاط البيع والمخزون والمبيعات والمشتريات بكفاءة وأمان عاليين، شريكك التقني الموثوق.'),
  ('ST_412', 'تخطيط القوى العاملة بالذكاء الاصطناعي، ومطابقة الكفاءات، والعقود، والفوترة، وتمويل الفواتير للمؤسسات السعودية.'),
  ('ST_413', 'استكشف بيانات السوق العقاري السعودي بسهولة مع بيانات عقارية مبسطة.'),
  ('ST_415', 'تحدث مِعكاز نقلة في رعاية الأمراض المزمنة في المملكة عبر منصات افتراضية، تمكّن الأسر برؤى صحية عملية وتعزّز استقلالية كبار السن.'),
  ('ST_416', 'الشحن والدفع والأتمتة في منصة واحدة: اربط متجرك، وقارن أسعار الشحن، وابدأ البيع للعالم.'),
  ('ST_417', 'تجعل هدايا.AI الخيارات الأذكى أقرب إليك عبر رحلات تسوق مخصصة ومدعومة بالمجتمع.'),
  ('ST_418', 'بيانات رواتب حقيقية ومعلومات تواصل مباشرة. ابحث في أكثر من مليون ملف موثّق دون الحاجة إلى نشر وظائف.'),
  ('ST_424', 'استمتع بتجربة تسوق مريحة مع تطبيق جاي: اطلب ما تحتاجه من متاجرك المفضلة واستلمه مباشرة في سيارتك عبر خدمة الاستلام من السيارة، دون انتظار أو بحث عن موقف.'),
  ('ST_425', 'تعلّم اللغات مع Giraffe عبر تدريب محادثة بالذكاء الاصطناعي، ودروس مخصصة، وتقييم للنطق، ومتابعة يومية للتقدّم.'),
  ('ST_427', 'مولّد صور شخصية مهنية بالذكاء الاصطناعي للمهنيين في المملكة.'),
  ('ST_432', 'مجموعة من حلول الذكاء الاصطناعي لبناء عقول رقمية ذكية واستخدامها وتوسيع نطاقها في العمل والحياة.'),
  ('ST_433', 'المنصة الأكثر ابتكارًا في معلومات السوق المالية.'),
  ('ST_434', 'تقدّم AVA حلول دفع غير نقدية تشمل SoftPOS ورموز QR وبوابة الدفع والفوترة الإلكترونية، لتبسيط المدفوعات الرقمية لأعمال مثل الفنادق والمطاعم وآلات البيع.'),
  ('ST_435', 'اختر hseeltech.com حلًا لإطلاق منصة التمويل الجماعي الخاصة بك: عقاري أو خيري أو بالملكية أو بالإقراض أو بالمكافآت.'),
  ('ST_437', 'شريك موثوق للمعاملات الإلكترونية، والحل الأمثل لإدارة العقود والمدفوعات بسلاسة.'),
  ('ST_438', 'لا رسوم خفية ولا وعود مضللة بتداول «مجاني»، بل تسعير شفاف وعادل، ونجاحنا مرتبط بنجاحك.'),
  ('ST_439', 'منصة ضمان مالي مرخّصة من البنك المركزي السعودي، تعمل طرفًا ثالثًا محايدًا يحفظ أموالك في حساب ضمان معتمد ولا يصرفها إلا بعد اكتمال التنفيذ.'),
  ('ST_440', 'نجمع جميع أطراف السوق في منصة واحدة لبناء منظومة رقمية للتمويل الإسلامي.'),
  ('ST_442', 'مستشار رقمي ذكي يدير استثمارك آليًا دون تدخل بشري، ويقدّم حلولًا رقمية لإدارة الثروات تمكّن الأفراد من الاستثمار والادخار.'),
  ('ST_443', 'خبرة لا مثيل لها: فريقنا من المحترفين المعتمدين ذوي المعرفة العميقة في الأمن السيبراني وذكاء الأعمال. نقدّم استراتيجيات مخصصة تتوافق مع أهداف كل منشأة، ونلتزم بتحقيق نتائج قابلة للقياس تضمن نجاحك وأمانك على المدى الطويل.'),
  ('ST_444', 'إرشاد مستقل لتنظيم حياتك المالية وإطلاق إمكانات ثروتك.'),
  ('ST_446', 'ارتقِ مع مناسب، الإقراض أصبح أبسط!'),
  ('ST_447', 'نربط المؤسسات المالية مباشرة بأفضل الموردين لتسهيل عمليات المرابحة الرقمية وفق أحكام الشريعة الإسلامية.'),
  ('ST_448', 'اكتشف العروض والخصومات والقسائم الحصرية مع هللة بلس، تطبيق التوفير الأمثل المدعوم بالمصرفية المفتوحة.'),
  ('ST_449', 'منصتك المتكاملة في عالم التقنية المالية، حيث تلتقي الفرص بالاستثمار.'),
  ('ST_451', 'احجز أفضل الفنانين من موسيقيين وراقصين وسحرة ومنسقي أغانٍ وغيرهم لفعالياتك عبر Soul Artists، واجعل مناسبتك لا تُنسى!'),
  ('ST_452', 'بيّنة منصة قانونية رقمية تربط الأفراد والشركات بمحامين مرخّصين في أنحاء المملكة، وتقدّم استشارات فورية ومجموعة واسعة من الخدمات القانونية بتجربة بسيطة وسريعة وآمنة في مكان واحد.'),
  ('ST_453', 'تصميم وتصنيع ودمج أقمار صناعية متقدمة بالكامل، وتقديم حلول رصد الأرض من العتاد المداري إلى رؤى قابلة للتنفيذ للقطاعات الرئيسية.'),
  ('ST_454', 'أكوان منصة تهدف إلى غرس حب اللغة العربية عبر اللعب، وتقدّم كتبًا وأدوات تعليمية مختارة بعناية لتشجيع اللعب وقضاء وقت نوعي.'),
  ('ST_455', 'اكتشف كيف تدعم Seavos التنقل البحري والعمليات والرصد واستخدامات الأساطيل المتصلة.'),
  ('ST_456', 'تخزين مرن ونقل موثوق وتخليص جمركي: خدمات لوجستية متكاملة سلسة ومرنة.'),
  ('ST_457', 'نمِّ متجرك بفيديوهات أصيلة عبر شبكة المؤثرين الأولى في الشرق الأوسط المدعومة بالذكاء الاصطناعي.'),
  ('ST_458', 'تعرّف على منتجات TechieMatter لتوظيف الكفاءات التقنية، وتشمل أربع خدمات رئيسية: التوظيف التقني، والتقييمات التقنية، والمقابلات التقنية، وتهيئة الموظفين.'),
  ('ST_459', 'بيزاتي من أبرز شركات الدفع في المملكة، تقدّم بوابة دفع آمنة وروابط دفع سريعة لتسهيل مبيعاتك. ابدأ أعمالك مع بيزاتي اليوم.'),
  ('ST_461', 'منصة رقمية لتوثيق الديون وتنظيم تحصيلها وحفظ الحقوق.'),
  ('ST_462', 'يسير، رفيقك في الذكاء المالي.'),
  ('ST_465', 'Truc-King العمود الفقري الرقمي لكل شاحنة على الطريق في المملكة: إدارة الأساطيل والتوثيق والتواصل والمدفوعات في منصة واحدة.'),
  ('ST_467', 'شركة رائدة في الحلول التقنية، نكرّس جهودنا لتقديم أحدث الابتكارات والخدمات التقنية المخصصة التي تساعد عملاءنا على النجاح والتميّز، بفريق متخصص من الخبراء المبدعين لتطوير حلول متكاملة تلبي احتياجات عملك وتسهم في نموه واستدامته.'),
  ('ST_469', 'أفضل وكالة رقمية في السعودية ومصر: تطوير المواقع وتطبيقات الجوال والتسويق الرقمي والحلول البرمجية كخدمة.'),
  ('ST_470', 'تقدّم DH Solutions خدمات تطوير البرمجيات وهندسة الذكاء الاصطناعي وتقنية المعلومات بخبرة عالية، لمساعدة الشركات على بناء حلول رقمية مبتكرة وآمنة وقابلة للتوسع.'),
  ('ST_471', 'اكتشف الفعاليات، وتواصل مع أصدقائك، وخطط لطلعاتك، واحجز التذاكر بسهولة. وللأعمال: ضع مكانك على الخريطة وأتح الحجوزات ببساطة. خرجة تجعل حياتك الاجتماعية وأعمالك أفضل في المملكة.'),
  ('ST_472', 'جمعة أول منصة للتسوق الجماعي في المملكة، تساعدك على الحصول على أفضل الأسعار بالتسوق مع الأصدقاء والعائلة.'),
  ('ST_473', 'استخبارات تهديدات لحظية واستجابة فورية.'),
  ('ST_474', 'تهدف إلى رفع الوعي التنظيمي لدى العملاء ومستوى التزامهم بالأنظمة واللوائح باستخدام التقنية التنظيمية، بما يساعد على تجنّب الغرامات والمخالفات.'),
  ('ST_475', 'نبني فريقًا أحمر ذاتيًا بالذكاء الاصطناعي يحوّل اختبار الاختراق من خدمة يدوية بطيئة إلى عملية برمجية مستمرة.'),
  ('ST_477', 'ارفع الكفاءة ووفّر مع حل سحابي مصمَّم خصيصًا لقطاعك ومتاح أينما احتجت إليه.'),
  ('ST_479', 'هديتك من «ظرف» بين يديك: لمسات شخصية وتغليف فاخر من علامة سعودية معروفة، هدايا لجميع المناسبات من تخرج وأعياد ميلاد وزواج وأعياد لأغلى الناس، مع توصيل سريع إلى جميع أنحاء المملكة وشحن مجاني للطلبات فوق 399 ريالًا.'),
  ('ST_480', 'Startups Galaxy تنمّي الشركات الناشئة بربطها بخبراء تسويق موثّقين بعناية تحت إشراف ومتابعة محايدة: تحدد التوقعات، ويتولى الخبراء التدقيق والتنفيذ وتسليم النتائج.'),
  ('ST_481', 'Nomadroid استوديو ألعاب مستقل تأسس أواخر 2021، ومن أوائل استوديوهات ألعاب الحاسب والمنصات المنزلية في المملكة، يسعى لكسر الصور النمطية ووضع معاييره الخاصة في المنطقة بتطوير ألعاب فردية مميزة بأعلى جودة.'),
  ('ST_482', 'تقدّم مسرّعة تقدّم العالمية للشركات الناشئة، المدعومة بشبكات كاوست وساب، الدعم للشركات الناشئة في جميع مراحل نموها منذ عام 2016، وتساند المؤسسين لتجاوز حدود الممكن.'),
  ('ST_484', 'منصة عقارية للبيع والإيجار في المملكة: ابحث عن عقارك المفضل في الرياض وجدة وغيرها من المدن بأفضل وسائل البحث، من شقق وفلل وأراضٍ واستراحات.'),
  ('ST_485', 'اكتشف المشاريع العقارية في المملكة: شقق وفلل وأراضٍ في الرياض وجدة والدمام والمدينة المنورة بأسعار تنافسية تناسب مختلف الاحتياجات.'),
  ('ST_487', 'أراضٍ للبيع بأفضل الأسعار، ومبانٍ تجارية وسكنية للبيع، وشقق للإيجار.'),
  ('ST_488', 'تداولكم منصة عقارية سعودية متكاملة لإنشاء المواقع العقارية وتصميمها، وإدارة العقارات وتسويقها، واستعراض المخططات والخرائط التفاعلية للمدن عبر نظم المعلومات الجغرافية.'),
  ('ST_490', 'اكتشف الخدمات العقارية المختارة التي تقدّمها منصة سكن.'),
  ('ST_491', 'تسهّل عليك «ست» العقارية تملّك منزل أحلامك بأسهل الطرق، وتساعدك على اختيار المنزل والتمويل المناسبين.'),
  ('ST_492', 'تصفّح العقارات، وقدّم طلبك العقاري، أو سجّل وسيطًا في منصة رقمية منظّمة تخدم السوق العقاري السعودي.'),
  ('ST_494', 'خدمات تقنية لا غنى عنها في عالم الأعمال الرقمية، نقدّم لك شبكة دعم فني متكاملة لضمان حضورك الرقمي بأفضل صورة.'),
  ('ST_495', 'ربط بين أُطر الامتثال بالذكاء الاصطناعي: محرّكنا الدلالي يربط أعمال الامتثال لديك آليًا عبر أكثر من 12 إطارًا. قيّم مرة واحدة، والتزم في كل مكان.'),
  ('ST_496', 'تصفّح آلاف العقارات للبيع والشقق للإيجار في الرياض والدمام وجميع مدن المملكة على ديل، من فلل وأراضٍ ومحلات تجارية مع وسطاء معتمدين.'),
  ('ST_497', 'نحدث نقلة في إدارة الأساطيل في الشرق الأوسط وأفريقيا عبر نظام تشغيل يخفّض مصروفات الأسطول ويرفع الكفاءة ويتتبع الانبعاثات.'),
  ('ST_499', 'يجعل استوديو شبلونة فن الطباعة اليدوية في متناول الجميع عبر تعليم منظّم ومساحة إبداعية مفتوحة، سواء كنت تطبع لأول مرة أو تطوّر ممارستك.'),
  ('ST_501', 'بسّط عمليات المشتريات لديك عبر المناقصات التنافسية على منصة شطيب لطلبات عروض الأسعار.'),
  ('ST_502', 'تقدّم منزل حلولًا مُدارة بالكامل لسكن العمالة ونقلها في المملكة، بعقود مرنة وتراخيص نظامية وإدارة شاملة تضمن راحة فريقك والتزام شركتك بجميع الأنظمة.'),
  ('ST_503', 'PrimeLoop، حل التبريد الأكثر كفاءة.'),
  ('ST_504', 'نحن هنا لمساعدتك في العثور على العقار المثالي.'),
  ('ST_506', 'نمهّد الطريق نحو الحياد الكربوني في المملكة: تبسّط COZ إنشاء أرصدة الكربون وتوسّع الوصول إلى أسواقها، لتساعد الشركات السعودية على تسريع رحلتها نحو أهداف الحياد الصفري بثقة ووضوح.'),
  ('ST_507', 'نوظّف خبرتنا لوضع معايير جديدة في الدقة والعائد على الاستثمار لدفع النمو وخفض التكاليف.'),
  ('ST_509', 'نجمع أحدث التصاميم وأشهر المصممين والمتاجر المحلية، مع توصيل سريع وإرجاع مجاني، لتستمتع بتجربة تسوق فريدة تجمع الأناقة والراحة.'),
  ('ST_510', 'يتيح التطبيق استعراض جميع الوحدات والقطع المتاحة في المنطقة التي تريد الشراء فيها مع كامل بياناتها، والشراء بمختلف الطرق.'),
  ('ST_512', 'قروف شركة سعودية تربط المزارع بالمستهلك لتوصيل المنتجات الزراعية الطازجة مباشرة من المزرعة عبر سلسلة إمداد ذكية قائمة على الطلب لجودة أعلى.'),
  ('ST_513', 'ماوا العقارية: اعثر على منزل المستقبل.'),
  ('ST_514', 'تمكّن 525K مشغّلي الخدمات اللوجستية بمختلف أحجامهم وعملياتهم من تحسين عملياتهم في دقيقة بتقنيتها المتطورة، لأن السنة فيها 525 ألف دقيقة فقط.'),
  ('ST_518', 'أدِر الحجوزات والمدفوعات والعمليات والامتثال لبيوت العطلات والإيجارات قصيرة المدى من منصة واحدة، مع سوق للموردين وشبكة من المشغّلين.')
) as v(id, ar)
where s.startup_id = v.id;

update public.startups as s set startup_description_ar = v.ar
from (values
  ('ST_519', 'نمكّن الجهات الحكومية والشركات من البناء على شبكات البلوك تشين بأمان وسرعة.'),
  ('ST_520', 'مرايا منصة رائدة للتجارة الإلكترونية في الأزياء تمنح الأزياء العربية منبرًا لعرض أفضل المصممين العرب، وتجمع التقنية المتطورة والخدمات المخصصة في تجربة تسوق متعددة القنوات، مع متجرها الرئيسي في الرياض وحضور قوي عبر الإنترنت يعكس التزامها بالإبداع والحرفية المحلية.'),
  ('ST_521', 'اعثر على منزل أحلامك في المملكة.'),
  ('ST_523', 'يبحث كثير من رواد الأعمال عن تمويل من المستثمرين دون التخلي عن جزء من ملكية شركاتهم، وقد أسهم التطور الكبير في التقنية المالية في فكرة التمويل عبر منصة إلكترونية تتيح للمنشآت الصغيرة والمتوسطة الوصول إلى رأس المال، وللمستثمرين دخول استثمارات جديدة وتوسيع محافظهم.'),
  ('ST_524', 'منصتك العقارية تمكّنك من تسويق الفرص العقارية واستكشافها لتملّك الوحدات السكنية والأراضي المخططة عبر تجربة رقمية مبتكرة وموثّقة مع دفع وتمويل آمنين.'),
  ('ST_525', 'انضم إلى المنصة الرقمية الرائدة للاستثمار العقاري في المملكة، المعتمدة من هيئة السوق المالية، والآمنة والسهلة الاستخدام. ابدأ رحلتك الاستثمارية الآن.'),
  ('ST_526', 'عبر حلولنا المبتكرة في التقنية المالية وثقة المستثمرين والشركاء (النسخة التجريبية) يمكننا مساعدتك، وللتواصل عبر البريد الإلكتروني أو الهاتف.'),
  ('ST_528', 'شركة تقنية مالية سعودية تقدّم حلول تمويل واستثمار مبتكرة متوافقة مع الشريعة الإسلامية، تمكّن الشركات والمستثمرين من الوصول إلى فرص واعدة تدعم النمو الاقتصادي.'),
  ('ST_529', 'SmartSavings شركة تقنية مالية سعودية تتيح للمستخدمين الوصول إلى صناديق استثمار مرخّصة من هيئة السوق المالية والاستثمار فيها، عبر سوق يجمع منتجات استثمارية متعددة يقدّمها مديرو الأصول في المملكة.'),
  ('ST_530', 'شركة تقنية مالية مرخّصة من البنك المركزي السعودي.'),
  ('ST_531', 'تهدف الشركة إلى أن تكون حلقة الوصل بين ملّاك الأراضي ومطوّريها والمستثمرين الأفراد والشركات عبر منصة لإصدار أدوات دين توفّر التمويل للمطوّرين لشراء الأراضي أو تغطية تكاليف البناء، وتمكّن المستثمرين من الاستثمار في التطوير العقاري بوسائل مالية آمنة ومشروعة تحفظ حقوق جميع الأطراف.'),
  ('ST_532', 'ساعي منصة تسويق عقاري مرخّصة من الهيئة العامة للعقار في المملكة، تقدّم حلولًا عقارية متكاملة وأفضل المشاريع السكنية والاستثمارية في الرياض.'),
  ('ST_533', 'تصفّح الفرص واستثمر بدءًا من 1,000 ريال، وأكمل جميع الإجراءات النظامية فورًا وبسلاسة عبر منصة طهر.'),
  ('ST_534', 'المنصة الأنسب للاستثمار وتمويل مشاريع التطوير، عبر صكوك وأوراق مالية متوافقة مع الشريعة، وفرص استثمارية بأرباح ثابتة في قطاعات متنوعة.'),
  ('ST_535', 'منصة أرات المالية للاستثمار والتمويل بالصكوك الجماعية لتمويل العقارات للمؤسسات والشركات، مرخّصة من هيئة السوق المالية.'),
  ('ST_536', 'منصة فعّالة مرخّصة من هيئة السوق المالية توفّر لك التمويل المناسب، بتمويل سريع خلال 5 أيام عمل.'),
  ('ST_537', 'تعرّف على منصة أرض ودورها في تطوير القطاع العقاري عبر خرائط دقيقة وبيانات رقمية تعزّز الشفافية وتدعم اتخاذ القرار.'),
  ('ST_538', 'منصة تقنية مالية مرخّصة من هيئة السوق المالية تعمل على توزيع وحدات صناديق الاستثمار العقاري والملكية الخاصة ورأس المال الجريء والدخل الثابت محليًا وعالميًا.'),
  ('ST_540', 'منصة استثمار مرخّصة من هيئة السوق المالية تتيح لك الوصول إلى فرص استثمارية نوعية وبناء ثروتك عبر تجربة استثمار آمنة واحترافية.'),
  ('ST_542', 'منصة سعودية تقدّم تجربة غنية لشراء الوحدات السكنية واستئجارها، مع عرض شامل للوحدات باستخدام تقنيات حديثة.'),
  ('ST_543', 'شريك لنمو أعمالك ونجاحها عبر التمويل بالصكوك.'),
  ('ST_544', 'تربط ساعة كابيتال المستثمرين الأفراد الراغبين في الاستثمار في صناديق الاستثمار بمديري الصناديق الراغبين في إدراج صناديقهم وبيعها.'),
  ('ST_545', 'نتاج منصة استثمار جماعي تقدّم فرص استثمار عقاري مع سوق ثانوية منظّمة تتيح للمستثمرين بيع وشراء وحدات الصناديق الخاصة والمغلقة.'),
  ('ST_546', 'نخصص جزءًا من الإيرادات لدعم الطلاب عبر صندوق الطالب، ولتمويل برامج تنموية تخدم المجتمع والبيئة.'),
  ('ST_547', 'WiseTech شركة تقنية سعودية رائدة متخصصة في خدمات تقنية المعلومات الشاملة وحلول الأمن السيبراني، وتعمل عبر قسمين متخصصين في البنية التحتية لتقنية المعلومات وخدمات الأمن السيبراني.'),
  ('ST_548', 'انضم إلى منصة MoneyDo الآمنة للاستثمار للوصول إلى فرص عالية النمو في العقار والملكية الخاصة والاستثمارات البديلة في المملكة.'),
  ('ST_549', 'نعيد تصوّر طريقة الشراء والبيع والإيجار، ليصبح الوصول إلى مكان تحبه أسهل. لنفعلها معًا.'),
  ('ST_550', 'قناة إضافية لتسويق الصندوق وزيادة الاشتراكات، وتقليل الجهد في تنفيذ عمليات الاشتراك، وإبراز الصندوق للمستثمرين بشكل أفضل.'),
  ('ST_551', 'منصة رقمية مبتكرة لإدارة الملكية وأعمال الجمعيات العمومية وعلاقات المستثمرين. بسّط حوكمة شركتك بحلول إبانة المبتكرة.'),
  ('ST_552', 'آفاق كابيتال شركة مساهمة مقفلة مقرها الرياض، حاصلة على ترخيص من هيئة السوق المالية بتاريخ 18 أبريل 2022.'),
  ('ST_553', 'تخارج مبادرة رائدة في التقنية المالية من شركة نولدج نت، تقدّم منصة تحدث نقلة في تداول أسهم الشركات غير المدرجة، وتربط مجموعة متنوعة من هذه الشركات بالمستثمرين، وتسهّل بيع الأسهم وشراءها بسلاسة وأمان في سوق ديناميكية.'),
  ('ST_554', 'منصة تسويق افتراضية وتطبيقات لسوق افتراضية للخدمات العقارية، مرخّصة من الهيئة العامة للعقار وموثّقة من المركز السعودي للأعمال.'),
  ('ST_555', 'منتجات تحوّل البيانات المعقدة إلى قيمة تجارية عبر إدارة شاملة للبيانات، تشمل حوكمة البيانات كإطار تشغيلي متكامل لتنظيم بيانات أعمالك وتصنيفها وتتبّعها، وإدارة البيانات الرئيسية كمصدر موحّد وموثوق بين الأنظمة.'),
  ('ST_556', 'فحص يكشف لك ما ينقصك قبل أن يتحول إلى مشكلة.'),
  ('ST_557', 'Aiqona Productions تصنع تجارب أيقونية، وتبني الألعاب بسرعة وبأسلوب مختلف وجريء.'),
  ('ST_558', 'برامج محاكاة التصيّد الاحتيالي المثالية بالذكاء الاصطناعي.'),
  ('ST_559', 'انطلق Fourcast من الرياض، وهو استوديو مستقل يسعى لصنع اسم له في سوق ألعاب الحاسب الاجتماعية.'),
  ('ST_560', 'مبتكرون في عالم الألعاب منذ يناير 2019، متخصصون في التجارب الغامرة على Minecraft وRoblox.'),
  ('ST_561', 'OFF BOX Studios فريق تطوير ألعاب يفكر بشكل مختلف، ويصنع ألعابًا فريدة تتجاوز مجرد الترفيه.'),
  ('ST_562', 'تطبيق لياقة سعودي بالواقع المعزز للأطفال من عمر سنتين إلى 12 سنة، دون أجهزة أو وحدات تحكم، لعب قائم على الحركة مع مكافآت حقيقية ورقابة أبوية ذكية.'),
  ('ST_563', 'بنية تحتية بالذكاء الاصطناعي تطابق المهندسين الموثّقين مع العملاء فورًا، مع وصول مباشر إلى المطورين المتاحين وعقود ومقابلات مؤتمتة.'),
  ('ST_564', 'منصة رقمية تربط مشتري وبائعي السلع الفاخرة المستعملة الموثّقة والمختارة بعناية. تغيّر AMUSED طريقة تفكير المجتمع في المملكة وشعوره تجاه الفخامة واستهلاكها.'),
  ('ST_565', 'شركة ناشئة لديها موقع إلكتروني.'),
  ('ST_566', 'نتخصص في ثود في تمكين المؤسسات من التحقق المستمر من ضوابطها الأمنية، وبصفتنا روّادًا في محاكاة الاختراقات والهجمات تقدّم تقنيتنا رؤى قابلة للتنفيذ على مدار الساعة لتعزيز منع التهديدات واكتشافها.'),
  ('ST_568', 'مساحتك الشخصية للتعلّم الذكي.'),
  ('ST_569', 'بنية تحتية للإيصالات الرقمية في المملكة جاهزة لنظام حماية البيانات الشخصية، بإعداد نقطة البيع في 5 إلى 10 دقائق، والخصوصية مدمجة في التصميم.'),
  ('ST_571', 'بِع واشترِ الخضروات والفواكه الطازجة بالجملة مباشرة من المزارعين والمستوردين في المملكة، بأسعار تنافسية وتوصيل سريع.'),
  ('ST_572', 'دلالي منصة شاملة لإدارة الأملاك في المملكة، تقدّم حلولًا تقنية لإدارة الإيجارات وتحصيل الدفعات والصيانة والتسويق العقاري.'),
  ('ST_573', 'تتصدر Ashia الابتكار في الرعاية الصحية، متخصصة في أجهزة مراقبة صحية منزلية متميزة متكاملة مع برمجيات متطورة تمنح المرضى ومقدّمي الرعاية وصولًا لحظيًا إلى البيانات الصحية، بهدف الانتقال من التدخلات قصيرة المدى إلى نماذج رعاية استباقية مستمرة تتمحور حول الإنسان.'),
  ('ST_574', 'Odystra AI منصة حوكمة ومخاطر وامتثال وكيلية للمؤسسات الخاضعة للتنظيم، تجمع الحوكمة والمخاطر والامتثال في منصة واحدة مصمَّمة للبيئة التنظيمية السعودية.'),
  ('ST_575', 'AISC شركة تقنية متخصصة في تقنيات البناء، تقدّم حلولًا مبتكرة لإدارة مواقع البناء وفحصها، وتعتمد على تقنيات الواقع المعزز والذكاء الاصطناعي لتعزيز السلامة والكفاءة والاستدامة في عمليات البناء.'),
  ('ST_576', 'منصة إلكترونية تساعدك على إنشاء متجرك الإلكتروني المتكامل، وتتولى التجارة الإلكترونية والتسويق والإعلان وإدارة المنصة والحسابات، مع فريق عمل متكامل يعمل على متجرك.'),
  ('ST_577', 'نمونا بسرعة لنصبح شريكًا موثوقًا للمؤسسات الساعية إلى التحول الرقمي وتحسين الكفاءة التشغيلية.'),
  ('ST_578', 'استثمر في ودائع متوافقة مع الشريعة بعوائد بنكية تنافسية في تطبيق واحد.'),
  ('ST_580', 'حوّل كل عملية شراء إلى قرار مالي ذكي، وخصّص الاسترداد النقدي مباشرة للفواتير والقروض والاشتراكات.'),
  ('ST_581', 'تمنح SandsBytes فرق الاستجابة للحوادث مكانًا واحدًا لفرز الحوادث وتعقّب التهديدات وتوثيق النتائج وتقديم تقارير متسقة، دون الحاجة إلى ربط أدوات متعددة أو فقدان السياق أثناء التحقيق.'),
  ('ST_583', 'يجمع ركاز حجوزاتك واشتراكاتك ومدفوعاتك وموظفيك وتواصلك مع العملاء في نظام واحد مصمَّم للمشاريع الخدمية.'),
  ('ST_584', 'منصات تعلّم عميق للعمليات الصناعية، قابلة للتشغيل محليًا وجاهزة لأنظمة SCADA، وتشمل FoulGuardAI™.'),
  ('ST_585', 'لامح نظام تشغيل بالذكاء الاصطناعي للمؤسسات المالية في المنطقة، يوحّد المستندات والكشوف وبيانات السوق والمصادر الخارجية في طبقة واحدة محكومة، ويختصر دورات التحليل من أيام إلى دقائق، ومصمَّم للبيئات الخاضعة للتنظيم مع تتبّع كامل وضوابط وصول دقيقة وإشراف بشري.'),
  ('ST_586', 'منصة واحدة للمدفوعات وقوائم الطعام وبرامج الولاء في المنطقة.'),
  ('ST_587', 'خصّص تواصلك وزِد مبيعاتك عبر منصة أعمال واتساب التي تؤتمت التسويق والمبيعات والخدمة والدعم.'),
  ('ST_588', 'Authena شركة تقنيات عميقة تقدّم تتبّعًا لحظيًا لسلاسل الإمداد والتحقق من أصالة المنتجات لقطاعات الأغذية والأدوية والسلع الفاخرة.'),
  ('ST_589', 'OpenFarming منصة مدعومة بالذكاء الاصطناعي تساعد الموزعين على تبسيط عملياتهم وتحسين رضا عملائهم.'),
  ('ST_590', 'ارتقِ بعمليات إنتاج الدواجن واستفد من الذكاء الاصطناعي لتحسين الأداء وتوفير التكاليف والحد من الاحتيال ورفع الكفاءة.'),
  ('ST_593', 'شركة ناشئة لديها موقع إلكتروني.'),
  ('ST_594', 'رفاه الإنسان ينبع من رأس المال الحيوي للتربة.'),
  ('ST_595', 'أضف كيس كلين إلى طلبك واستمتع بخدمة غسيل مريحة جدًا دون الحاجة إلى التواصل مع المندوب أو التواجد في شقتك وقت الاستلام والتسليم.'),
  ('ST_596', 'البوابة العقارية الإلكترونية الرائدة في المملكة: من مجلة إعلانات عقارية مبوّبة إلى منصة رقمية عالمية اليوم.'),
  ('ST_597', 'تقدّم ورد للخدمات اللوجستية حلولًا مبتكرة للمصانع وشركات النقل، لتبسيط العمليات وضمان تسليم سلس ومعالجة التحديات اللوجستية عبر منصتها.'),
  ('ST_598', 'نقدّم تقنيات متطورة في الذكاء الاصطناعي والحوسبة السحابية لتحسين عملياتك وخفض التكاليف وتسريع النمو.'),
  ('ST_599', 'مصدرك للمنتجات عالية الجودة التي يحتاجها مطعمك.'),
  ('ST_600', 'تأسست شركة الحلول التقنية والهندسية المستدامة (STES) لتكون رائدة في أنظمة الأمن وأنظمة النقل الذكية وتقنية المعلومات والاتصالات، وتتخصص في تصميم أنظمة السلامة والأمن وتركيبها وصيانتها، بهدف إيجاد بيئات آمنة للعيش، مع تواصل وثيق مع العملاء خلال مراحل التصميم والتشغيل.'),
  ('ST_601', 'Supermile نظام تشغيل للميل الأخير مدعوم بالذكاء الاصطناعي في المملكة، مع أكثر من 520 شريكًا وأكثر من 26,000 سائق، وحلول للشركات والأساطيل.'),
  ('ST_602', 'مهمتنا تلبية جميع احتياجات السوق في مجال الروبوتات والذكاء الاصطناعي بصناعة سعودية 100%.'),
  ('ST_604', 'Rovera تؤتمت الامتثال لإطار الأمن السيبراني للبنك المركزي السعودي ومتطلباته التنظيمية وتدير المخاطر، لتنمو أعمالك بشكل أسرع.'),
  ('ST_605', 'خدمات أمن هجومي متميزة في المملكة، مرخّصة من الهيئة الوطنية للأمن السيبراني ومتوافقة مع رؤية 2030: اختبار الاختراق والفريق الأحمر ومراجعة الشيفرة وتدقيق الحوكمة والمخاطر والامتثال على يد خبراء سعوديين.'),
  ('ST_606', 'نقلة نوعية وفق معايير جودة متكاملة، نعمل برؤى حديثة ومتجددة على تطوير وتمويل مشاريع أراضٍ ومشاريع متعددة الاستخدامات مبتكرة وعالية الجودة تسهم في تنمية الاقتصاد وتحقيق استثمار مميز لعملائنا.'),
  ('ST_607', 'منصة رائدة للاستثمار العقاري في المملكة.'),
  ('ST_608', 'تبسّط منصة COGNNA لمراكز العمليات الأمنية بالذكاء الاصطناعي ووكلائها الأذكياء الاكتشاف والاستجابة والامتثال، لدعم فرق الأمن بأمن أسرع وأذكى.'),
  ('ST_609', 'ادّخر بذكاء واكسب مكافآت حصرية واستردادًا نقديًا من أفضل العلامات التجارية وأنت تحقق أهدافك المالية.'),
  ('ST_610', 'من كثبان المملكة الذهبية وُلدت Dunes Aero، شركة متخصصة في تقنيات الطائرات المسيّرة والأنظمة غير المأهولة.'),
  ('ST_612', 'أكثر من 12,000 مصدر تعليمي تفاعلي، ومعلم ذكي على مدار الساعة، ومختبرات ثلاثية الأبعاد، وبنوك أسئلة تساعد الطلاب على التعلّم وفق مستواهم واحتياجاتهم.'),
  ('ST_613', 'منصات بيانات مدعومة بالذكاء الاصطناعي لقطاع التجزئة والسلع الاستهلاكية سريعة الدوران.'),
  ('ST_614', 'موقع «أثق» أداة مالية مبتكرة لتسهيل إدارة الفواتير وتحليل المصروفات الشخصية، بواجهة بسيطة وسهلة تمكّن المستخدمين من تتبع مصروفاتهم بسهولة والتحكم في ميزانيتهم.'),
  ('ST_615', 'أنشئ دليلًا لعقارك وشارك روابط ذكية مع ضيوفك بسهولة.'),
  ('ST_616', 'Evolite Studio شركة تطوير ألعاب حائزة على جوائز ومدعومة من صندوق رأس مال جريء، تركّز على بناء ألعاب فريدة عالية الجودة بنكهة عربية.'),
  ('ST_617', 'إيوان تك العقارية شركة سعودية مبتكرة في التقنية العقارية تأسست في أغسطس 2023، تسعى لإحداث نقلة في طريقة التعامل مع الأصول العقارية وتحسينها، وسد الفجوة بين الممارسات العقارية التقليدية والتقنيات المتطورة.'),
  ('ST_618', 'سوق للتدريب.'),
  ('ST_619', 'منصة وساطة عقارية سكنية تربط المؤجر والمستأجر والبائع والمشتري باستخدام الذكاء الاصطناعي.'),
  ('ST_620', 'Helper شركة ناشئة تقنية تقدّم سوقًا للتقنيات التعليمية يربط مقدّمي المحتوى من مهندسين وباحثين ومعلمين في العلوم والتقنية والذكاء الاصطناعي والروبوتات بالطلاب، ويتيح للمعلمين إضافة دوراتهم المباشرة أو المسجلة لتحقيق دخل إضافي. كما تقدّم مختبرًا مجهزًا بالأدوات والروبوتات، وبناء نماذج روبوتات تعليمية، ودورات تقنية للمؤسسات، وتطوير المواقع الإلكترونية.'),
  ('ST_621', 'منصة تقنية تسويقية موحّدة يعمل فيها الذكاء الاصطناعي والإعلام والتقنية معًا لتحقيق نمو حقيقي وقابل للتوسع.'),
  ('ST_622', 'تساعد Newera.ai فرق الجهات الحكومية والمؤسسات على الانتقال من إثبات المفهوم إلى التشغيل الفعلي، عبر تصميم أنظمة ذكاء اصطناعي مخصصة باللغتين العربية والإنجليزية وتدريبها ونشرها في بيئات آمنة ومعزولة خلال أسابيع.'),
  ('ST_623', 'منصة رقمية رائدة للتمويل الجماعي بالدين بين الأفراد، تربط طالبي التمويل بالمستثمرين بطريقة سريعة وآمنة وشفافة، وتتيح للأفراد الحصول على تمويل سريع بهامش ربح تنافسي، مع فرص استثمارية متنوعة ومبتكرة، وفق أنظمة البنك المركزي السعودي ودعمًا للشمول المالي في المملكة.'),
  ('ST_624', 'علامة أثاث سعودية فاخرة تعيد تعريف الحياة العصرية بتصاميم راقية ومجموعات مختارة وحرفية استثنائية، وتقدّم حلولًا متكاملة في الأثاث والإضاءة والسجاد وديكور المنزل، حيث تلتقي الأناقة بالعملية.'),
  ('ST_625', 'تقدّم حلول إدامة حلولًا تقنية متقدمة في الحوكمة والتدقيق الداخلي، مستفيدة من الذكاء الاصطناعي لتحسين أداء الأعمال محليًا وإقليميًا وعالميًا.'),
  ('ST_626', 'فريد التطبيق الشامل للتقنيات التعليمية في المنطقة: تعلّم والعب واقرأ وأكثر!'),
  ('ST_627', 'نقوة شركة ناشئة سعودية في تقنيات الفن والثقافة، تبني بنية الثقة الرقمية لسوق الفنون البصرية، وتجمع التحقق من الفنانين والمصادقة على الأعمال الفنية وشهادات الأصالة وسجلات المصدر وأدوات السوق، لتمكين معاملات أكثر موثوقية بين الفنانين والمقتنين والمعارض في المملكة والمنطقة.'),
  ('ST_628', 'Wilow منصة غسيل متكاملة توحّد الاستلام والغسيل والتوصيل بخدمة سريعة ونظيفة ويمكن التنبؤ بها.'),
  ('ST_629', 'أول خدمة لتقييم مخاطر الذكاء الاصطناعي في المنطقة، أسسها طبيب ومتخصص في حوكمة الذكاء الاصطناعي، وتطبّق SAIF CHECK انضباط السلامة السريرية والأمن السيبراني والصرامة التنظيمية على أنظمة الذكاء الاصطناعي الحديثة.'),
  ('ST_630', 'Elevaty الشريك الرقمي لتشغيل الفنادق الحديثة، تستبدل أدلة التدريب القديمة بمنصة للجوال تتحدث لغة موظفيك، وتحوّل معايير الفنادق المعقدة إلى مهام مرئية بسيطة خطوة بخطوة يمكن إتقانها في دقائق، ليكون فريقك جاهزًا من اليوم الأول مع تقليل عبء المشرفين والقضاء على أخطاء الخدمة.')
) as v(id, ar)
where s.startup_id = v.id;

update public.startups as s set startup_description_ar = v.ar
from (values
  ('ST_631', 'نقاط منصة ولاء موحّدة تجمع كل نقاطك في مكان واحد: تسوّق من شبكة تجار مميزة واكسب نقاطًا مع كل عملية شراء، ثم استخدمها للدفع في أي متجر شريك، وانقل نقاطك من برامج الولاء الأخرى إلى محفظتك الموحّدة. محفظة واحدة وفرص بلا حدود!'),
  ('ST_632', 'شركة تقنية صناعية تساعد المصانع على استخدام البيانات والذكاء الاصطناعي والحلول الرقمية لتحسين العمليات وتقليل الهدر واتخاذ قرارات أسرع.'),
  ('ST_633', 'رمال لأشباه الموصلات أول شركة سعودية لتصميم أشباه موصلات الطاقة دون مصانع خاصة، تبني منظومة رقائق سيادية قائمة على التطبيقات، وتتخصص في أجهزة الطاقة لقطاعات حيوية كالطاقة والأتمتة الصناعية والتنقل والبنية التحتية للبيانات. تجمع بين تصميم الرقائق وهندسة التطبيقات والتوطين، وتعتمد على سلسلة إمداد عالمية متعددة المصانع لضمان إمداد مرن وآمن، وتسهم في نقل التقنية وتطوير الكفاءات الهندسية وجعل المملكة مركزًا إقليميًا لابتكار أشباه الموصلات بما يتماشى مع رؤية 2030.'),
  ('ST_634', 'Pixconvey شركة سعودية متخصصة في حلول التنقل الذكي داخل المباني، تطوّر مركبات ذاتية القيادة تتنقل دون خرائط وتفهم اللغة العربية، وتخدم المطارات والمستشفيات والمنشآت الكبيرة ببيئات تشغيلية ذكية تتماشى مع رؤية 2030.'),
  ('ST_635', 'Qanary شركة ناشئة في التقنيات العميقة لعلاج الأورام، تطوّر أول وكيل تشخيصي للسرطان في العالم يعتمد على الذكاء الاصطناعي الكمي، ويكتشف الأورام الخبيثة في مراحلها المبكرة غير المرئية خلال 8.24 ثانية فقط، ليكون «رأيًا ثانيًا رقميًا» فوريًا يقضي على تأخر التشخيص ويعيد تعريف الكشف المبكر عن السرطان.'),
  ('ST_636', 'منصة سعودية حديثة لإدارة المشاريع البرمجية ونشرها بسهولة واحترافية، تمكّن الشركات والمطورين من تشغيل تطبيقاتهم على خوادمهم أو على خوادم سحابية أو عبرنا كحل متكامل وجاهز، مع سرعة الإطلاق وأمان البنية التحتية وأتمتة النشر والتحديث والمراقبة والنسخ الاحتياطي.'),
  ('ST_637', 'Bookahospi تعيد تشكيل التنقل العالمي للمهن المنظَّمة. تأسست في مدريد عام 2023 وساعدت أكثر من 2,500 مهني على الحصول على تراخيصهم في إسبانيا والسعودية و5 دول أخرى، وتحظى بثقة مؤسسات رائدة منها مستشفيات د. سليمان الحبيب ووزارة الصحة السعودية، ويستخدم منصتها أكثر من 100,000 مستخدم نشط، لمعالجة نقص الكوادر الصحية المؤهلة. وتتوسع الآن ببنيتها المدعومة بالذكاء الاصطناعي في الخليج وأمريكا اللاتينية.'),
  ('ST_638', 'يحوّل Byondbites ما في مطبخك إلى وجبات تحب تناولها: تطبيق تقنية غذائية يتيح مسح محتويات المخزن والحصول فورًا على وصفات مخصصة، لمعالجة هدر الطعام وحيرة اختيار الوجبات. التطبيق متاح على iOS وAndroid مع قاعدة مستخدمين متنامية في السعودية والإمارات، ويستعد لمرحلة ثانية بتجربة مدعومة بالذكاء الاصطناعي والتوسع في الخليج ثم جنوب آسيا.'),
  ('ST_639', 'Path Link منصة رقمية متكاملة تجمع الأفراد والشركات في مكان واحد، وتركّز على التوظيف والتدريب والاستشارات والعمل الحر، معتمدة على التقنية الذكية وتحليل البيانات لربط المستخدمين بالفرص المناسبة وتطوير مهاراتهم وبناء شراكات مهنية بكفاءة وسلاسة.'),
  ('ST_640', 'SENOZ منصة ذكاء صحي مدعومة بالذكاء الاصطناعي لتحسين القرارات السريرية وكفاءة الرعاية الصحية، تدعم الأطباء والفرق الطبية لاتخاذ قرارات أسرع وأدق وأكثر موثوقية، وتمكّن المستشفيات من الانتقال من الرعاية التفاعلية التقليدية إلى رعاية استباقية وتنبؤية.'),
  ('ST_641', 'الفلسفة الرقمية شركة تقنية متخصصة في التحول الرقمي وبناء حلول رقمية متكاملة للشركات، وتساعدها على الانتقال من العمليات التقليدية إلى أنظمة رقمية فعّالة ومرنة. منتجها منصة ذكاء مالي ذاتية بالذكاء الاصطناعي مصمَّمة لتجار التجارة الإلكترونية في المملكة، تحوّل البيانات المالية المتفرقة إلى صافي ربح دون تدخل بشري.'),
  ('ST_642', 'رواء سوق يساعد الشركات الناشئة على خفض التكاليف والنمو بذكاء، بالشراكة مع أفضل المزوّدين لتقديم عروض حصرية للمؤسسين على الخدمات والأدوات التي يحتاجونها، من القانونية والمحاسبية إلى التسويق والتصميم والتقنية.'),
  ('ST_643', 'جلوردا منصة سعودية للهدايا والمناسبات تجمع أفضل محلات الورد والكيك والحلويات والهدايا في تطبيق واحد، وتربط العملاء بالمتاجر المحلية القريبة بتجربة شراء سريعة وأنيقة.'),
  ('ST_644', 'نقدّم حلول تأجير متكاملة من الأثاث والمعدات الصوتية والمرئية إلى كراسي المساج الفاخرة. استأجر السوق الرائد للتأجير في المملكة، يربط الشركات والأفراد بموردين موثّقين للفعاليات والضيافة وغيرها.'),
  ('ST_645', 'قاول تك منصة مشتريات مدعومة بالذكاء الاصطناعي تغيّر طريقة توريد مشاريع البناء وتقييم قرارات الشراء وتنفيذها، إذ تحلل مستندات المشروع وتقسّمها إلى حزم مشتريات منظّمة وتقدّم توصيات تنفيذية خلال أيام بدل أشهر، وتستهدف المشاريع المتوسطة والكبيرة، وتدمج الموردين والخدمات اللوجستية والحلول المالية في طبقة قرار موحّدة.'),
  ('ST_646', 'منصة تعليمية تسعى لبناء جيل تقني رائد عبر دورات البرمجة والروبوتات والذكاء الاصطناعي والحساب الذهني للأطفال من 5 إلى 17 عامًا، بمناهج عربية مرنة ومباشرة.'),
  ('ST_647', 'منصة تقنية مبتكرة تهدف إلى إحداث نقلة نوعية في التوظيف التقني بالمملكة، تجمع الشركات السعودية الراغبة في استقطاب الكفاءات التقنية المتخصصة بالمواهب التقنية العربية الباحثة عن عمل، مع دعم الشركات الناشئة لتعزيز أعمالها في مكان واحد متكامل.'),
  ('ST_648', 'رجح لألعاب الفيديو استوديو يصنع ألعاب ألغاز إبداعية ومريحة وبأساليب فنية مميزة، بعوالم ساحرة وأفكار لعب فريدة وفن مصنوع يدويًا.'),
  ('ST_649', 'Zest شركة بنية تحتية رقمية لتنفيذ صفقات الأسواق الخاصة، تستبدل العمليات المجزأة ببنية مؤسسية تغطي دورة الصفقة كاملة: تهيئة المستثمرين وإعداد الصفقات والتقارير والحوكمة في سير عمل رقمي واحد، مع خدمات ضمان وترتيب مرخّصة في سوق أبوظبي العالمي، ودعمت أكثر من 250 مليون دولار في 207 صفقات.'),
  ('ST_650', 'منصة سعودية مدعومة بالذكاء الاصطناعي تمكّن المحامين والفرق القانونية من تحليل العقود وصياغة المذكرات والدعاوى بدقة عالية، مع محرك بحث ذكي يغطي أكثر من 450 نظامًا ولائحة سعودية، يختصر ساعات البحث والعمل اليدوي إلى ثوانٍ ويرفع كفاءة الفرق حتى 70%.'),
  ('ST_651', 'Bus14 منصة للنقل المدرسي تقدّم رحلات مدرسية آمنة ومريحة وبأسعار مناسبة للطلاب.'),
  ('ST_652', 'شركة سعودية للتقنية الرياضية مقرها جدة، تقدّم منصة متكاملة لإدارة ملاعب البادل والتنس تجمع حجز الملاعب الذكي وتسجيل الفيديو بدقة 4K وتحليل الأداء بالذكاء الاصطناعي والمدفوعات وأدوات تفاعل اللاعبين، عبر التطبيق والموقع وواتساب، للمنشآت الرياضية واللاعبين.'),
  ('ST_653', 'Synclane شركة استشارات تقنية في المملكة، ومنصتها الرئيسية Tijori نظام سحابي حديث لإدارة الخزينة يمنح الفرق المالية رؤية وتحكمًا لحظيين في النقد والتسهيلات البنكية والاستثمارات والمخاطر، دون تكلفة الأنظمة القديمة أو تعقيدها. يوحّد إدارة السيولة والقروض والاستثمارات والتمويل التجاري والمدفوعات والمطابقة ومحاسبة الخزينة الآلية ومراقبة الامتثال وفق متطلبات البنك المركزي وهيئة الزكاة.'),
  ('ST_654', 'مرسم نظام تشغيل للأعمال مدعوم بالذكاء الاصطناعي يساعد الشركات على البناء والإطلاق والنمو رقميًا دون خبرة تقنية، من المواقع والصفحات التعريفية إلى الأتمتة والتفاعل مع العملاء وعمليات الأعمال.'),
  ('ST_655', 'مجتمعات شركة سعودية في التقنية العقارية تبني منظومة رقمية موحّدة لجمعيات الملاك، تمتد ببرنامج «ملاك» التابع للهيئة العامة للعقار إلى الجانب التشغيلي، وتجمع الحوكمة والمالية والصيانة والمجتمع في منصة واحدة للقادة والمديرين والملاك والمستأجرين.'),
  ('ST_656', 'Handl Hub عقل العمليات بالذكاء الاصطناعي لتجار التجارة الإلكترونية في السعودية والخليج، مبني بالعربية أولًا ومتكامل مع سلة وزد وShopify وTikTok، ويوحّد الطلبات والمخزون وخدمة العملاء والمحتوى والإعلانات وتحسين الظهور في مركز تحكم ذكي واحد.'),
  ('ST_657', 'سكاكر برنامج ولاء بسيط وودود للتجارة الإلكترونية، يتيح لعملاء متجرك جمع النقاط والاستمتاع والفوز بالمكافآت أثناء التسوق، ويشجعهم على العودة مرارًا بمزايا ممتعة كالاسترداد النقدي وبطاقات الأختام و«اكشط واربح»، فيزيد التفاعل والزيارات المتكررة والمبيعات.'),
  ('ST_658', 'خدمة نشر سحابي مُدار للمؤسسين غير التقنيين الذين يبنون تطبيقاتهم بأدوات البرمجة بالذكاء الاصطناعي مثل Bolt وLovable وReplit؛ نأخذ الشيفرة الجاهزة وننشرها على بنية سحابية آمنة ونتولى الاستضافة والصيانة.'),
  ('ST_659', 'ثيابي المنصة الأولى لبيع وشراء الأزياء والإكسسوارات المستعملة في المملكة، بعملية آمنة وبسيطة ومستدامة تربط محبي الأزياء الراغبين في منح القطع المستعملة حياة جديدة، سواء كنت تفرّغ خزانتك أو تبحث عن قطعتك المفضلة القادمة.'),
  ('ST_660', 'منصة برمجية للشركات تساعد المؤسسات السعودية على تحقيق الوضوح التشغيلي والامتثال التنظيمي.'),
  ('ST_661', 'ذكاء تشغيلي للأعمال: نحوّل كل كاميرا إلى وكيل ذكاء اصطناعي يرصد الأحداث المهمة للأعمال لحظيًا.'),
  ('ST_662', 'ZORY AI منصة مدعومة بالذكاء الاصطناعي لتصور التصميم الداخلي والتجارة، تخدم قطاعات الأثاث والديكور والعقار والتقنية العقارية، وتساعد الملاك والمصممين وتجار الأثاث والمطوّرين على تحويل الصور والرسومات والمخططات إلى تصاميم غرف واقعية، وتربط التصميم باكتشاف المنتجات المناسبة وشرائها، ما يحسّن تفاعل العملاء ومعدلات الشراء ويقرّب المسافة بين الإلهام والتنفيذ.'),
  ('ST_663', 'طموحنا بناء بنك رقمي للطاقة تصبح فيه الطاقة أصلًا استثماريًا قابلًا للتداول، عبر ثلاث مراحل: أولًا تجميع سوق الطاقة في منصة رقمية تربط العملاء بمزوّدي خدمات الطاقة (وقد نُفّذت عبر منصة Re-New Bank التي تتيح مقارنة عروض متعددة خلال دقائق)، ثم بناء منظومة تجمع المستثمرين والعملاء لتمويل مشاريع الطاقة مباشرة، وأخيرًا إشراك الجهات الحكومية والمؤسسات الكبرى لطرح مشاريع الطاقة المتجددة على المستثمرين وصولًا إلى سوق طاقة متكامل.'),
  ('ST_664', 'لينك عربي منصة عربية لإنشاء صفحة بسيطة تجمع روابط التواصل الاجتماعي وواتساب والمنتجات، لتعرض الشركات منتجاتها وتستقبل الطلبات مباشرة عبر واتساب.'),
  ('ST_665', 'ذكاء اصطناعي يفهم الفيديو المباشر على نطاق وطني، مصمَّم لأمن المملكة وسيادتها التشغيلية، يحوّل الكاميرات المتفرقة إلى شبكات استخبارات موحّدة تقدّم رؤى موثّقة تدعم اتخاذ القرار في البنية التحتية الحيوية والحدود والفعاليات الكبرى.'),
  ('ST_666', 'Printo Go منصة طباعة عبر الجوال مقرها الرياض، تتيح رفع ملفات PDF واختيار مقاس الورق والألوان وعدد النسخ وخيارات التشطيب وموقع التوصيل وطريقة الدفع من تطبيق واحد، مستندة إلى أكثر من 14 عامًا من الخبرة في الطباعة، وتخدم العملاء في الرياض.'),
  ('ST_667', 'جبر منصة محاسبة مدعومة بالذكاء الاصطناعي للشركات السعودية، تدير المحاسبة ومسك الدفاتر وضريبة القيمة المضافة والزكاة والرواتب والمخزون والقوائم المالية والإقرارات الضريبية في مكان واحد وفق معايير الهيئة السعودية للمحاسبين وأنظمة هيئة الزكاة. يمكن استخدامها نظامًا محاسبيًا كاملًا أو ربطها بمساعدات ذكية لطلب المهام بلغة طبيعية، فتنجز في دقائق ما يستغرق عادة ساعات أو أيامًا.'),
  ('ST_668', 'TotalPay مزوّد خدمات تقنية لمدفوعات التجارة الإلكترونية معتمد من البنك المركزي السعودي، يقدّم بوابة دفع آمنة وقابلة للتوسع وحلولًا لتنسيق المدفوعات، تشمل التوجيه عبر عدة بوابات وروابط الدفع والمدفوعات المتكررة والترميز ومدفوعات QR والإضافات والواجهات البرمجية وتقارير التجار.'),
  ('ST_669', 'منصة تعليمية عربية تزوّد المعلمين بشاشة تفاعلية ومجموعة أدوات ذكية لإدارة الحصص وأنشطة الفصل من مكان واحد، تعمل مباشرة عبر المتصفح، وتساعد المعلمين والمدارس على تقديم دروس أكثر تفاعلًا وتنظيمًا داخل الفصل وفي التعليم عن بُعد.'),
  ('ST_670', 'صناديق الزعفران متجر متخصص في المملكة يقدّم أنواعًا متعددة من الزعفران للقهوة العربية والسعودية والطبخ والضيافة والهدايا.'),
  ('ST_671', 'بوكرا منصة عربية لإدارة وحجز الشاليهات والاستراحات والمخيمات والإيجارات قصيرة المدى في السوق السعودي، تساعد الملاك على إدارة الحجوزات وتقويم التوفر والعربون والمبالغ المتبقية والمصروفات والعقود الإلكترونية والإشغال والتقارير من لوحة واحدة، مع صفحة حجز خاصة لكل عقار.'),
  ('ST_672', 'Altaius شركة تقنية سعودية تبني محاكاة قيادية ثنائية اللغة بالذكاء الاصطناعي للمؤسسات في المملكة والخليج، تمنح المديرين بيئة آمنة للتدرّب على المحادثات الحساسة والتفاوض واتخاذ القرار مع ملاحظات منظمة ورؤى سلوكية قابلة للقياس، إضافة إلى خدمات تكامل الأنظمة من الاستراتيجية التقنية إلى حلول السحابة والبيانات والذكاء الاصطناعي والأتمتة.'),
  ('ST_673', 'شركة ناشئة واعدة. تمكّن 4Rounds المؤسسات من قياس نضجها المؤسسي وتحديد نقاط قوتها وفرص التحسين وإعداد تقارير تنفيذية وخرائط طريق عملية عبر منصة مؤتمتة بالكامل مبنية على أفضل الممارسات الدولية، وتشمل تقييمات نضج المؤسسة ومكتب إدارة المشاريع ومكتب الاستراتيجية ومكتب التحول والحوكمة.'),
  ('ST_674', '4th Layer مزوّد رائد لحلول التصنيع المتقدم، متخصص في التصميم الميكانيكي ثلاثي الأبعاد وتطوير حلول أتمتة مخصصة مبتكرة وإنتاج قطع غيار مخصصة عالية الجودة باستخدام تقنيات الطباعة ثلاثية الأبعاد، لمساعدة العملاء على رفع الإنتاجية وتحسين الجودة وخفض التكاليف.'),
  ('ST_675', 'تبني 7amdaan.io الجيل القادم من التفاعل والإعلانات الخارجية عبر روبوتات ذاتية مدعومة بالذكاء الاصطناعي تتنقل في المراكز التجارية والمطارات والمعارض والجامعات والمدن الذكية لتقديم تجارب تفاعلية ومحادثات وألعاب، إضافة إلى دعم التعليم وإرشاد الزوار والإعلانات والاستبيانات، مع تحليلات لحظية للجمهور دون تخزين صور أو مقاطع شخصية.'),
  ('ST_676', 'البرمجة بالذكاء الاصطناعي لبناء تطبيقات المؤسسات.'),
  ('ST_679', 'تطوّر ADADK منصة إنذار مبكر بالذكاء الاصطناعي تكتشف تسربات المياه وتلوثها قبل حدوث أضرار إنشائية أو بيئية، وتحوّل البيانات المعقدة إلى رؤى عملية عبر إنترنت الأشياء ولوحات متابعة لحظية، لتمكين المدن والمباني الذكية والمنشآت الزراعية ومحطات التحلية من حماية المياه وترشيد الطاقة والحد من الهدر.'),
  ('ST_680', 'AOF إطار حوكمة قابل للبرمجة يحوّل الإجراءات المتوافقة مع السياسات إلى أدلة يمكن التحقق منها رياضيًا، ويعمل عبر قطاعات منها البنوك والجهات التنظيمية والمنشآت الصغيرة وضمان الحلال، مع دمج منصة «سكن وقف إكس» لإطلاق قيمة المنازل في المملكة دون بيعها، بحد أدنى للاستثمار بين 1,500 و2,500 ريال، وجزء من العوائد لوقف دائم للإسكان الميسّر.'),
  ('ST_681', 'آدم هيلث أول مركز صحي رقمي في المملكة مخصص للرجال، يجعل الرعاية أسهل وأكثر خصوصية واستباقية، خاصة للمشكلات التي يؤجلها الرجال. يقدّم عبر منصة عربية أولًا استشارات عن بُعد للحالات الحساسة مع توصيل الأدوية بسرية، وتحاليل وقائية وتقارير صحية مخصصة، ورعاية أولية مدعومة بالذكاء الاصطناعي، مع بقاء الأطباء في صميم الرعاية السريرية.'),
  ('ST_682', 'نبني حلًا قانونيًا بالذكاء الاصطناعي لتحويل السوق القانوني: أنشئ أي مستند قانوني وعدّله وراجعه وتأكد من امتثاله بالذكاء الاصطناعي الآن.'),
  ('ST_684', 'تقدّم شركة القرن المتقدمة لتقنية المعلومات عبر منظومة Boardz حلولًا متكاملة للحوكمة والتحول الرقمي تجمع الاستشارات المتخصصة ومنصة تقنية قوية، لبناء أطر الحوكمة والسياسات والإجراءات وإدارة أعمال مجالس الإدارة والإدارة التنفيذية، وتحويل الاستراتيجيات إلى تنفيذ قابل للقياس، مع إدارة الاجتماعات والقرارات والمشاريع ومؤشرات الأداء والمستندات في بيئة رقمية واحدة.'),
  ('ST_685', 'نبني منصة سعودية لتخطيط موارد المؤسسات تجمع المحاسبة والمخزون ونقاط البيع وعمليات الأعمال الأساسية، لتمكين المنشآت الصغيرة والمتوسطة من تحول رقمي فعّال ومتوافق مع الأنظمة.'),
  ('ST_687', 'AI Geo Navigators شركة للذكاء المناخي والمعلومات الجغرافية تحوّل البيانات المناخية والبيئية إلى رؤى عملية بدمج الذكاء الاصطناعي مع نظم المعلومات الجغرافية والاستشعار عن بُعد، وتعمل في التكيف المناخي والحد من مخاطر الكوارث والإنذار المبكر وتقارير الاستدامة، مع تدريب جيل جديد من المتخصصين في المناخ والذكاء الاصطناعي.'),
  ('ST_688', 'تبني Aikido Security برمجيات تؤمّن نفسها لفرق التطوير الحديثة، عبر منصة أمنية موحّدة تحمي الشيفرة والسحابة وبيئة التشغيل دون إبطاء التطوير. أسرع شركة أوروبية للأمن السيبراني تبلغ قيمة المليار دولار، ويثق بها أكثر من 100,000 فريق، وأحدث إصداراتها اختبار اختراق مستمر بالذكاء الاصطناعي.'),
  ('ST_689', 'يستفيد ذكاؤنا الاصطناعي من كاميرات المراقبة الحالية لتحليل أحداث السلامة والإنتاجية والأمن لحظيًا وإرسال التنبيهات.'),
  ('ST_691', 'Aipathos شركة سعودية للذكاء الاصطناعي تبني حلولًا عملية تغيّر طريقة عمل الشركات وتفاعلها مع عملائها. منتجها الرئيسي FlyThru منصة طلبات بالذكاء الاصطناعي لقطاع الأغذية والمشروبات تتيح الطلب بالمحادثة الصوتية الطبيعية والطلب الرقمي، وتتكامل مع أنظمة نقاط البيع والدفع، وعالجت أكثر من 40,000 طلب في أقل من شهرين.'),
  ('ST_692', 'AiTech-USA شركة تقنية أمريكية تطوّر أجهزة صحية قابلة للارتداء ومنصات رقمية ذكية مبنية على تقنيات استشعار حيوي وذكاء اصطناعي حاصلة على براءات اختراع، ومن منصاتها: Smart GlucoRing لقياس السكر دون وخز، وSmart VitaRing لمتابعة ضغط الدم والتنفس والنبض والأكسجين والنوم والتوتر والنشاط، وSmart MakkaRing لدعم الحجاج والمعتمرين صحيًا ومكانيًا وإرشاديًا مع إبقاء عائلاتهم على اطلاع.'),
  ('ST_693', 'تشغّل شركة عجلتي لتجارة قطع غيار السيارات منصة B2BPartsHub لتوفير قطع غيار أصلية للعملاء الدوليين بأسعار تنافسية عبر التوريد العالمي، معتمدة على الأتمتة والذكاء الاصطناعي لتبسيط العمليات وتقديم خدمة متسقة.'),
  ('ST_695', 'مثمّن يجعل القرارات العقارية بسيطة بعرض القيمة الحقيقية للعقار وجودة الحي والتوقعات المستقبلية للمنطقة، لمساعدتك على تقرير ما إذا كان الشراء أو الاستثمار خيارًا ذكيًا.'),
  ('ST_698', 'بنك أسئلة تفاعلي بأسلوب الألعاب والمكافآت يغطي جميع الأنظمة التعليمية.'),
  ('ST_699', 'عالِم منصة لتعليم القرآن الكريم مدعومة بالذكاء الاصطناعي، تجمع التفسير والحفظ والتجويد في تجربة واحدة موثوقة للمتعلمين الأفراد والمدارس، ليصل معنى كل آية فعلًا.'),
  ('ST_700', 'بسّط عمليات DevOps من المراقبة إلى الاستعادة الآلية: AlertMend منصة مراقبة وأتمتة بالذكاء الاصطناعي لفرق التطوير والتشغيل، ترى كامل البنية من Kubernetes والخوادم والسحابة والتطبيقات وقواعد البيانات، وتكتشف الأسباب الجذرية بسرعة، وتجمع الاستجابة للحوادث والمعالجة الآلية، مع إمكانية التشغيل سحابيًا أو ذاتيًا.'),
  ('ST_701', 'تبني ALFIA نظام تشغيل للشركات الناشئة والبرامج، يساعد المؤسسين على التنفيذ، والمسرّعات والحاضنات على إدارة محافظها، والمستثمرين على متابعة التقدم الفعلي لحظيًا بالذكاء الاصطناعي.'),
  ('ST_702', 'حلول لإدارة الطاقة والصيانة.'),
  ('ST_703', 'وكلاء صوتيون بالذكاء الاصطناعي للغة العربية.'),
  ('ST_704', 'لا تحصل المتاجر الصغيرة على قروض متناهية الصغر لضعف الخدمات المقدّمة لها، بينما تمنحها شركات السلع الاستهلاكية الكبرى ائتمانًا عالي المخاطر دون تقييم.'),
  ('ST_706', 'تبني AllyTech مجموعة من البرمجيات المتخصصة في الذكاء الاصطناعي والأمن السيبراني والبنية التحتية الرقمية، لتأمين عمليات المؤسسات وتحسينها وتحويلها.'),
  ('ST_708', 'تداول كمّي مدعوم بالذكاء الاصطناعي في السوق السعودي والأسواق العالمية: إشارات مؤتمتة واستراتيجيات محافظ ذكية وأداء فعلي يتفوق على الاستثمار التقليدي.'),
  ('ST_709', 'منصة امتثال تنظيمي مدعومة بالذكاء الاصطناعي تساعد المؤسسات على الامتثال بسهولة واستباقية ودقة.'),
  ('ST_712', 'سوق آمن لمستلزمات الأطفال: بِع واشترِ القطع المستعملة بحالة جيدة أو المفتوحة أو الفائضة، ووفّر المال وادعم دورة أكثر استدامة وصداقة للبيئة.'),
  ('ST_714', 'يختار المتسوقون ووكلاء الذكاء الاصطناعي مشترياتهم عبر ChatGPT وغيره، لكن معظم المتاجر لا تعرف من وصل إليها ولا المبيعات القادمة منهم. يكشف Arbling ما إذا كان الزائر شخصًا أرسله الذكاء الاصطناعي أو وكيل تسوق أو روبوتًا، ويتتبع المنتجات التي تفاعل معها وهل اشترى، ليساعد التجار على إزالة عوائق البيع والاستفادة من إيرادات التجارة الوكيلية.'),
  ('ST_715', 'يحوّل Argami الأرقام والتقارير المربكة إلى شرح بسيط ويوضح معناها وكيفية استخدامها لاتخاذ قرارات أفضل. منتجه الأساسي منصة تحليلات بالمحادثة تتيح التفاعل مع بيانات المؤسسة باللغة الطبيعية والحصول على إجابات دقيقة وموثوقة، مبنية على طبقة دلالية محكومة تجعل البيانات جاهزة للذكاء الاصطناعي.'),
  ('ST_717', 'asilla برنامج أمني مبني على الذكاء الاصطناعي يحوّل كاميرات المراقبة الحالية إلى أنظمة ذكية تعمل على مدار الساعة بإضافة خادم محلي فقط، فيكتشف السلوكيات غير الطبيعية ويرسل تنبيهات فورية، ويعمل في أكثر من 200 موقع كبير في اليابان منها مجمعات تجارية ومحطات ومطارات.'),
  ('ST_718', 'Aspired Health شركة ناشئة في التقنية الصحية توظّف الذكاء الاصطناعي والحلول المعتمدة على البيانات لتحويل تقديم الرعاية الصحية، وتطوّر أدوات صحية رقمية تمكّن مقدّمي الرعاية والمرضى وتحسّن النتائج السريرية والكفاءة التشغيلية.'),
  ('ST_721', 'AtharX شركة ناشئة سعودية في التقنيات العميقة تبني تقنيات محاكاة سيادية عالية الدقة مسرّعة بالذكاء الاصطناعي لقطاعات الفضاء والطيران والدفاع والطاقة والمدن الذكية، بالجمع بين النمذجة متعددة الفيزياء وديناميكا الموائع الحسابية والحلول المعتمدة على تعلّم الآلة، دعمًا للاعتماد على الذات ورؤية 2030.'),
  ('ST_724', 'تحوّل AudienceJet واتساب مطعمك إلى نظام طلبات مؤتمت بالكامل: يتصفح العملاء القائمة ويطلبون ويدفعون إلكترونيًا ويتتبعون التوصيل داخل واتساب.'),
  ('ST_726', 'Autilent منصة ذكاء اصطناعي تعمل داخل المركبات أثناء حركتها، ترصد الطريق والسائق لحظيًا وتولّد رؤى قيّمة.'),
  ('ST_727', 'نحوّل البصمات الرقمية للعاملين والعربات والرافعات إلى رسوم ومؤشرات واضحة تكشف الازدحام والتأخير، ونقدّم تخطيطات محسّنة لسير عمل أسرع وأكثر أمانًا.'),
  ('ST_728', 'LXERA عصر جديد في بناء التدريب وتصميمه وتقديمه، تساعد المدربين وفرق التعلّم والتطوير والمستشارين على تحويل خبراتهم إلى برامج تدريبية كاملة جاهزة للتقديم، من وحدات ودروس ودراسات حالة وتمارين وتقييمات، تُولَّد من طلب واحد وتُحسَّن بالمحادثة.'),
  ('ST_729', 'Axis Digital شركة تقنية تساعد المؤسسات على تحسين الحوكمة والامتثال والذكاء المالي عبر برمجيات مؤسسية مبتكرة، منها Diskus Board لاجتماعات مجالس الإدارة والتعاون الآمن، وDiskus Flow لأتمتة الامتثال وسير العمل، وواجهات Tresmark لبيانات الأسواق المالية اللحظية والتاريخية.'),
  ('ST_730', 'نبني حلولًا ذكية لإدارة الوقود لمحطات الوقود والمنشآت الصناعية، تساعدها على تتبع الوقود وتقليل الفاقد وخفض التكاليف والتوجه نحو طاقة أنظف.'),
  ('ST_731', 'تقدّم Banana حلول بنية تحتية للسوبرماركت: نظام واحد للمبيعات الإلكترونية والحضورية، متصل بجميع تطبيقات التوصيل الكبرى مع مزامنة لحظية للمخزون والأسعار.'),
  ('ST_733', 'بيتين شركة ناشئة في التقنية العقارية متخصصة في الإيجارات قصيرة ومتوسطة المدى، تقدّم إدارة متكاملة للعقارات وخدمات تشغيلية، وأدوات تقنية متقدمة تضمن أفضل نسب إشغال وعوائد مجزية للملاك.'),
  ('ST_734', 'نبني نظام موارد بشرية مجانيًا وبسيطًا يستبدل الطرق التقليدية المعقدة، ويساعد المنشآت الصغيرة على إدارة الموظفين والرواتب والامتثال بسهولة.'),
  ('ST_735', 'بساط منصة برمجية دون برمجة تتيح لك بناء أكاديميتك التدريبية الرقمية بعلامتك الخاصة وإطلاقها، مع الدورات والجلسات المباشرة والاستشارات والمدفوعات في دقائق.'),
  ('ST_738', 'أمن سيبراني كخدمة بنظام الاشتراك.'),
  ('ST_739', 'محرك ذكي للفوترة والدفع يتيح الدفع مباشرة داخل محادثات واتساب، ليساعد الشركات على تحصيل مستحقاتها أسرع وتقديم تجربة أسلس للعملاء.'),
  ('ST_741', 'Boost منصة ذكاء مبيعات مدعومة بالذكاء الاصطناعي لشركات السلع الاستهلاكية، تحوّل بيانات المبيعات والمخزون والتوزيع المتفرقة إلى لوحات جاهزة وتقارير مؤتمتة ورؤى عملية خلال أسابيع لا أشهر، وتثق بها علامات عالمية وإقليمية منها Mars Wrigley وRed Bull وSC Johnson وBarilla وDuracell.'),
  ('ST_742', 'نطوّر جهاز ذكاء اصطناعي محمولًا يعمل دون اتصال بحجم الجوال، يمكّن ذوي الإعاقة البصرية من الوصول المباشر إلى الذكاء الاصطناعي والتواصل في الاتجاهين عبر طريقة برايل اللمسية.'),
  ('ST_743', 'منصة للبرمجة بالذكاء الاصطناعي.'),
  ('ST_744', 'يساعد Brooch الملاك ومديري العقارات على تحصيل الإيجارات ومتابعة العقود وإدارة الصيانة في مكان واحد، ليحصل المستأجرون على خدمة أسرع ويبقى الملاك متحكمين.'),
  ('ST_748', 'تنقل BYOND Asia الذكاء الاصطناعي إلى العالم الحقيقي عبر HoloMe، بشر رقميون أذكياء يستمعون ويفهمون ويجيبون وينفّذون، من موظفي استقبال افتراضيين في المراكز التجارية ومحطات النقل والخدمات الحكومية إلى مساعدين للمؤسسات، بمحادثات طبيعية متعددة اللغات توفّر الوقت والتكلفة.'),
  ('ST_750', 'أفقد ChatGPT السيرة الذاتية مصداقيتها. يتحقق CandiScan من المرشحين عبر مقابلة فيديو تمهيدية تكيفية مدتها 30 دقيقة مبنية على سيرتهم الذاتية، ويقدّم ملف حالة بدل درجة رقمية يوضح السؤال والإجابة والتوقيت والسبب لكل ملاحظة، والقرار لك. متوافق مع اللائحة الأوروبية لحماية البيانات وقانون الذكاء الاصطناعي الأوروبي، ويدعم أكثر من 20 لغة منها العربية.'),
  ('ST_752', 'cardoO علامة إلكترونيات استهلاكية تأسست في مصر، تقدّم أجهزة ذكية بالذكاء الاصطناعي بأسعار مناسبة ومصمَّمة لمنطقة الشرق الأوسط وشمال أفريقيا، منها الساعات والخواتم الذكية والسماعات العازلة للضوضاء والموازين الذكية ونظارات الواقع الافتراضي، مع منظومة ذكاء اصطناعي محلية تتكيف مع أنماط الحياة في المنطقة ومنها إيقاع رمضان واللهجات العربية.'),
  ('ST_753', 'تبني Carely منصة متكاملة لرقمنة صالونات الحلاقة في المملكة، تشمل الحجز والدفع والولاء وخدمات الزيارة المنزلية، لمساعدة الحلاقين على النمو ومنح العملاء رعاية سلسة.'),
  ('ST_754', 'Carevision منصة حائزة على جوائز مدعومة بالذكاء الاصطناعي تحوّل مسحًا للوجه مدته 60 ثانية إلى معلومات صحية عملية، فتكتشف مؤشرات حيوية رقمية مرتبطة بـ14 مرضًا قلبيًا واستقلابيًا وتصنّف المخاطر فورًا، وتتكامل عبر واجهات برمجية مع تطبيقات الشركاء والعيادات الرقمية، لتمكين المستشفيات وشركات التأمين والصيدليات والحكومات من الفحص المبكر على نطاق واسع بتكلفة أقل، بدقة 97% في التنبؤ القلبي.'),
  ('ST_755', 'يضيّع المستثمرون الأفراد كل صباح في الفرز والرسوم البيانية وحساب المخاطر يدويًا، ويختصر Chartex ذلك: اسأل عما تريد واحصل على إجابة واضحة في أقل من ثانية. تحليل لا نصيحة، ومتاح اليوم.'),
  ('ST_756', 'نستخدم الذكاء الاصطناعي لتحويل رموز QR في اللوحات الإعلانية إلى محادثات واتساب فورية، فبدل إرسال المستخدمين إلى صفحات ثابتة يتحدثون مباشرة مع المنتج أو الخدمة ويتحولون إلى عملاء في الحال.'),
  ('ST_757', 'تصنع Classy Games ألعابًا ممتعة تشعل الخيال وتوقظ الطفل في داخلك، لتعيد اكتشاف متعة اللعب.'),
  ('ST_759', 'مساعد ذكاء اصطناعي من الجيل القادم يخفف الأعباء الإدارية والذهنية عن الأطباء، لتحقيق نتائج صحية أفضل.')
) as v(id, ar)
where s.startup_id = v.id;

update public.startups as s set startup_description_ar = v.ar
from (values
  ('ST_760', 'نبني منصة متكاملة لنقاط البيع والمدفوعات تساعد المطاعم ومتاجر التجزئة على إدارة المبيعات والمدفوعات والمخزون والولاء، عبر الإنترنت أو دونه، وعلى أي جهاز.'),
  ('ST_761', 'يخسر المصنّعون الملايين لأن تقدير التكاليف يعتمد على مراجعة الرسومات يدويًا وفحص القطع فعليًا، دون ذكاء اصطناعي أو روبوت يربط التصميم بأرضية المصنع لحظيًا.'),
  ('ST_762', 'نزيل عوائق النمو ليتفرغ البائعون للبيع.'),
  ('ST_763', 'Constems AI Systems شركة تقنيات عميقة في الرؤية الحاسوبية بالذكاء الاصطناعي تأسست عام 2017، تبني أنظمة ذكية تمكّن المؤسسات من رؤية العالم المادي وفهمه والتصرف فيه لحظيًا، عبر محرك CAInatics ونموذجها البصري متعدد الوسائط، لقطاعات التجزئة والتصنيع والزراعة والخدمات اللوجستية والرعاية الصحية والبنية التحتية.'),
  ('ST_764', 'منصة لتنسيق المحتوى بالذكاء الاصطناعي للمؤسسات، توحّد سير العمل وتؤتمت إنتاج المحتوى وتضمن الحوكمة والامتثال والاتساق بين الفرق حول العالم.'),
  ('ST_766', 'تطبيق ألعاب كرة قدم يغطي الدوري السعودي والدوريات الأوروبية الكبرى باللغتين الإنجليزية والعربية، استقطب 150 ألف مستخدم في الموسم الماضي شاركوا في أكثر من مليوني مسابقة بميزانية تسويق محدودة، ويجمع الآن تمويلًا للتوسع مع مستثمر رئيسي مؤكد.'),
  ('ST_769', 'Craftle طبقة برمجية لمراكز البيانات للتنبؤ بالتكاليف والجاهزية والقدرة الحاسوبية وعوائد المشاريع.'),
  ('ST_770', 'تطوّر Creative AI حلول ذكاء اصطناعي تضع العربية أولًا لإدارات خدمة العملاء، تؤتمت التفاعل مع العملاء وتقيّم المحادثات وتراقب الجودة وتحسّن أداء الموظفين عبر المكالمات والمحادثات، مع دعم التشغيل السحابي والمحلي للمؤسسات والجهات الحكومية.'),
  ('ST_771', 'تبني Ctruh طبقة البنية التحتية للإنترنت المكاني، فتشغّل المحتوى ثلاثي الأبعاد عالي الدقة والذكاء الاصطناعي والواقع الممتد مباشرة في المتصفح على أي جهاز دون تنزيل، عبر محرك Verse Engine الحاصل على براءة اختراع، وطبقة VersaAI التي تحوّل النصوص والصور والفيديو إلى نماذج ثلاثية الأبعاد في دقائق. تخدم العقار والتجزئة والسيارات والتصنيع والطاقة والتعليم والسياحة، تأسست عام 2023 في بنغالور بالهند، وتدخل السوق السعودي ضمن رؤية 2030.'),
  ('ST_772', 'CyberAgora شركة تقنية سعودية تبني حلولًا ذكية لعمليات الأعمال الحديثة، ومنتجها الرئيسي OSS (نظام نجاح العمليات) أساس ذكي واحد يوحّد العمليات متعددة القنوات ويبسّطها في تجربة العملاء والمخزون والخدمات اللوجستية والقوى العاملة، لخفض التكاليف وزيادة الإيرادات ورفع الكفاءة.'),
  ('ST_773', 'CyberFortX مزوّد رائد للأمن السيبراني والخدمات الأمنية المُدارة، متخصص في اكتشاف التهديدات والاستجابة لها وخدمات مراكز العمليات الأمنية وإدارة الثغرات وأمن السحابة واستشارات الامتثال، لتمكين المؤسسات في المنطقة من حماية أصولها الرقمية الحيوية.'),
  ('ST_774', 'نساعد المؤسسات على توسيع التدريب على الأمن السيبراني دون تكاليف تشغيلية عالية، عبر منصة سحابية تقدّم محاكاة بأسلوب الألعاب وتعلّمًا موجّهًا بالذكاء الاصطناعي وتقييمًا آليًا، وتُطبَّق حاليًا في مدارس كازاخستان وتتوسع في المنطقة والولايات المتحدة.'),
  ('ST_775', 'Dadan.io منصة فيديو بالذكاء الاصطناعي لإنشاء فيديوهات المنتجات والشروحات والأدلة خطوة بخطوة في مكان واحد، مع التحرير والترجمة إلى 180 لغة والمشاركة عبر الإنترنت مع نماذج تفاعلية ودعوات لاتخاذ إجراء.'),
  ('ST_777', 'Dapti منصة تعلّم بالذكاء الاصطناعي تجعل التعلّم أكثر فاعلية وتخصيصًا ومتعة، وفلسفتها «التعلّم بالممارسة» عبر التمرين المستمر والتغذية الراجعة والتصحيح والتقدّم، وتتكيف مع مهارات كل طالب، وتقدّم للمعلمين والمدارس أدوات لإدارة الفصول وتخطيط التعلّم وتقارير ورؤى لكل مستوى إداري.'),
  ('ST_778', 'نصنّع حلولًا روبوتية آلية لتنظيف الألواح الشمسية ترفع إنتاج الطاقة وتوفّر المياه وتخفض التكاليف، لتصبح الطاقة الشمسية أنظف وأكثر كفاءة للجميع.'),
  ('ST_779', 'DataBahn مستوى تحكم وكيلي بالبيانات للمؤسسات، تستقبل منصته بيانات التشغيل من أكثر من 600 مصدر وتوحّدها وتثريها وتحكمها وتوجّهها بحيادية تامة تجاه البيانات والذكاء الاصطناعي ودون ارتباط بمورّد، ومقرها دالاس وتخدم كبرى الشركات العالمية.'),
  ('ST_781', 'تساعد DefAi البنوك وشركات التقنية المالية في السعودية والخليج على اكتشاف الاحتيال مبكرًا عبر تنبيهات ذكاء اصطناعي قابلة للتفسير وترتيب أذكى للحالات وتحقيقات أسرع، باستخدام إشارات سلوكية ومعاملاتية موحّدة.'),
  ('ST_782', 'نجعل الكاميرات ذكية لتتبع العاملين وفهم العملاء وقياس الإعلانات لحظيًا.'),
  ('ST_783', 'DermaScan جهاز محمول لتصوير الجلد وتحليله يساعد الأطباء على تقييم الحالات الجلدية في موقع الرعاية، يلتقط صورًا مفصلة ويحللها داخل الجهاز ويقدّم قائمة قصيرة بالحالات المحتملة، ويعمل دون اتصال مع إبقاء بيانات المريض على الجهاز.'),
  ('ST_784', 'DIGISEC شركة متخصصة في التوعية بالأمن السيبراني وإدارة المخاطر البشرية مقرها الرياض، تساعد المؤسسات على قياس المخاطر السيبرانية البشرية وإدارتها وتقليلها عبر برامج توعية متقدمة ومحاكاة التصيّد وتحليل السلوك وتدريب القيادات، وتصمّم محتوى توعويًا مخصصًا ودورات إلكترونية وفعاليات وورش عمل لبناء ثقافة أمنية قوية.'),
  ('ST_785', 'نمكّن أي مصنع من أن يصبح ذكيًا بالكامل باستخدام مستشعر ذكاء اصطناعي واحد.'),
  ('ST_786', 'نبني مستقبل توريد مواد البناء.'),
  ('ST_788', 'نجعل المطاعم والمقاهي في أعلى درجات الكفاءة.'),
  ('ST_789', 'منظومة تقنية لرقمنة التجارة بين علامات الإلكترونيات والموزعين وتجار التجزئة وتحسينها، تجمع تطبيق سوق وتطبيقًا شاملًا للمندوبين الميدانيين وبوابة لإدارة التجارة.'),
  ('ST_791', 'Dovera.ai منصة لتجربة العملاء مبنية على الذكاء الاصطناعي، توحّد المبيعات والدعم والتسويق في مساحة عمل ذكية واحدة يعمل فيها وكلاء ذكاء اصطناعي ذاتيًا بلغة العميل ولهجته على مدار الساعة. تجمع محادثات واتساب وإنستغرام وماسنجر والموقع وتيليجرام وتيك توك في صندوق وارد موحّد، وتفهم اللهجات العربية الحقيقية، وتبني نظام إدارة علاقات العملاء تلقائيًا من المحادثات، وتشمل التذاكر والحملات والحجوزات ولوحات المتابعة، وعالجت أكثر من 5 ملايين تفاعل في 5 دول.'),
  ('ST_792', 'تبني DPhi Space أقمارًا صناعية مبنية على الذكاء الاصطناعي مزودة بمعالجات رسومية وكاميرات عالية الدقة، لتشغيل نماذج الذكاء الاصطناعي مباشرة في المدار وتوليد الرؤى لحظة وقوع الحدث على الأرض. نفّذت مهمتين فضائيتين، وكانت الأولى في تشغيل نموذج رؤية ولغة على متن قمر صناعي، ويُطلق قمرها القادم عام 2027.'),
  ('ST_793', 'Drone Tech International شركة تقنية سعودية رائدة تقدّم حلول طائرات مسيّرة ذاتية مدعومة بالذكاء الاصطناعي وخدمات جوية متقدمة، تجمع الأنظمة الذكية والتشغيل الذاتي والتحليلات والمستشعرات المتخصصة لتحويل طريقة فحص الأصول والبنية التحتية ومراقبتها وتأمينها ومسحها، في قطاعات الطاقة والبناء والأمن والمرافق والمدن الذكية.'),
  ('ST_794', 'نبني مختبرات ذاتية بالذكاء الاصطناعي تكتشف مواد جديدة وتوسّع إنتاجها أسرع بـ10 إلى 50 مرة، فتحوّل عقودًا من البحث والتطوير الصناعي إلى أشهر وتسرّع الطاقة النظيفة والتصنيع المتقدم.'),
  ('ST_795', 'تساعد DuoKey المؤسسات المالية والجهات الخاضعة للتنظيم على الانتقال إلى التشفير المقاوم للحوسبة الكمية، إذ يكتشف ماسحها الأصول التشفيرية دون وكلاء ويصدر قائمة مواد تشفيرية ودرجة جاهزية كمية من 0 إلى 100، ثم يصوغ وكلاء الذكاء الاصطناعي التغييرات ويتحققون منها وينشرونها بموافقة بشرية وإمكانية تراجع موثّقة.'),
  ('ST_796', 'نبني منصة مدعومة بالذكاء الاصطناعي تشخّص أعطال السيارات وتقدّر تكاليف الإصلاح وتربطك بورش موثوقة وخدمات الطوارئ، وتبسّط مطالبات التأمين وتمويل الإصلاح.'),
  ('ST_798', 'EDEN منصة سفر اجتماعية تربط المسافرين حسب الوجهة والتوقيت والاهتمامات والتوافق، وتتيح اكتشاف مسافرين متشابهين والانضمام إليهم وإنشاء رحلات جماعية منسقة وتجارب سفر مخصصة بمطابقة ذكية، لتحويل السفر الفردي إلى تجارب مشتركة هادفة، بدءًا من أسواق سريعة النمو مثل المملكة.'),
  ('ST_804', 'emotii منصة تواصل متعددة اللغات تعمل مع مختلف نماذج الذكاء الاصطناعي، تساعد المؤسسات على التواصل بطبيعية عبر اللغات والأسواق والثقافات، مع الحفاظ على المعنى والسياق والنبرة والفروق الثقافية، وتدعم أكثر من 126 لغة مكتوبة و70 لغة منطوقة عبر حلول للاجتماعات والمؤتمرات والعروض والفيديو والمواقع وروبوتات المحادثة والواجهات البرمجية.'),
  ('ST_805', 'تساعد Engagesoft عملاءها على تعزيز ثقافة العمل وفاعلية القيادة بتحويل آراء الموظفين إلى خطط عمل، مستفيدة من الذكاء الاصطناعي والتحليلات المتقدمة.'),
  ('ST_806', 'نبني منصة تقنية حيوية بالذكاء الاصطناعي تكتشف سرطان الثدي مبكرًا باستخدام إشارات حيوية مخصصة، لنقل الرعاية الصحية من التشخيص المتأخر إلى الوقاية الدقيقة.'),
  ('ST_807', 'إشفاء منصة رعاية صحية رقمية (موقع وتطبيق)، وأول تطبيق متخصص في خدمات الكونسيرج الطبي بإدارة الحالات وتنسيق الرعاية للمرضى المحليين والدوليين، ويدعم الشركات ذاتية التأمين والسياحة العلاجية. يدير تجربة المريض بالكامل: الطب عن بُعد، والرعاية المنزلية قبل العمليات وبعدها والتأهيل، وإدارة الأمراض المزمنة ورعاية كبار السن، وحجز العيادات والعمليات والإسعاف، والصيدلية الرقمية، إضافة إلى خدمات صحية للشركات في المصانع والمناجم ومواقع العمل.'),
  ('ST_808', 'estaie أول منصة عالمية مبنية على الذكاء الاصطناعي للإقامات الممتدة (من 30 إلى 365 ليلة)، تستخدم تسعيرًا ديناميكيًا خاصًا يضمن خصمًا لا يقل عن 32% مقارنة بأي مزوّد آخر.'),
  ('ST_809', 'استكمال سوق للاندماج والاستحواذ والاستثمار في المنشآت الصغيرة والمتوسطة في المملكة، يربط البائعين بالمشترين والمستثمرين وصناديق الملكية الخاصة عبر منصة رقمية منظّمة وشفافة، مع عروض نشطة وصفقات مكتملة في قطاعات متنوعة.'),
  ('ST_810', 'نبني نوعًا جديدًا من أنظمة نقل الطاقة لاسلكيًا لتسريع الجيل الثاني من الكهربة.'),
  ('ST_811', 'تتيح RivalN للاعبين التنافس في ألعابهم المفضلة والتواصل مع مجتمعهم وكسب نقاط قابلة للاستبدال بقيمة حقيقية من العلامات التجارية.'),
  ('ST_813', 'Evolve Innovative Solutions شركة هندسية مبنية على الذكاء الاصطناعي، تأسست في سنغافورة وتعمل في دول آسيان، تبني أنظمة متكاملة بالذكاء الاصطناعي في كل طبقة حول احتياجات أعمال حقيقية، وتنقل العملاء من الطموح إلى التشغيل عبر إطار FORGE، مع حوكمة وأمن وامتثال مدمجة منذ البداية.'),
  ('ST_814', 'تبني exoheal قفازًا روبوتيًا مدعومًا بالذكاء الاصطناعي يساعد المصابين بشلل اليد على استعادة الحركة أسرع، ويجعل التأهيل عن بُعد وبتكلفة معقولة ومتاحًا للجميع.'),
  ('ST_816', 'نطوّر نظام نقل مداري عند الطلب، أشبه بـ«سيارة أجرة فضائية»، لحل مشكلة الميل الأخير في إيصال الأقمار الصناعية.'),
  ('ST_817', 'نعمل في Eyesight Electronics على تشخيص الغمش (كسل العين) وعلاجه، وهو يصيب 200 مليون شخص حول العالم.'),
  ('ST_818', 'يتيح حلنا «فاحص» الكشف المبدئي عن سرطان الثدي على مستوى وطني، دون تدخل جراحي ومع حفظ الخصوصية، ومتاحًا للنساء من جميع الأعمار، لاكتشاف السرطان مبكرًا وإنقاذ الأرواح على نطاق واسع.'),
  ('ST_819', 'تبني فلك فئة جديدة: شبكة هوية بأسلوب الألعاب تحوّل التقدم الشخصي والهوية والتواصل الاجتماعي إلى تجربة رقمية ممتعة واحدة.'),
  ('ST_822', 'محفظة تجزئة وبنية تحتية للذكاء: تمكّن Feddi تجار التجزئة من إطلاق محافظ بعلامتهم تدمج المدفوعات والمكافآت، وتحصيل الإيرادات مقدمًا، وتحويل المعاملات إلى رؤى عن العملاء تعزّز الولاء ونموًا متوقعًا للإيرادات.'),
  ('ST_824', 'نصنع ألعابًا عربية أصيلة ثقافيًا لمنطقة الشرق الأوسط وشمال أفريقيا، بدعم من ميراك ونشر مجموعة MBC، تجاوزت تنزيلاتها مليوني تنزيل، وظهرت مرتين على متجر Apple، وصُنّفنا ضمن أفضل 30 صانع ألعاب في المنطقة عامي 2022 و2025.'),
  ('ST_825', 'Flawless منصة لتوجيه المسار المهني للجيل الجديد الباحث عن مسيرة هادفة، تجمع علم النفس والعلوم السلوكية والتقنية الذكية لمساعدة الأفراد على اكتشاف ذواتهم وفهم نقاط قوتهم واهتماماتهم وقيمهم، والتنقل في مساراتهم المهنية بثقة، والتواصل مع مرشدين وأدوات تُحدث فرقًا حقيقيًا.'),
  ('ST_826', 'منصة مركزية واحدة تدمج جميع تطبيقات توصيل الطعام، وتؤتمت إدارة الطلبات، وتقدّم رؤى لحظية عن الأداء لمساعدة المطاعم والمقاهي على توفير الوقت ورفع الكفاءة.'),
  ('ST_827', 'Fortify Technologies شركة تقنية عقارية تقدّم حلولًا برمجية بالذكاء الاصطناعي لتبسيط المبيعات وإدارة العملاء والأملاك وعمليات الأعمال، وتخدم أكثر من 50 شركة في باكستان والسعودية والإمارات.'),
  ('ST_829', 'تبني FortyGuard نماذج حرارة عالية الدقة وواسعة النطاق تساعد المدن والمطوّرين والمؤسسات على فهم الحرارة الحضرية والتنبؤ بها والحد منها على مستوى الشارع.'),
  ('ST_830', 'جسر للتجارة الإلكترونية: تستخدم Fundero تحليل البيانات لتحويل بيانات المبيعات إلى حدود ائتمانية فورية، وتربط المنشآت الصغيرة والمتوسطة بشركاء تمويل مرخّصين لنمو سريع دون تعقيدات البنوك.'),
  ('ST_831', 'تمكّن Fundraizerly الشركات من إطلاق منصات أسواق رأس المال الخاصة بها، لجعل جمع رأس المال أسرع وأقل تكلفة وأسهل وصولًا.'),
  ('ST_832', 'تايقو مجمّع اتصالات مرخّص في المملكة، يجمع عروض الجوال وشرائح SIM والشرائح الإلكترونية وإعادة الشحن وخدمات الاتصالات من كبرى الشركات في منصة واحدة بسيطة، ليسهل على العملاء اكتشاف الخدمات المناسبة ومقارنتها والحصول عليها بتجربة رقمية سلسة.'),
  ('ST_833', 'نبني منصة بالذكاء الاصطناعي تجمع بيانات التسويق والمبيعات والموقع ووسائل التواصل في مكان واحد، وتحوّلها إلى رؤى واضحة وخطط عمل في دقائق بدل أسابيع.'),
  ('ST_835', 'منصة ألعاب مصمَّمة بأساليب علمية وممتعة للأطفال، تهدف إلى تنمية مهاراتهم الإدراكية وقدراتهم الأساسية اللازمة لعملية التعلّم.'),
  ('ST_838', 'تساعد Geojet العلامات متعددة الفروع على إدارة ملفاتها التجارية وسمعتها وعرض منتجاتها عبر بحث Google وخرائطه ومنصات المراجعات ومنها Apple وYango وTripadvisor ومتاجر التطبيقات، عبر لوحة واحدة بسيطة مع أتمتة ودعم مُدار.'),
  ('ST_840', 'غرفة تك منصة تأجير ذكية في المملكة تربط المضيفين بالضيوف، وتبسّط نشر العقارات وتسرّع الحجوزات لجعل الإيجار سريعًا وواضحًا وموثوقًا.'),
  ('ST_842', 'GoPal أول منصة سعودية بالذكاء الاصطناعي لأنشطة الأطفال، تحل حيرة الآباء في معرفة ما يتميز به أطفالهم وأين يجدونه: يبني اختبار المهارات ملف اكتشاف لكل طفل يحدد نوع ذكائه وشخصيته وأسلوب تعلّمه، ثم يوصي بالأنشطة المناسبة، مع إمكانية البحث والحجز والمتابعة لأكثر من 100 نوع من الأنشطة في مكان واحد.'),
  ('ST_844', 'تساعدك Grona على زيادة مبيعات موقعك بكشف أين ولماذا يغادر الزوار، ومعالجة هذه المشكلات مباشرة!'),
  ('ST_845', 'تبني GrowthLabs بنية رقمية لمنظومات ريادة الأعمال والابتكار، تمكّن الحكومات والجامعات والحاضنات والمسرّعات ومراكز الابتكار من إدارة البرامج بالكامل، وإرشاد المؤسسين، وقياس النتائج الموثّقة، وربط الشركات الناشئة بالمستثمرين والمرشدين والشركاء، عبر منتجاتها Catalyst وStartup Gate وStartPad.'),
  ('ST_853', 'استوديو هنقا استوديو ألعاب ثقافي سعودي يمزج التراث بالتقنية الحديثة، وتعيد لعبته إحياء الألعاب الشعبية مثل «أم تسعة» وتعلّم قواعدها وتراثها والتفكير الاستراتيجي بطريقة تفاعلية.'),
  ('ST_854', 'ذكاء اصطناعي صوتي باللهجة السعودية للعيادات، يرد على المكالمات والرسائل على مدار الساعة، ويحجز المواعيد، ويتواصل مع المرضى غير النشطين، ويقلّل الغياب، ليحوّل الطلب الضائع إلى إيرادات محجوزة تلقائيًا.'),
  ('ST_856', 'تساعد HookPhish المؤسسات على إيقاف هجمات التصيّد الاحتيالي بمحاكاة تهديدات واقعية، وتدريب الموظفين بسيناريوهات حقيقية، وقياس المخاطر البشرية قبل أن يستغلها المهاجمون.'),
  ('ST_859', 'Humentra طبقة ذكاء مبنية على الذكاء الاصطناعي للقوى العاملة لديك، تعمل فوق أنظمة إدارة رأس المال البشري الحالية وتقرأ بياناتها وتحوّلها إلى قرارات في التوظيف والمهارات ومقارنة الرواتب والتعاقب الوظيفي والتنقل الداخلي، عبر وكلاء ذكاء اصطناعي متخصصين يقدّمون التوصيات ويبقى القرار للبشر، مع 14 وحدة وإقامة للبيانات داخل المنطقة وحوكمة موثّقة، ويستخدمها أكثر من 2,000 مستخدم وتتوسع في الخليج.'),
  ('ST_862', 'Hydrosense Technology شركة ناشئة سعودية في التقنيات العميقة متخصصة في كشف الغازات ومراقبة جودة الهواء بالذكاء الاصطناعي، تجمع المستشعرات المتقدمة وتعلّم الآلة وإنترنت الأشياء لتقديم أنظمة مراقبة مدمجة وقابلة للتوسع ومنخفضة التكلفة للتطبيقات الصناعية والبيئية والزراعية والمدن الذكية.'),
  ('ST_864', 'الشخير مشكلة شائعة في كل بيت. Somnicio سهل الاستخدام ومريح ليلًا، يقضي على الشخير ويحسّن النوم ويخلّص من رائحة الفم الصباحية.'),
  ('ST_865', 'نبني أنبوب تغذية أذكى لوحدات العناية المركزة لحديثي الولادة يجمع التغذية والمراقبة الداخلية في جهاز واحد، فيقلّل الأسلاك ويبسّط الرعاية ويساعد الأطباء على دعم المواليد الأكثر هشاشة.'),
  ('ST_866', 'Improdata شريك تقني للشركات التي تريد أكثر من مجرد برمجيات، متخصص في تحويل البيانات المعقدة إلى استراتيجية واضحة، وبناء أنظمة ذكاء اصطناعي تتكيف وتتعلم، وتقديم برمجيات تحل مشكلات حقيقية على نطاق واسع.'),
  ('ST_867', 'تتيح nline للمطاعم والمقاهي استقبال الطلبات مسبقًا وتسليمها للعملاء في سياراتهم مقابل عمولة 5% بدل 15-30% في تطبيقات التوصيل، مع احتفاظ التاجر بأسعاره وعلاقته بعملائه واستلام مستحقاته يوميًا.'),
  ('ST_869', 'Mventus شركة ناشئة سعودية في التقنية الصناعية تساعد المصانع على التوريد أسرع والتشغيل بذكاء والرقمنة بفاعلية، وتربط عبر منتجاتها MCart وMPulse وMWorks وMGrid المشتريات الصناعية وحلول المصانع الذكية والتنفيذ الميداني والعمليات المتصلة في منظومة واحدة متوافقة مع رؤية 2030.'),
  ('ST_870', 'منتجات وخدمات مدعومة بالذكاء الاصطناعي صُنعت في المملكة، ننسج الذكاء في نسيج أعمالك.'),
  ('ST_874', 'تقدّم Invigilo ذكاء السلامة للقطاعات عالية المخاطر، ومنتجها SafeSuite مدير سلامة مبني على الذكاء الاصطناعي يعمل على كاميرات المراقبة الحالية دون كاميرات جديدة، ويغطي أكثر من 50 فئة من مخاطر السلامة في نحو 200 موقع في سنغافورة والسعودية والإمارات وغيرها، وحاصل على شهادة ISO/IEC 27001.'),
  ('ST_875', 'الرائد الأكثر تتويجًا بالجوائز في البلوك تشين والذكاء الاصطناعي في المنطقة، وأول استثمار لأرامكو في البلوك تشين في المنطقة والثاني عالميًا.'),
  ('ST_876', 'نقدّم لعلامات الأزياء متسوقًا شخصيًا افتراضيًا يوصي بالقطع المناسبة لمظهر كل مستخدم ويتيح التجربة الافتراضية، لرفع معدلات الشراء وتقليل المرتجعات.'),
  ('ST_877', 'مختبر أبحاث في الذكاء الاصطناعي في طليعة تطوير الذكاء الاصطناعي السيادي ومعالجة اللغات المتعددة، ومنتجه الرئيسي النموذج اللغوي المغلق Gamma Velorum بـ2.5 تريليون معامل، يتفوق في اللغات التي تُكتب من اليمين كالعربية والفارسية ومن اليسار كالإنجليزية والفرنسية، وحلّ ثانيًا إجمالًا وأولًا في المهام الوكيلية في معيار «بلسم» للنماذج العربية، مع تقنيات تشفير كمي تضمن السيادة الكاملة على البيانات.'),
  ('ST_878', 'تحوّل ISAW الأحلام الحقيقية إلى ملكية فكرية إبداعية، وتربط الحالمين بالمبدعين الباحثين عن أفكار أصيلة للأفلام والكتب والإعلانات وغيرها.'),
  ('ST_879', 'Ithaca، المنبثقة عن Odyssea، تربط الباحثين عن عمل بأصحاب العمل عبر المطابقة بالذكاء الاصطناعي والتدريب العملي، لمعالجة اضطرابات التوظيف الناتجة عن الذكاء الاصطناعي وفق نموذج Odyssea الذي غيّر حياة أكثر من 10 آلاف شخص.'),
  ('ST_882', 'نظام محاسبة متكامل يتطلب إدخال بيانات أساسية فقط دون خبرة محاسبية، مع محاسب آلي مدمج يتولى القيود اليومية وتحليل التكاليف بدقة واحترافية.'),
  ('ST_883', 'منظومة متكاملة من المنصات ونماذج الذكاء الاصطناعي: الأرشفة والتفريغ النصي والذكاء الاصطناعي المحادثي والامتثال وإدارة المحتوى.'),
  ('ST_885', 'تجعل JOVIA التجارب قابلة للإهداء: أهدِ تجربة عبر صندوق فاخر يُفتح كهدية، يحوّل القسائم الرقمية إلى هدايا هادفة لا تُنسى، تُوصل في اليوم نفسه أو خلال 90 دقيقة.'),
  ('ST_887', 'تبني مختبرات جسور مختبرات علوم افتراضية ثلاثية الأبعاد وبالواقع الافتراضي بتكلفة معقولة، تتيح للطلاب إجراء تجارب حقيقية متوافقة مع المناهج بأمان في أي وقت ومكان، بجزء بسيط من تكلفة المختبرات الفعلية.'),
  ('ST_888', 'لماذا يتعامل 35 مليون شخص مع الأنظمة السعودية بأدوات بُنيت للقانون الأمريكي والبريطاني؟ JUSTECH منظومة قانونية عربية أولًا ومراعية للشريعة مبنية للمملكة: ذكاء اصطناعي قانوني مجاني للمواطنين والمقيمين يجيب عن الأسئلة اليومية بعربية واضحة، ومحرك تحليل قضايا للمحامين، ونظام من 14 وحدة لإدارة مكاتب المحاماة، وخدمة لربط الناس بالمحامي المناسب، مع استضافة البيانات داخل المملكة وفق نظام حماية البيانات الشخصية.'),
  ('ST_894', 'كرم منصة أتمتة بالذكاء الاصطناعي للشركات، يفهم وكيلها الذكي الطلبات ويتصل بالأنظمة الخارجية مثل أنظمة العملاء والواجهات البرمجية، ويطلق سير عمل متعدد الخطوات لأتمتة العمليات.'),
  ('ST_896', 'خوارزميات شركة سعودية للذكاء الاصطناعي تبني وكلاء صوتيين ونصيين يتحدثون باسم الأعمال، وتبنيهم هنا بما يناسب طريقة العمل الفعلية هنا.'),
  ('ST_897', 'خيّال منصة ذكية تربط الفرسان بالإسطبلات وتقدّم أدوات متكاملة لإدارتها، وتبسّط الحجوزات والتدريب والزيارات والعمليات اليومية لمراكز الفروسية.'),
  ('ST_898', 'Kitchenara منصة لاكتشاف الطعام وطلبه تعتمد على الفيديو، يشاهد فيها المستخدمون فيديوهات طعام حقيقية ويطلبون فورًا، ويكسب صنّاع المحتوى من كل طلب يؤثرون فيه.'),
  ('ST_901', 'نبني منصة تعلّم وتدريب إلكتروني قابلة للتوسع تساعد المؤسسات على تصميم تدريب رقمي عالي الجودة وتقديمه وإدارته وفق المعايير الوطنية والقطاعية.'),
  ('ST_902', 'شريكك الأول في التحول الوكيلي: نسيج تنسيق آمن وقابل للتفسير يمكّن المؤسسات من نشر أساطيل من الوكلاء الذاتيين وحوكمتها على نطاق واسع، لتؤتمت الوكلاء الفوقيون من Kodamai عملياتك المعقدة من البداية إلى النهاية، أشبه بنظام تشغيل يمتد عبر بنية المؤسسة بالكامل.'),
  ('ST_904', 'كراستي منصة سعودية تعيد تعريف تجربة المشتريات الحكومية بالذكاء الاصطناعي، من إعداد كراسة الشروط حتى التعاقد.'),
  ('ST_906', 'أداة توضح لك أي الإعلانات تجلب لك عملاء حقيقيين، حتى لا تهدر أموالك.'),
  ('ST_908', 'Lingoline تطبيق لتعلّم اللغات وممارستها مع معلمين، والانضمام إلى غرف محادثة جماعية، والتواصل مع أقران لتبادل اللغة والثقافة في مجتمع واحد.'),
  ('ST_913', 'Tookeez منظومة مبنية على البلوك تشين تحوّل المكافآت إلى عملة رقمية (tkz)، لمعالجة قصور برامج المكافآت التقليدية للعملاء والشركاء والموظفين، إذ تحدد الشركات الميزانيات وتشحن الحسابات بالعملة للوصول الفوري عبر تطبيق الجوال.'),
  ('ST_916', 'MABIEN شركة سعودية للتقنية التأمينية بالذكاء الاصطناعي المتخصص، تبني بنية قرارات متخصصة للتأمين الصحي.'),
  ('ST_917', 'MachaDev Engineering مزوّد حلول تقنية متكاملة يساعد الشركات على تحويل الأفكار والتحديات المعقدة إلى حلول مبتكرة وموثوقة جاهزة للسوق، بخبرات في تطوير البرمجيات والذكاء الاصطناعي والأنظمة المدمجة وهندسة العتاد وتصميم اللوحات الإلكترونية والهندسة الميكانيكية وإنترنت الأشياء وتطوير المنتجات، من الفكرة والنموذج الأولي حتى الإنتاج.'),
  ('ST_920', 'كل محتواك الإعلامي في أداة واحدة، من فيديوهات التواصل الاجتماعي إلى صور المنتجات، مصمَّمة لصنّاع المحتوى والعلامات التجارية.'),
  ('ST_922', 'محصومة شركة تقنية سعودية تقدّم حلول البنية السحابية والتحول الرقمي والبرمجيات المؤسسية والذكاء الاصطناعي والأمن السيبراني، وتوفّر عبر «محصومة كلاود» خدمات سحابية آمنة ومُدارة، ومن منتجاتها منصة Moto لورش الدراجات النارية ومراكز خدمتها.'),
  ('ST_925', 'منار واي منصة تعلّم متوافقة مع المناهج تعتمد على الذكاء الاصطناعي والتقنيات ثلاثية الأبعاد، وتقدّم طريقة مبتكرة وتفاعلية للتعلّم لطلاب المرحلتين الابتدائية والثانوية.'),
  ('ST_926', 'Mantas شركة تقنية تأمينية تصمّم منتجات تأمين بارامترية لانقطاعات الخدمات السحابية والمخاطر الرقمية، باستخدام مُحفّزات محددة مسبقًا ومراقبة لحظية، وتعمل مع شركات التأمين والوسطاء لطرحها في السوق.'),
  ('ST_927', 'نبني منتجات لإتاحة استخدام الذكاء الاصطناعي وتأمينه وخفض تكلفته، ونساعد الشركات على تبنّي الذكاء الاصطناعي والتحول الرقمي وتحديث التقنية. MarsDevs شركة تقنية وهندسة ذكاء اصطناعي تساعد الشركات الناشئة والمنشآت الصغيرة والمتوسطة والمؤسسات على بناء منتجاتها الرقمية وتحديثها وتوسيعها، من الاستراتيجية وتجربة المستخدم إلى الهندسة والسحابة والتحسين المستمر.')
) as v(id, ar)
where s.startup_id = v.id;

update public.startups as s set startup_description_ar = v.ar
from (values
  ('ST_929', 'نقدّم حلولًا وخدمات تشغيلية للتجارة الإلكترونية للشركات، وحلول الدروبشيبينغ لنموذج البيع عبر الشركات إلى المستهلكين.'),
  ('ST_930', 'تطبيق يطابقك مع المشاريع العقارية الجديدة حسب نمط حياتك وتفضيلاتك، ويمنح المطوّرين رؤى عما يريده الناس فعلًا قبل البناء.'),
  ('ST_933', 'يساعد موصول فرق المبيعات للشركات على الوصول إلى صنّاع القرار الحقيقيين ببيانات تواصل موثّقة لإغلاق الصفقات أسرع.'),
  ('ST_934', 'MedBrain مساعد سريري بالذكاء الاصطناعي يعمل دون اتصال، يساعد العاملين الصحيين في الخطوط الأمامية على تشخيص المرضى وإدارتهم بدقة وأمان الطبيب المختص في موقع الرعاية.'),
  ('ST_935', 'شركة سعودية من الجيل الجديد في تقنيات الإعلام تمكّن المعلنين المحليين بتقنية مبتكرة، وتمنح العلامات تحكمًا كاملًا في تخطيط الحملات وتحسينها وتنفيذها ومتابعة أدائها عبر التلفزيون والإعلانات الخارجية والإذاعة والقنوات الرقمية في منصة ذكية واحدة.'),
  ('ST_936', 'في Medwrite نخصص الوقت لفهم سير عملك السريري بالتفصيل، ونخصّص المنصة لكل طبيب وكل سير عمل وكل قسم.'),
  ('ST_937', 'تحوّل MELT الجليد إلى ماء نقي: بنينا أول تقنية وأجهزة فعّالة في العالم تعتمد على التجميد لتنقية المياه دون فلاتر، إذ يتجمد الماء النقي وحده وتبقى الشوائب سائلة.'),
  ('ST_939', 'مسك والحلم منصة سوق إلكترونية مبتكرة لتطوير منظومة التقنية الرياضية مع التركيز على كرة القدم، وليست وكالة استكشاف تقليدية بل بوابة رقمية شاملة تربط المواهب الرياضية بالأندية والفرص، وتستخدم الذكاء الاصطناعي والرؤية الحاسوبية لتقييم الأداء بالفيديو، وتبني أنظمة أتمتة لإدارة الأندية.'),
  ('ST_940', 'Metis محرك لمخاطر الاستدامة والحوكمة مدعوم بالذكاء الاصطناعي، يحوّل مستندات الموردين إلى خرائط مخاطر وتقييمات موثّقة وإجراءات معالجة عملية على نطاق واسع، دون استبيانات أو إقرارات ذاتية.'),
  ('ST_942', 'منصة تحليل الأسهم الأمثل المدعومة بالذكاء الاصطناعي والمصمَّمة للسوق السعودي، بواجهة تفاعلية سهلة وتحليل مبسّط للجميع.'),
  ('ST_945', 'نبني MRFQ، منصة لإدارة العقارات بالذكاء الاصطناعي تشغّل المباني على مدار الساعة وتقدّم خدمات الصيانة بتجربة متكاملة وسلسة.'),
  ('ST_946', 'نبني مستند: نظام سعودي لإدارة المستندات بالذكاء الاصطناعي يجعل تخزين ملفات الشركة والعثور عليها وتأمينها أمرًا سهلًا.'),
  ('ST_949', 'Musicality Beats أول تطبيق ألعاب موسيقية للجوال على iOS وAndroid يربطك بالموسيقى العربية عبر ألعاب ممتعة وتعليمية، برؤية للحفاظ على التراث الموسيقي العربي وتمكين كل مستخدم من التواصل مع جذوره، آلة تلو الأخرى وقصة تلو الأخرى.'),
  ('ST_951', 'مُتِم سوق موارد بشرية بالذكاء الاصطناعي يربط الشركات بمختصين موثّقين في الموارد البشرية يفهمون أعمالها وقطاعها وثقافتها واحتياجات السوق المحلي.'),
  ('ST_952', 'MyCatering سوق متخصص في خدمات الضيافة والتموين يربط الأفراد والشركات والجهات بالمطاعم والمقاهي التي تقدّم هذه الخدمات للفعاليات والمناسبات، ويبسّط اكتشافها ومقارنتها وتخصيصها وحجزها وجدولتها وإدارتها في تجربة رقمية واحدة.'),
  ('ST_955', 'نانو بالم شركة تقنيات عميقة في الطب النانوي مقرها الرياض ومنبثقة عن مدينة الملك عبدالعزيز للعلوم والتقنية، تطوّر الجيل القادم من تقنيات توصيل الأدوية، إذ يصمّم الذكاء الاصطناعي عبر منصتها EnsaliX جسيمات دهنية نانوية مخصصة ثم تُصنَّع بالطباعة النانوية لتحقيق ثبات وأمان واستهداف دقيق لأعضاء وخلايا محددة خارج الكبد، وتتعاون مع شركات التقنية الحيوية والأدوية والمؤسسات البحثية.'),
  ('ST_960', 'ذكاء اصطناعي يقيس المشاريع السكنية ويحسب كمياتها ويسعّرها في دقائق، بنماذج رؤية وخوارزميات خاصة تقرأ الرسومات الواقعية، ومحرك يطابق كل كمية مع أفضل منتج متاح لدى الموردين بأسعار اليوم، من القياس حتى التقدير المسعّر. شركة تقنيات عميقة بريطانية مدعومة من وكالة الفضاء الأوروبية.'),
  ('ST_961', 'نبني وكلاء أمن سيبراني بالذكاء الاصطناعي.'),
  ('ST_962', 'Nexera منصة رقمية مبتكرة من Empower تساعد المؤسسات على تحويل الاستراتيجية إلى تنفيذ قابل للقياس ونتائج على مستوى مجالس الإدارة، وتجمع التخطيط الاستراتيجي وإدارة الأداء وإدارة المشاريع والمحافظ واللجان والمجالس في منصة موحّدة، لتعزيز اتخاذ القرار والحوكمة والشفافية والأداء المؤسسي.'),
  ('ST_968', 'Novent منصة تقنية للفعاليات تبسّط عملياتها عبر تسجيل الحضور الذكي وإنشاء البطاقات آليًا وتتبع الحضور وإصدار الشهادات والتحليلات اللحظية، لمساعدة المنظمين على رفع الكفاءة وتفاعل الحضور.'),
  ('ST_969', 'منصة أمن أجهزة طرفية مدعومة بالذكاء الاصطناعي مع اكتشاف واستجابة لحظيين، مبنية للمرونة السيبرانية عبر حلولنا الاستباقية الحاصلة على براءات اختراع.'),
  ('ST_970', 'يساعد Nuelink المؤسسين والمنشآت الصغيرة والوكالات على التخطيط مرة واحدة وأتمتة النشر على جميع منصات التواصل الاجتماعي، ليعمل المحتوى في الخلفية بينما يركزون على أعمالهم.'),
  ('ST_971', 'تبني نُهى نظامًا ذكيًا لإدارة المدارس من الروضة حتى الثانوية في المنطقة مدعومًا بالذكاء الاصطناعي، يجعل التدريس أسهل والتعلّم مخصصًا والتواصل سلسًا للجميع.'),
  ('ST_972', 'نمو منصة جاهزية للعمل مدعومة بالذكاء الاصطناعي للشباب من 15 إلى 18 عامًا، تساعد الطلاب على بناء هويتهم المهنية قبل التخرج عبر محاكاة وظائف واقعية مع أصحاب العمل، و«غرفة العرض» لتطوير مهارات التواصل بتغذية راجعة فورية، وجواز مسار مهني موثّق يجمع مهاراتهم وإنجازاتهم، لتربط المدارس والطلاب وأصحاب العمل.'),
  ('ST_973', 'تقدّم Objects AI رؤى ذكاء اصطناعي تضع الخصوصية أولًا: تحليلات سريعة دون تلامس وتوصيات مخصصة للتجزئة والعافية والرعاية الصحية والتجارب الافتراضية.'),
  ('ST_974', 'أولو: منظومة المواهب السعودية لتدريب الكفاءات الجاهزة للمستقبل وربطها وتوظيفها.'),
  ('ST_975', 'علقان نظام تشغيل للأعمال يتيح للشركات ربط العملاء والمبيعات والمشاريع والموظفين والمالية والدعم والمشتريات والعمليات وإدارتها في نظام واحد.'),
  ('ST_977', 'Operate مساعد ذكي يرقمن إجراءات التشغيل القياسية ويؤتمتها للمشغّلين متعددي الفروع.'),
  ('ST_978', 'نظام تشغيل وكيلي يتيح لك نشر وكلاء الذكاء الاصطناعي وإدارتهم كأعضاء مستقلين فعليين في فريقك، دون كتابة أي أوامر أو سطر برمجي.'),
  ('ST_979', 'أول منصة شاملة للطاقة الشمسية في المملكة مدعومة بالذكاء الاصطناعي: من التصميم الفوري للأسطح إلى مطابقة المقاولين، نجعل التحول إلى الطاقة الشمسية سريعًا وميسورًا ودون عناء للمنازل والمزارع والجهات غير الربحية.'),
  ('ST_981', 'تجمع Optiqb بين عتاد «واقي شاشة بصري» وبرمجيات «محرك تحويل لحظي ثلاثي الأبعاد» لتتيح تجربة ثلاثية الأبعاد على الجوال بالعين المجردة لمحتوى غير محدود.'),
  ('ST_982', 'معرّف حل برمجي ذكي لتتبع الأصول المادية وإدارة المخزون تستخدمه جهات كبرى في المملكة، ويساعد على جرد الأصول وتتبعها بسرعة دون الحاجة إلى المسح المباشر، ومن عملائه شركة البحر الأحمر الدولية والجامعة السعودية الإلكترونية والمركز الوطني لقياس أداء الأجهزة العامة (أداء)، وهو من خريجي برنامج مسك Launchpad ومسرّعة The Garage.'),
  ('ST_983', 'Polly من Parrots ذكاء اصطناعي متعدد الوسائط (تخطيط الدماغ والكلام والعلامات الحيوية) يكتشف التدهور الإدراكي قبل ظهوره، ويخصّص الرعاية، ويعمل من المنزل إلى العيادة وشركات الأدوية. الاكتشاف المبكر يعني وقتًا أطول.'),
  ('ST_986', 'تطبيق واحد يساعد أصحاب الحيوانات الأليفة على إدارة حيواناتهم وطلب الخدمات والمنتجات.'),
  ('ST_987', 'اختبار اختراق مؤتمت على مدار الساعة مع استخبارات تهديدات سيبرانية محلية، لتعرف المؤسسات دائمًا ما يمكن للمهاجمين استغلاله وأي التهديدات تهم فعلًا في المملكة.'),
  ('ST_988', 'نصنع في Phaseshift نوعًا جديدًا من المواد فائقة الرقة يُسمى الأسطح البصرية الفوقية، سيغيّر الممكن في مجالات مثل الحوسبة الكمية والاستشعار المتقدم، بهدف تصغير المعدات الكبيرة اليوم وتحسينها وجمعها على شريحة واحدة صغيرة، مع تطبيقات في الليزر القوي والسيارات ذاتية القيادة.'),
  ('ST_990', 'PIXEL شركة ناشئة في الرياض تبني بطاقات أعمال ذكية بديلة للبطاقات الورقية: المس بطاقتك بأي جوال لتُحفظ بيانات تواصلك فورًا دون تطبيق أو كتابة أو ورق، مع إمكانية تحديث البيانات في أي وقت ونظام حماية يمنع كشف معلوماتك، دعمًا لأهداف التحول الرقمي في رؤية 2030، ببطاقات للأفراد وبطاقات مخصصة مع لوحة مشتركة للفرق والشركات.'),
  ('ST_991', 'بكسل لاند استوديو في الرياض للتقنيات التعليمية والواقع الممتد، يغيّر طريقة تفاعل الطلاب مع العلوم والرياضيات عبر التعلّم التفاعلي ثلاثي الأبعاد، ويحوّل الدروس المجردة إلى مغامرات رقمية ملموسة. منصته PixelLand AR تستبدل المواد الثابتة بمحتوى واقع معزز وألعاب تفاعلية تحيي المناهج، وصُنّف ضمن أفضل 50 شركة ناشئة في برنامج مسك Launchpad.'),
  ('ST_994', 'تبني ProTag منصات ذكاء بيانات تحوّل البيانات المعقدة إلى رؤى واضحة وإجراءات فعلية، لمساعدة المؤسسات على فهم بياناتها واتخاذ قرارات أفضل وأسرع.'),
  ('ST_995', 'Psynary منصة ذكاء سريري للاكتئاب والقلق والرفاه في بيئة العمل، تربط التقييم والمراقبة المستمرة ودعم قرار الطبيب في رحلة واحدة آمنة، لتساعد فرق الرعاية على اكتشاف عدم فاعلية العلاج والاستجابة مبكرًا، وتقدّم لأصحاب العمل رؤى محمية الخصوصية عن القوى العاملة دون أي بيانات سريرية فردية، باللغتين العربية والإنجليزية.'),
  ('ST_997', 'أول سوق لصنّاع المحتوى في المملكة: مع Push Brands تصنع العلامات التجارية إعلانات التواصل الاجتماعي أسرع بثلاث مرات.'),
  ('ST_998', 'تبني Q9 Labs منتجات ذكاء اصطناعي عملية تؤتمت أعمالًا حقيقية في المكالمات والتوظيف ورحلات العملاء والتعاون وسير العمل والتعليم.'),
  ('ST_999', 'نحوّل السير الذاتية غير الموثوقة إلى ملفات موثّقة عبر فحص آلي للمؤهلات وتقييمات مهارات بالذكاء الاصطناعي، لنقدّم لأصحاب العمل مرشحين مفرزين مسبقًا يمكن الوثوق بهم.'),
  ('ST_1000', 'QuantiCor للأمن السيبراني المقاوم للحوسبة الكمية: منصة PQVault لحماية البيانات والمستندات والأجهزة وسير التعاون الحساسة طوال دورة حياتها بالتشفير والتحكم في الوصول والمشاركة الآمنة والتواقيع والموافقات والتدقيق، إضافة إلى PQCryptoGuard لاكتشاف الأصول التشفيرية وتقييم مخاطرها، وPQInfraProtect لإضافة حماية مقاومة للحوسبة الكمية للبنية التحتية القائمة دون تغييرات كبيرة.'),
  ('ST_1003', 'الحلول الرقمية المبتكرة شركة سعودية لتقنيات التجزئة تبني منظومة «رشيد» التي تستبدل الإيصالات الورقية بتجربة رقمية ذكية، وجهازها TapCeipt يقدّم إيصالات فورية دون تلامس عند الدفع ويعمل دون إنترنت ودون ربط بنقاط البيع، وتطبيقها يحوّل كل معاملة إلى رؤى وعروض وإدارة للمصروفات ومحفظة للإيصالات.'),
  ('ST_1004', 'REG-1 منظومة مبنية على الذكاء الاصطناعي توحّد الحوكمة والشؤون القانونية والمخاطر والامتثال في منصة ذكية واحدة، تمنح المؤسسات متعددة الولايات القضائية مصدر حقيقة واحدًا موثوقًا باستمرار، مع طبقة وكلاء تعمل على مدار الساعة في الفحص والمسح والتحقق، ما يقلّل الجهد اليدوي حتى 90%، ويغطي أكثر من 240 ولاية قضائية، بتصميم معياري يبدأ بالوحدات التي تحتاجها.'),
  ('ST_1005', 'تخيّل زميلًا بالذكاء الاصطناعي يعيش في صندوق البريد المشترك لشركتك، يتولى الأعمال المملة من فرز وتصفية وصياغة ردود، فتكتفي بالمراجعة والإرسال.'),
  ('ST_1006', 'تحمي نماذج Resemble AI لكشف التزييف العميق الجهات الحكومية والمؤسسات من انتحال الشخصية والاحتيال والتضليل بالذكاء الاصطناعي، وتكشف الصوت والفيديو والصور المولّدة بالذكاء الاصطناعي لحظيًا، مع إمكانية النشر سحابيًا أو محليًا لتلبية متطلبات السيادة على البيانات، وحققت دقة 99.5% في تقييم مستقل.'),
  ('ST_1008', 'Rezlytix منصة تقنيات عميقة مبنية على الذكاء الاصطناعي تحدث نقلة في سوق التنقيب عن الطاقة البالغ 325 مليار دولار بمعالجة نسبة الآبار الجافة البالغة 50%، عبر محركها DIME AI بدقة تنبؤ تتجاوز 80%، وقد عالجت بيانات أكثر من 6,000 كيلومتر مربع لعمالقة منهم أرامكو السعودية ومؤسسة البترول الكويتية وENI.'),
  ('ST_1009', 'رزمة منصة رقمية تقدّم التقسيط كخدمة للمشتريات عالية القيمة، دون فوائد باستخدام البطاقات الائتمانية الحالية، لمدة تصل إلى 12 شهرًا، ومتوافقة مع الشريعة ودون فحص ائتماني.'),
  ('ST_1015', 'رويال روم كير شركة سعودية في التقنية العقارية وخدمات الضيافة تغيّر طريقة تشغيل عقارات الإيجار قصير المدى والضيافة وصيانتها، عبر منصة تقنية تربط تشغيل العقارات والتدبير المنزلي والصيانة وتجهيز الوحدات للضيوف في تجربة واحدة سلسة لرفع الكفاءة والجودة.'),
  ('ST_1017', 'موسوعة ويكيبيديا خاصة بعائلتك.'),
  ('ST_1018', 'منصة للشركات تقدّم تقييمات مخصصة للمرشحين مدعومة بالذكاء الاصطناعي.'),
  ('ST_1021', 'خدمات محاسبة مدعومة بالذكاء الاصطناعي.'),
  ('ST_1022', 'ساريات شركة سعودية مرخّصة في التقنية العقارية تبني الطريق من الاستئجار إلى التملّك: عقد واحد بدفعات شهرية، كل دفعة فيها جزء لاستخدام العقار وجزء يتراكم ملكيةً، وتنتقل الملكية في نهاية المدة دون دفعة أولى إلزامية، وفق صيغة الإجارة، للعقارات السكنية والتجارية، ومرخّصة من الهيئة العامة للعقار.'),
  ('ST_1024', 'Scene منصة اجتماعية بالذكاء الاصطناعي لمحبي الأفلام والمسلسلات: تابع كل ما تشاهده، واكتب مراجعات بالصور، واكتشف توصيات تناسب ذوقك، وابنِ ملفًا شخصيًا يحكي رحلتك الترفيهية.'),
  ('ST_1025', 'Schoolz شركة تقنية للتنقل الذكي تغيّر نقل طلاب المدارس والجامعات والموظفين في المنطقة، بخدمات نقل مُدارة ومنصتها Routz لإدارة الحافلات والمسارات والسائقين والطلاب والسلامة، مع تتبع لحظي وتنبيهات وتحسين المسارات بالذكاء الاصطناعي. أكملت أكثر من 4.5 ملايين رحلة، وتتوسع من مصر إلى الخليج مع تركيز على المملكة.'),
  ('ST_1027', 'Byondbites منظومة للطعام والتغذية والعافية مدعومة بالذكاء الاصطناعي، تجمع مسح المكونات والوجبات والوصفات المخصصة وتتبع التغذية والإرشاد الذكي عبر «أيرا» وخطط الوجبات والتمارين المخصصة، لتربط الطبخ اليومي بدعم صحي مخصص في منصة واحدة عملية.'),
  ('ST_1028', 'الاستعداد لاختبارَي القدرات والتحصيلي قد يكون مرهقًا دون التوجيه المناسب، وقد بُني تطبيق سمو لتسهيل هذه الرحلة بتجربة تعلّم مخصصة لكل طالب تساعده على التدرّب بفاعلية ومتابعة تقدّمه والاستعداد بثقة.'),
  ('ST_1030', 'تجعل SentiVue كل محادثة متعددة اللغات: ذكاء اصطناعي صوتي للمؤسسات يشغّل وكلاء صوتيين، ويترجم المكالمات الهاتفية مباشرة، ويدعم الفعاليات متعددة اللغات، ويتكامل مع أنظمة الاتصالات والصوت الحالية، لخدمة العملاء بعدة لغات دون فريق أو قائمة انتظار لكل لغة.'),
  ('ST_1031', 'منصة برمجية شاملة مدعومة بالذكاء الاصطناعي لتبسيط إدارة الأساطيل من البداية إلى النهاية.'),
  ('ST_1032', 'AskSary Studio شركة تقنية مستقلة في البحرين تبني منصات ذكاء اصطناعي متقدمة، أبرزها AskSary Studio، بيئة موحّدة متعددة النماذج للإنتاجية والإبداع تجمع المحادثة والذاكرة المستمرة والصوت وتوليد الصور والفيديو والموسيقى والعروض والبرمجة وتطوير الألعاب ثلاثية الأبعاد في مكان واحد، إضافة إلى ARIA، منصة عمليات أمنية مبنية على الذكاء الاصطناعي بصلاحيات تتدرج حسب الأداء تحت حوكمة وإشراف بشري، وقابلة للتشغيل محليًا لمتطلبات سيادة البيانات.'),
  ('ST_1033', 'موقع يستخدم الذكاء الاصطناعي لقراءة القوائم المالية ومراقبة الأسواق ودعم رقابة التداول بإبراز ما يهم فعلًا.'),
  ('ST_1034', 'تبني Signvrse شخصيات افتراضية ثلاثية الأبعاد بالذكاء الاصطناعي للترجمة الفورية إلى لغة الإشارة والتعليق النصي، لجعل التواصل الرقمي متاحًا للصم.'),
  ('ST_1036', 'Sinaholz استوديو متميز لحلول الواقع الممتد والذكاء الاصطناعي، متخصص في التوائم الرقمية عالية الدقة لقطاعي العقار والمؤسسات، ومبتكر منصة Vistara لإدارة البيئات المكانية دون برمجة، التي تتيح للمطوّرين استضافة البيئات ثلاثية الأبعاد والجولات الافتراضية الموجّهة بالذكاء الاصطناعي ونشرها وتحديثها.'),
  ('ST_1038', 'سيادة AI تبني طبقة تنفيذ محكومة للمؤسسات: تصف الشركة النتيجة المطلوبة، فتنشئ سيادة موظفين أذكياء متخصصين يفهمون سياق العمل ويخططون وينفذون عبر الأنظمة المعتمدة ويقدّمون دليلًا على كل إجراء، بصلاحيات واضحة وموافقة بشرية على الإجراءات الحساسة، للعمل باللغتين العربية والإنجليزية مع مراعاة السياق التنظيمي السعودي.'),
  ('ST_1041', 'منصة القرارات الذكية للتجميل والعافية: تحوّل Skin Smart خيارات التجميل والعافية المعقدة إلى قرارات مخصصة وقابلة للتفسير، لتساعد الناس على معرفة ما يناسبهم والشركات على تقديم التجربة المناسبة على نطاق واسع.'),
  ('ST_1042', 'تطوّر حلول القيادة الذكية تقنيات سيارات بالذكاء الاصطناعي تربط ملاك المركبات والورش وموردي القطع ومشغّلي الأساطيل في منصة ذكية واحدة، وحلها الرئيسي «صيانتك» يبسّط التشخيص والصيانة وتوفير القطع وتوصيات العناية التنبؤية بالمركبة.'),
  ('ST_1043', '3B منصة تقنية ذكية متكاملة للمدارس تستخدم الأساور الذكية والمدفوعات الرقمية وحلول الحضور لتبسيط العمليات المدرسية اليومية وتعزيز السلامة، فتدير حضور الطلاب والمشتريات غير النقدية داخل المدرسة وحدود الإنفاق، وتربط المدارس والطلاب وأولياء الأمور في منظومة رقمية موحّدة.'),
  ('ST_1045', 'نبني تقنية ذكية تساعد المدن ومشغّلي النفايات على رؤية ما يحدث داخل الحاويات لحظيًا، ليجمعوا النفايات عند الحاجة فقط ويخفضوا التكاليف ويحافظوا على نظافة المدن.'),
  ('ST_1048', 'منصة ذكاء اصطناعي للمتاجر الإلكترونية: صندوق وارد واحد لواتساب وإنستغرام وتيك توك مع إتمام الشراء داخل المحادثة، وردود ذكية، ونشر المحتوى، وشراء الإعلانات من شاشة واحدة.'),
  ('ST_1051', 'تحوّل صورة الأرض بيانات الأقمار الصناعية إلى خرائط شبه لحظية تكشف الحرارة والتلوث ومخاطر الأمراض، لتساعد الحكومات على منع الأزمة الصحية القادمة قبل وقوعها.'),
  ('ST_1052', 'SorsX منصة توظيف بالذكاء الاصطناعي تساعد الشركات على استقطاب الكفاءات المناسبة وفرزها ومقابلتها أسرع بنسبة تصل إلى 75%، وتجمع البحث عن المواهب والفرز الآلي والمقابلات متعددة اللغات بالذكاء الاصطناعي وتتبع المتقدمين في منصة واحدة، وتعمل في الولايات المتحدة وتركيا وتتوسع في المنطقة بدءًا من المملكة.'),
  ('ST_1054', 'نبني WooHoo®، مساعدًا بالذكاء الاصطناعي التوليدي داخل غرف الفنادق، وحلولًا رقمية ذكية تجعل الضيافة والسفر سلسين ومتصلين ومخصصين.'),
  ('ST_1056', 'ستامب شركة ناشئة في تقنيات الامتثال تقدّم منصة بواجهة واحدة تؤتمت التزامات الشركات بالكامل، بهدف تحرير الشركات السعودية من العبء التنظيمي بربط عملياتها مباشرة بالأنظمة الحكومية عبر أتمتة ذكية: واجهة واحدة لإدارة الامتثال، وتتبع الالتزامات وتنفيذها تلقائيًا، وتكامل مع البوابات الحكومية.'),
  ('ST_1057', 'منصة ذكاء اصطناعي سيادية للقطاعات عالية التنظيم، حيث يجب أن تبقى البيانات محليًا وأن تكون رؤى الذكاء الاصطناعي قابلة للتدقيق والتفسير ومتوافقة مع الأنظمة.'),
  ('ST_1058', 'ستارفانيا استوديو ألعاب مستقل في المملكة يصنع عوالم خيالية عالية الجودة تلهم اللاعبين، تأسس عام 2022، ونال جائزة أفضل شركة ناشئة في الألعاب في المنطقة عام 2024، وفازت لعبته الأولى «بهموت وشجرة الواق واق» بجوائز منها أفضل لعبة سعودية في جوائز TrueGaming 2025.'),
  ('ST_1061', 'ماذا لو كان توريد المنتجات الصناعية بسرعة بحث Google؟ Stock On Fire أول سوق رقمي للشركات يرقمن المشتريات الصناعية في الخليج، بشريط بحث واحد يغطي ستة قطاعات: السلامة من الحرائق والكهرباء والتكييف والأتمتة والأمن والميكانيكا، مع أكثر من مليون منتج ومخزون بقيمة تتجاوز 40 مليون دولار، وأكثر من 12,000 طلب منجز في 6 دول، ويتوسع الآن إلى مصر.'),
  ('ST_1062', 'نبني كونسيرج رقميًا بالذكاء الاصطناعي للفنادق يتيح للضيوف طلب خدمة الغرف والسبا والجولات والمرافق فورًا بمسح رمز QR، دون تطبيق أو تنزيل.'),
  ('ST_1068', 'تبني TachyHealth حلولًا من الجيل القادم لدعم الرعاية الصحية القائمة على القيمة لشركات التأمين ومقدّمي الخدمات، بالذكاء الاصطناعي وعلم البيانات.'),
  ('ST_1069', 'تفادي شبكة تحمي المتاجر الإلكترونية من العملاء الوهميين وذوي المخاطر وغير الجادين قبل أن يتسببوا في خسائر.'),
  ('ST_1071', 'وفّر حتى 90% من وقت فرز المرشحين مع Talboost، الذكاء الاصطناعي الوحيد الذي يحبه مسؤولو التوظيف: دون تكامل تقني، ويُطبَّق خلال 24 ساعة، ومصمَّم ليكون الحل الأكثر أخلاقية وإنسانية في السوق.'),
  ('ST_1072', 'حلول الحوكمة والمخاطر والامتثال للشركات الناشئة.'),
  ('ST_1074', 'مارد شبكة سعودية مدعومة بالمصرفية المفتوحة توحّد العروض المرتبطة بالبطاقات والنقاط والخصومات في تطبيق واحد سلس، لتساعد العملاء على التوفير والتجار على جذب المشترين المناسبين.'),
  ('ST_1076', 'تك إيرا شركة لدمج الروبوتات والأتمتة الصناعية تحوّل عمليات المؤسسات بأنظمة ذكية ذاتية، وتقدّم أساطيل روبوتية متكاملة وخلايا مناولة عالية السرعة وأتمتة بالذكاء الاصطناعي للمستودعات وخطوط التصنيع، وروبوتات خدمية للتنظيف والتوصيل في المراكز التجارية والمطارات، وحلول تنظيف الألواح الشمسية والدوريات الأمنية الذاتية، مع تنفيذ متكامل ودعم ميداني محلي.'),
  ('ST_1077', 'تبني Techvention برمجيات لإدارة المستشفيات بالذكاء الاصطناعي تؤتمت سير العمل وتوحّد بيانات المرضى وتمكّن الأطباء والإداريين والمرضى عبر مساعدين أذكياء.'),
  ('ST_1078', 'TeknoVerse نظام تعليمي في الميتافيرس ينشئ بيئة تعلّم إلكتروني تفاعلية حقيقية باستخدام الواقع الافتراضي والمختلط والذكاء الاصطناعي.'),
  ('ST_1080', 'تحوّل Texula مخلفات أشجار الموز إلى ألياف عالية الأداء قابلة للتحلل للمنسوجات والتغليف، صديقة للبيئة وبجودة عالية وسهلة الدمج في خطوط الإنتاج الحالية.'),
  ('ST_1083', 'أبحاث سوق مدعومة بالذكاء الاصطناعي لقرارات أعمال أسرع وأذكى.'),
  ('ST_1084', 'تستخدم منصتنا PolyEdge شبكات الاتصالات الخلوية الحالية للرادار السلبي والوعي بالموقف بالذكاء الاصطناعي، فتكتشف الطائرات المسيّرة والمركبات والأشخاص دون إرسال إشارات أو انتهاك الخصوصية.'),
  ('ST_1087', 'توب طلّة منصة مدعومة بالذكاء الاصطناعي تغيّر صالونات التجميل في المملكة، من الحجوزات الذكية إلى التسويق المؤتمت ومخزون يدير نفسه. أعمال التجميل بمستوى أعلى.'),
  ('ST_1088', 'تقدّم Transpioneers خدمات ترجمة مخصصة للعالم، بتقنية متطورة معززة بالذكاء الاصطناعي ومترجمين بشريين خبراء.'),
  ('ST_1090', 'Trellis Work شركة استشارات وتنفيذ في الذكاء الاصطناعي تأسست في الرياض للشركات المتوسطة السعودية، تجعل الشركات مبنية على الذكاء الاصطناعي: الاستراتيجية والنشر وإدارة التغيير. شريك معتمد لدى Anthropic وOpenAI وIBM، ممولة ذاتيًا من إيراداتها منذ اليوم الأول، وتخدم عملاء في السعودية والولايات المتحدة في الرعاية الصحية والعقار والتعليم والخدمات المهنية، ولديها ثلاثة منتجات منها «حمى» للحوكمة والمخاطر والامتثال و«مزيد» لإدارة الأصول.'),
  ('ST_1091', 'تتحاور True Nexus مع البروتينات لتُظهر أفضل وظائفها، باستخدام الذكاء الاصطناعي وإضافة طبقة كمية لأول مرة، لتسريع الابتكار في قطاع الغذاء وتحسينه.'),
  ('ST_1092', 'شركة ناشئة من الجيل الجديد في اختبار البرمجيات تساعد الفرق على الإطلاق أسرع بحلول ضمان جودة موثوقة وقابلة للتوسع وفعّالة بالذكاء الاصطناعي. اختبار أذكى وبرمجيات أقوى.'),
  ('ST_1093', 'تربط Unipal العلامات التجارية بأهم شريحة من العملاء، الشباب، عبر عروض ومزايا حصرية في تطبيق تفاعلي ومخصص.'),
  ('ST_1094', 'تأسست UPDIVE لتقديم الأمن السيبراني للجهات الحكومية والخاصة، وأطلقت عام 2020 منتجها الأول لمنع تسرب البيانات، ثم نظام إدارة المعلومات والأحداث الأمنية عام 2023، وتطوّر الآن حلًا للكشف والاستجابة على الأجهزة الطرفية، لحماية المؤسسات في قطاعات الحكومة والرعاية الصحية والمالية وغيرها في آسيا الوسطى والمنطقة.'),
  ('ST_1096', 'نبني تقنيات التنقل وحلول السيارات المتصلة بالكامل، من إدارة الأساطيل والأصول إلى لوحة قيادة السيارة، بشراكات قوية مع ذراعَينا في إنترنت الأشياء والذكاء الاصطناعي.'),
  ('ST_1097', 'تطوّر Valere Therapeutics علاجات مناعية دقيقة لسد فجوات ملحّة في رعاية سرطان الثدي، خاصة في منطقة الخليج، بمنصة قابلة للتوسع تستهدف المقاومة المناعية في الأورام الصلبة بدءًا من سرطان الثدي الثلاثي السلبي، بدمج التحليل المناعي المتقدم مع أدوية حيوية وعلاجات خلوية مصنّعة محليًا.'),
  ('ST_1102', 'VGA Softwares شركة تقنية متخصصة في تطوير البرمجيات المخصصة والحلول الرقمية، تساعد الشركات على تحويل أفكارها إلى تطبيقات ويب وجوال قابلة للتوسع وحلول ووكلاء ذكاء اصطناعي، ومنصات رقمية تحسّن العمليات وتجربة العملاء والنمو.')
) as v(id, ar)
where s.startup_id = v.id;

update public.startups as s set startup_description_ar = v.ar
from (values
  ('ST_1103', 'تأمين الأنظمة، واكتشاف الثغرات، وتوعية الموظفين بالأمن السيبراني.'),
  ('ST_1104', 'الصوت مؤشرًا حيويًا لصحتنا: طوّرت Virtuosis، المنبثقة عن المعهد الفدرالي السويسري للتقنية في لوزان والفائزة بجائزة Microsoft لأفضل شركة ناشئة لعام 2023، نماذج ذكاء اصطناعي معتمدة سريريًا تكشف وتتابع ما يصل إلى 25 حالة صحية منها الاكتئاب وباركنسون وألزهايمر وصحة القلب والتنفس من تسجيل صوتي مدته 30 ثانية، وأجرت أكثر من مليون فحص صوتي.'),
  ('ST_1106', 'Voiset مخطط يومك بالذكاء الاصطناعي يعيد لك ساعتين كل يوم: مدير مهام صوتي من سلوفاكيا يثق به أكثر من 6,000 فريق ومهني، يحوّل كلامك إلى مهام مجدولة ويجد الوقت الأنسب في تقويمك، ويدعم أكثر من 60 لغة، مع روابط حجز ذكية وتوحيد تقويمات Google وOutlook وZoom وأدوات للفرق.'),
  ('ST_1107', 'Vora (vora.qa).'),
  ('ST_1109', 'Vyro شركة ناشئة عمانية تجعل التسوق الإلكتروني أكثر تفاعلًا بتقنية التجربة الافتراضية، فيرى العملاء فورًا كيف تبدو المجوهرات والنظارات والساعات والإكسسوارات عليهم قبل الشراء، ما يرفع مبيعات التجار ويقلّل المرتجعات.'),
  ('ST_1110', 'وافي الصحية حل بالذكاء الاصطناعي التوليدي يتيح حجز جميع خدمات الرعاية الصحية من منصة واحدة بنقرة واحدة.'),
  ('ST_1112', 'رحلات أصيلة يختارها أبرز مدوني السفر وينفّذها خبراء محليون، بمساعدة الذكاء الاصطناعي.'),
  ('ST_1113', 'Waspito منصة ثلاثية الأطراف للمرضى ومقدّمي الخدمة وجهات الدفع، يدير فيها ذكاء اصطناعي صحي أفريقي تقديم الرعاية وتمويلها في وسط أفريقيا وغربها: يحصل المرضى على الرعاية دون دفع مسبق، ويُدفع لمقدّمي الخدمة فور اعتماد المطالبة، وتتحكم جهات الدفع لحظيًا في الاحتيال والهدر، وتخدم نحو 1.1 مليون مريض في الكاميرون وساحل العاج.'),
  ('ST_1115', 'تساعد WeekOne الشركات على تحويل الموظفين الجدد إلى أعضاء منتجين أسرع، باستبدال التهيئة اليدوية المرهقة بنظام منظم مدعوم بالذكاء الاصطناعي يرشد الموظفين والمديرين والموارد البشرية.'),
  ('ST_1119', 'تطبيق ومنصة لترميز العقارات رقميًا يساعدانك على تنويع محفظتك الاستثمارية وتحقيق أهدافك.'),
  ('ST_1121', 'تحوّل WayCare أي سيارة إلى مركبة ذكية متصلة بالذكاء الاصطناعي وجهاز OBD، لتكون الحارس الرقمي لسيارتك للصيانة التنبؤية والولاء.'),
  ('ST_1122', 'Xorris منصة مكالمات صوتية بالذكاء الاصطناعي تؤتمت محادثات العملاء عبر وكلاء صوتيين أذكياء، وتبسّط المبيعات ودعم العملاء وتأهيل العملاء المحتملين وجدولة المواعيد والتوظيف والتحصيل بمحادثات طبيعية قريبة من البشر، مع مكالمات واردة وصادرة ومحادثات متعددة اللغات واستنساخ الصوت والتكامل مع أنظمة العملاء والتحليلات.'),
  ('ST_1123', 'نبني ألعابًا فريدة وأدوات لدعم استوديوهات الألعاب.'),
  ('ST_1124', 'زان منصة برمجية سعودية للشركات تدير العمليات الرقمية للصالونات والمنتجعات الصحية والعيادات والمراكز الصحية، وتجمع الحجز ونقاط البيع وإدارة العملاء والموارد البشرية والمخزون والمالية والتسويق والولاء والتقارير وإدارة الفروع المتعددة في منصة مركزية واحدة.'),
  ('ST_1125', 'زكن منصة ذكاء اصطناعي تتحقق من أفكار الأعمال قبل إطلاقها بتحليل السوق وبناء النماذج الأولية وتشغيل إعلانات تجريبية، وتقديم قرارات واضحة مبنية على البيانات بالمضي أو التوقف.'),
  ('ST_1127', 'Sla'),
  ('ST_1128', 'نتولى التعقيد لتنساب تجارتك بسلاسة: منصة رقمية للتخليص الجمركي في المملكة.')
) as v(id, ar)
where s.startup_id = v.id;

